COLLDATA("asabahur","ur",[[8505,"§۸۵۳۰ ۔ محمد بن عبد الرحمن (مولی رسول اللہ صلی اللہ علیہ وسلم)(1)\nمطین، عبدالرحمن مروزی اور باوردی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق یحییٰ بن ایوب بحوالہ محمد بن عبد الرحمن مولی رسول اللہ صلی اللہ علیہ وسلم کا یہ روایت کی ہے جس نے کسی عورت کا پردہ کھولا اس پر اس کا مہر واجب ہے۔ اسے ابو نعیم(2) نے بطریق مطین نقل کیا ہے، فرماتے ہیں: میرے نزدیک اس کی اسناد متصل نہیں، میرے خیال میں وہ محمد بن عبد الرحمن بن سلمانی ہیں۔ ابو موسیٰ نے ان کا تعاقب کیا ہے کہ جو انہوں نے گمان کیا ویسا نہیں ہے۔ ابن فتحون نے استیعاب میں اپنے استدراک میں ان کا ذکر کیا ہے۔ یحییٰ بن عبدالوہاب بن مندہ نے اپنے دادا کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے اور وضاحت کی ہے کہ وہ تابعی ہیں۔ اور ان کا تذکرہ کرنے کا یہ عذر پیش کیا ہے کہ انہیں خطرہ تھا کہ مذکورہ لوگوں کی کتب میں جو لکھا ہے اس سے کوئی شخص دھوکا کھا کر یہ گمان کر لے گا کہ انہوں نے انہیں نظر انداز کر دیا۔ پھر اس لیے ان کا ذکر کر کے ان کی وضاحت کر دی۔\nپھر دوسرے طریق سے بحوالہ یحییٰ بن ایوب اس سند سے نقل کیا ہے۔ فرماتے ہیں: بحوالہ محمد بن عبد الرحمن بن ثوبان، فرماتے ہیں: اسی طرح اسے ابو نعیم نے اپنے مجموعے میں حدیث صفوان بن سلیم میں صحیح طریق سے نقل کیا ہے، ابو موسیٰ کا قول ہے: اسی طرح عبدان نے اسے بحوالہ قتیبہ، انہوں نے لیث سے، انہوں نے عبید اللہ بن ابی جعفر سے نقل کیا ہے، فرماتے ہیں: بحوالہ محمد بن ثوبان پھر ان کے دادا تک نسب بیان کیا ہے۔ اسی طرح اسے ابو داؤد نے مراسیل میں بحوالہ قتیبہ نقل کیا ہے۔ ابن حبان نے کتاب الثقات میں فرمایا: محمد بن ثوبان شیخ (محدث) ہیں جو مرسل احادیث روایت کرتے ہیں... پھر مذکورہ حدیث روایت کی، پھر فرمایا: اسے لیث نے روایت کیا ہے، پھر اس کی سند ذکر کی، پھر فرمایا: جس کا یہ گمان ہے کہ انہیں شرف صحابیت حاصل ہے، اسے وہم ہوا ہے، پھر محمد بن عبد الرحمن بن ثوبان نے دوسرے سوانح میں ان کا ذکر کیا ہے۔ انہوں نے صحیح نہیں لکھا۔ ابو موسیٰ کا قول ہے: ہم نے ان کا اس لیے ذکر کیا ہے تا کہ کسی کو یہ گمان نہ ہو کہ ہم نے ان سے صرف نظر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۷۳۵) تجرید (۶۰/۲)\n(2) ابوداؤد کتاب النکاح (۱۸۸) (۲۸۹) معرفۃ الصحابہ (۱۳۷/۲) السنن الکبریٰ (۱۳۷/۲)"}],[8506,"§۸۵۳۱ ۔ محمد بن عتوارہ\nکنانی، پھر لیثی۔ ان لوگوں میں سے ہیں جن کا نام جاہلیت میں محمد رکھا گیا۔ ابو موسیٰ نے ان کا ذکر کیا ہے۔ فرماتے ہیں: یہ اس پر دلالت نہیں کرتا، محمد بن احیحہ بن جلاح کے سوانح میں اس کی طرف اشارہ گزر چکا ہے۔"],[8507,"§۸۵۳۲ ۔ محمد بن عروہ\nبن عطیہ سعدی۔ بغوی رحمہ اللہ نے محمد بن عطیہ کے سوانح میں ان کا ذکر کیا ہے، میں نے قسم ثانی میں محمد بن عطیہ کے سوانح میں غلطی کی وجہ بیان کر دی ہے۔ واللہ اعلم"],[8508,"§۸۵۳۳ ۔ محمد بن عطیہ سعدی\nقسم ثانی میں ان کا ذکر گزر چکا ہے۔"],[8509,"§۸۵۳۴ ۔ محمد بن عقبہ\nبن احیحہ بن جلاح قسم اول میں ان کا ذکر گزر چکا ہے۔"],[8510,"§۸۵۳۵ ۔ محمد بن عمرو\nبن علقمہ، ذہبی رحمہ اللہ نے تجرید میں ذکر کیا ہے کہ مسند بقی بن مخلد میں ان کی ایک حدیث ہے۔ یہ وہی لیثی ہیں جو ابو سلمہ بن عبد الرحمن اور ان کے طبقے کے لوگوں سے روایت کرتے ہیں۔ یہ اور ان کے والد صحابی نہیں ہیں، بقی کی مسند میں اس طرح کی کئی مثالیں ہیں وہ حدیث کو تابعین کی روایت سے نقل کرتے ہیں۔ خواہ وہ کبیر ہو یا صغیر۔ اسی طرح ان لوگوں سے بھی روایت کرتے ہیں جو تابعین میں شمار ہوتے ہیں، جیسے یہ محمد بن عمرو ہیں (تعجب کی بات ہے وہ اس کی وضاحت نہیں کرتے) پھر میں نے جز صحابہ رضی اللہ عنہم کے کسی نسخے میں دیکھا ہے، جن صحابہ رضی اللہ عنہم کی احادیث بقی بن مخلد نے ابن حزم محمد بن عمرو بن علقمہ کی ترتیب سے نقل کی ہیں۔ واللہ اعلم!"],[8511,"§۸۵۳۶ ۔ محمد بن عمیر(1)\nبن عطارد بن حاجب تمیمی، ابن مندہ کا قول ہے: صحابہ رضی اللہ عنہم میں ان کا ذکر ہے اور ان کا صحابی ہونا اور دیدار معروف نہیں۔ میں کہتا ہوں: ان کی وہ حدیث جس سے بخاری رحمہ اللہ کے اعتماد سے اشارہ ہوتا ہے کہ وہ مرسل ہے، اسے حماد بن سلمہ نے بحوالہ ابو عمران جونی، انہوں نے محمد بن عمیر بن عطارد نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم اپنے ساتھیوں کی ایک جماعت میں تھے، آپ صلی اللہ علیہ وسلم کے پاس حضرت جبرائیل علیہ السلام آئے اور آپ کے کندھے پر ہاتھ رکھا، آپ علیہ السلام نے فرمایا: پھر وہ مجھے ایک درخت کے پاس لے گئے جس میں پرندے کے گھونسلے کی طرح دو نشست گاہیں بنی ہوئی تھیں۔ ایک میں وہ اور دوسرے میں میں بیٹھ گیا، پھر وہ ہمیں لے کر چل پڑے، یہاں تک کہ افق بھر گیا۔ اگر میں اپنا ہاتھ آسمان کی طرف بڑھاتا تو اس کے ساتھ لگ جاتا، پھر جبرائیل جہاں نور اتر رہا تھا وہاں پہنچے، اس کے بعد جبرائیل بے ہوش ہو گئے... (الحدیث)(2)\nاسے ابن مبارک رحمہ اللہ نے کتاب الزہد میں بحوالہ حماد نقل کیا ہے، حسن بن سفیان نے بحوالہ ابراہیم بن حجر، انہوں نے حماد سے اس کی پیروی کی ہے، اسی طرح یزید بن ہارون نے بحوالہ حماد، اس میں محمد بن عطارد کے بعد یہ اضافہ کیا ہے عن ابیہ اسی طرح ابن ابی حاتم نے بحوالہ اپنے والد اعتماد کیا ہے، اسی طرح عسکری اور ابن حبان نے اسے مرسل قرار دیا ہے۔ میں کہتا ہوں: یہ محمد کوفہ کے معززین میں سے ہیں، کوفہ کے گورنروں، حجاج وغیرہ کے ساتھ ان کے کئی واقعات ہیں۔ انہی کے متعلق ایک شاعر کہتا ہے:\n”معد اور تمام قبائل جانتے ہیں کہ محمد بن عطارد بہادر ہے“۔ خلیفہ بن خیاط کا بیان ہے کہ صفین میں سیدنا علی رضی اللہ عنہ کے امیروں میں سے تھے۔ ابن مسروق کا بیان ہے کہ یہ عبدالملک بن مروان کے پاس آئے تو اس نے انہیں خاص کمرے میں اتارا۔ ان کے دادا عطارد بن حاجب کا تذکرہ حرف عین میں ہو چکا ہے۔ رہے ان کے والد تو مجھے معلوم نہیں کہ آیا انہوں نے دور نبوی پایا ہے یا نہیں؟ اس لیے کہ میں نے نہیں دیکھا کہ جن لوگوں نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھی ہیں، انہوں نے ان کا ذکر کیا ہے، ان کے زیادہ مناسب یہی ہے کہ انہوں نے عہد نبوی پایا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۶۰) تجرید (۶۰/۲)\n(2) مسند احمد (۲۳۱/۲) التاریخ الکبیر (۱۹۴/۱) معرفۃ الصحابہ (۱۰۴/۲) (۱۰۵/۲) اسد الغابہ (۸۰/۴)"}],[8512,"§۸۵۳۷ ۔ محمد بن فضالہ(1)\nبغوی، ابن قانع، ابن حبان، ابن شاہین نے ان کے اور محمد بن انس بن فضالہ کے درمیان فرق کیا ہے۔ طبرانی رحمہ اللہ ابن مندہ اور ان کی اتباع کرنے والوں نے اس سے انکار کیا ہے۔ انہوں نے ایک سوانح میں دو حدیثیں نقل کی ہیں۔ ان کے نزدیک جس نے انہیں ان کے دادا کی طرف نسبت کر کے محمد بن فضالہ کہا ہے، وہ صحیح ہے، جیسا کہ قسم اول میں میں نے وضاحت کی ہے۔ واللہ اعلم","",{"fn":"(1) استیعاب (۲۳۷۲) تجرید (۶۱/۲)"}],[8513,"§۸۵۳۸ ۔ محمد بن ابی کریمہ\nانہوں نے نبی کریم صلی اللہ علیہ وسلم سے سواک کے بارے میں روایت کی ہے، ان سے ابراہیم بن حجر نے روایت کی ہے، ابن فتحون کے اپنے استدراک میں ان کا ذکر کیا ہے اور بحوالہ ابی ذرعہ رازی نقل کیا ہے کہ انہوں نے اسے مسند شاہین میں شامل کیا ہے۔ بخاری(1) نے اعتماد کیا ہے کہ ان کی حدیث مرسل ہے، ابن ابی حاتم اور احمد عسکری نے ان کی پیروی کی ہے۔","",{"fn":"(1) تاریخ الکبیر (۲۱۸/۱)"}],[8514,"§۸۵۳۹ ۔ محمد بن کعب قرظی(1)\nانصار کے حلیف اور مشہور تابعی ہیں۔ ترمذی نے جامع میں فرمایا: میں نے قتیبہ بن سعید کو فرماتے ہوئے سنا: مجھے یہ بات پہنچی ہے کہ محمد بن کعب قرظی، نبی کریم صلی اللہ علیہ وسلم کی حیات میں پیدا ہوئے۔ اس طرح ابو عبیدہ آجری نے بحوالہ ابو داؤد، انہوں نے قتیبہ سے نقل کیا ہے اور وہ قتیبہ کی طرف سے وہم ہے۔ یہ کعب والد محمد کے بارے میں منقول ہے۔\nبخاری(2) نے محمد بن کعب کے سوانح میں نقل کیا ہے کہ ان کے والد ان لوگوں میں سے تھے جن کا نسب معلوم نہیں، اور جب بنو قریظہ کو سیدنا سعد بن معاذ رضی اللہ عنہ کے فیصلے پر قتل کیا گیا تو یہ بنی قریظہ کے ساتھ قتل نہیں ہوئے۔ ابن ابی خیثمہ نے اپنی تاریخ میں بحوالہ موسیٰ بن عقبہ روایت کی ہے کہ مجھے یہ بات معلوم ہوئی کہ نبی علیہ السلام نے فرمایا تھا: ”دو کانوں کے بیچ میں سے ایک شخص ہوگا جو سب سے بڑھ کر اللہ کی کتاب کا عالم ہوگا“۔ تو لوگ کہا کرتے تھے کہ وہ محمد بن کعب ہیں، کیونکہ ان کے والد بنی قریظہ اور والدہ بنی نظیر سے ہیں، دو کانوں سے مراد بنی قریظہ اور بنی نظیر ہیں۔ محمد بن کعب کی صحابہ رضی اللہ عنہم سے مروی حدیث صحیح میں ہے۔ تہذیب میں ان کے حالات مذکور ہیں۔ ان سے بحوالہ ابن مسعود روایت ہے، ابن عساکر نے اسے بعید قرار دیا ہے۔\nابن سعد(3) نے اہل مدینہ کے تابعین کے طبقہ اولیٰ میں ان کا ذکر کیا ہے۔ یعقوب بن شیبہ کا قول ہے: سیدنا ابو ہریرہ رضی اللہ عنہ وغیرہ سے روایت کرنے والے تیسرے طبقے میں ان کا شمار ہے، انہوں نے سیدنا عباس رضی اللہ عنہ سے نہیں سنا۔ کیونکہ سیدنا عباس رضی اللہ عنہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پا گئے تھے اور محمد بن کعب سیدنا علی رضی اللہ عنہ کی خلافت کے آخر میں ۴۰ھ میں پیدا ہوئے۔ ان کی وفات ۱۰۸ھ میں ہوئی۔ بعض کا قول ہے: اس کے بعد وفات پائی یہاں تک کہ بعض نے کہا: وہ ۱۲۰ھ میں فوت ہوئے، یہ یقین سے کہا جاتا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد ہی پیدا ہوئے۔","",{"fn":"(1) استیعاب (۲۳۷۱) تجرید (۶۱/۲)\n(2) تاریخ کبیر (۲۱۶/۱)\n(3) طبقات الکبریٰ (۳۷۱) (۳۷/۵) (۵۰۱/۷)"}],[8515,"§۸۵۴۰ ۔ محمد بن محمود(1)\nعبدان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا، پھر دو طریق سے حدیث نقل کی۔ بحوالہ یحییٰ بن سعید انصاری، انہوں نے محمد بن محمود سے نقل کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ایک نابینا کو وضو کرتے ہوئے دیکھا جب اس نے اپنے ہاتھ اور چہرہ دھویا تو نبی کریم صلی اللہ علیہ وسلم نے اس سے فرمایا: ”اپنے پاؤں کا پیچھے والا حصہ دھوؤ۔“(2)\nاس حدیث میں ایسی کوئی بات نہیں جس سے معلوم ہو کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا، جیسا کہ عبدان کا خیال ہے۔ بخاری رحمہ اللہ(3) نے ان لوگوں کا اتباع کیا ہے، انہوں نے ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کی حدیث مرسل ہے، انہوں نے ان کے نسب میں اختلاف کیا ہے، بعض کا قول ہے: وہ محمد بن محمود بن عبد اللہ بن مسلمہ ابن اخی محمد بن مسلمہ ہیں، بعض کا قول ہے: وہ ان کے پوتے ہیں، ابن مندہ نے اپنی تاریخ میں محمد بن محمود بن محمد بن مسلمہ لکھا ہے، انہوں نے اپنے والد عدی سے روایت کیا ہے، ان سے ان کے بیٹے سلیمان نے روایت کیا، کنیتوں میں ابو الفرثغفی کے سوانح میں ان کا مزید ذکر آئے گا۔ ان شاء اللہ تعالیٰ","",{"fn":"(1) اسد الغابہ (۴۷۶۶) تجرید (۶۱/۲)\n(2) جامع المسانید والسنن (۱۵۴/۱۱) اسد الغابہ (۸۲/۴)\n(3) تاریخ کبیر (۲۲۴/۱)"}],[8516,"§۸۵۴۱ ۔ محمد بن یحمد\nمحمد بن براء کے سوانح میں ان کا ذکر آئے گا۔"],[8517,"§۸۵۴۲ ۔ محمد بن یزید\nبن عمرو بن ربیعہ، بن خرقوص بن مازن بن عمرو بن تمیم تیمی مازنی۔ ابو موسیٰ نے ان کا ذکر کیا ہے، قسم اول میں محمد بن عدی کے سوانح میں اس پر تنبیہ گزر چکی ہے۔"],[8518,"§۸۵۴۳ ۔ محمد اسدی\nمحمد بن سعد نے ان لوگوں میں ان کا ذکر کیا ہے، جن کا نام جاہلیت میں محمد رکھا گیا۔"],[8519,"§۸۵۴۴ ۔ محمد الفقیمی\nمحمد بن سعد نے جاہلیت کے محمد نامی لوگوں میں ان کا ذکر کیا ہے۔"],[8520,"§۸۵۴۵ ۔ محمد کنانی\nبعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، یہ ثابت نہیں، ان کی حدیث مرسل ہے۔ ان سے عیسیٰ بن عبید کنانی نے روایت کی ہے۔ یہ ابو احمد عسکری کا قول ہے۔"],[8521,"§۸۵۴۶ ۔ محمد، ابو سلیمان مدنی\nابن مندہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: ایک جماعت نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، وہ وہم ہے۔ پھر بطریق ابو الفضل احمد بن حسین لہبی، بحوالہ سلیم بن محمد کرمانی، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے وضو کیا اور اچھی طرح وضو کیا، پھر نماز پڑھنے کی غرض سے مسجد قباء گیا تو اسے ایک عمرہ کا ثواب ملے گا۔“(1) ابن مندہ کا قول ہے: صحیح یہ ہے، بحوالہ محمد بن سلیمان کرمانی، انہوں نے ابو امامہ بن سہل بن حنیف، انہوں نے اپنے والد سے نقل کیا ہے۔\nیہ حدیث ابن ماجہ میں مذکور ہے۔ حاکم نے بطریق حاتم بن اسماعیل اور عیسیٰ بن یونس اسے صحیح قرار دیا ہے، دونوں نے محمد بن سلیمان سے صحیح طریق سے نقل کیا ہے۔ اسی طرح اسے نسائی نے اس مفہوم میں نقل کیا ہے، بروایت محمد بن یعقوب، بحوالہ محمد بن سلیمان گویا اس راوی کا نام ابو الفضل سے تبدیل ہو گیا اور ان کے شیخ کا نام چھوٹ گیا، اس سے ایسے صحابی کا نام جڑ گیا جس کا وجود ہی نہیں۔","",{"fn":"(1) نسائی (۶۹۸) ، ابن ماجہ (۱۴۰۲) مسند احمد (۳۸۷/۲)، معجم الکبیر (۷۴/۶)"}],[8522,"§۸۵۴۷ ۔ محمود بن عمرو(1)\nابو موسیٰ نے بحوالہ عبدان ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۷۷۱)"}],[8523,"§۸۵۴۸ ۔ محمول انصاری(1)\nتابعی ہیں، ان کی حدیث مرسل ہے۔ مستغفری نے صحابہ میں بحوالہ یحییٰ بن یونس شیرازی ان کا ذکر کیا ہے، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے اور بطریق محمد بن عمرو بن علقمہ، بحوالہ محمول انصاری نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس نے شرک اور گناہ پر قسم کھائی، اس نے شرک کیا۔“(2)","",{"fn":"(1) اسد الغابہ (۴۷۸۲) تجرید (۶۲/۲)\n(2) جامع المسانید والسنن (۱۸۳/۱۱) اسد الغابہ (۸۹/۴)"}],[8524,"§۸۵۴۹ ۔ مختار بن ابی عبید(1)\nبن مسعود ثقفی، کنیتوں میں ان کے والد کے سوانح میں ان کا نسب آئے گا، ابن عبد البر نے ان کا ذکر کیا ہے، فرماتے ہیں: اس کی کنیت ابو اسحاق ہے، اچھی سیرت والا آدمی نہیں تھا۔\nاس کے والد جلیل القدر صحابہ میں سے ہیں، کنیتوں میں ان کا ذکر آئے گا۔ مختار ہجرت کے سال پیدا ہوا، اسے شرف صحابیت اور رؤیت حاصل نہیں، ان کے حالات ناپسندیدہ ہیں، جنہیں اس سے ثقہ لوگوں جیسے شعبی رحمہ اللہ نے نقل کیا ہے۔ اس نے گورنری کا مطالبہ کیا اور کوفہ پر غلبہ پا لیا، یہاں تک کہ مصعب بن زبیر کو کوفہ میں ۶۷ھ میں قتل کر دیا۔(2) جبکہ اس سے پہلے یہ فضیلت والے اور نیک لوگوں میں شمار ہوتا تھا۔ یہاں تک کہ اس نے ابن زبیر کا ساتھ چھوڑ دیا وہ سیدنا حسین رضی اللہ عنہ کے خون کے مطالبے کا دھوکا دیتا تھا اور دنیا طلبی سے خوش ہوتا تھا، جھوٹ اور جنون بھری باتیں کرتا تھا۔ سولہ(۱۶) ماہ اس کی حکومت رہی، موسیٰ بن اسماعیل عن ابی عوامہ، عن مغیرہ، بحوالہ ثابت بن ہرمز روایت کرتے ہیں کہ مختار نے اپنے چچا کے ہاں سے مدائن کا بہت سا مال سیدنا علی رضی اللہ عنہ کی طرف بھیجا، ان میں سے ایک تھیلی نکالی، اس میں پندرہ درہم تھے۔ کہنے لگا: یہ کسیوں کی کمائی ہے۔ سیدنا علی رضی اللہ عنہ نے اس سے کہا: تیرا ناس ہو! مجھے کیسوں سے کیا تعلق؟ اس نے سرخ رنگ کی دھاری دار چادر اوڑھ رکھی تھی، جب وہ سلام کر کے چلا گیا تو سیدنا علی رضی اللہ عنہ نے فرمایا: اللہ اسے ہلاک کرے! اسے کیا ہوا ہے؟ اگر اللہ اس کا دل چیر کے دکھائے تو لات اور عزیٰ کی محبت سے بھرا ہوگا۔ فرماتے ہیں: بقول بعض: ابتدا میں وہ خارجی تھا، پھر زیدی ہوا، پھر رافضی ہو گیا۔\nمختار نے محمد بن عمار بن یاسر کو ظلما قتل کیا کیونکہ اس نے ان سے کہا تھا کہ تم اپنے والد کے حوالے سے جھوٹی حدیث بیان کرو، انہوں نے ایسا نہ کیا تو انہیں قتل کر دیا۔ یہ تو وہ باتیں ہیں جو ابو عمر نے اس کے حالات میں لکھی ہیں۔ اور یقین سے لکھا ہے کہ اس کے والد صحابی تھے۔ اور یہ ہجرت کے بعد پیدا ہوا۔ یہ بارہا گزر چکا ہے کہ وہ اور طائف میں جو قریشی اور ثقفتی زندہ رہا وہ حجۃ الوداع میں شریک ہوا تھا، اس لیے مختار اس قسم میں سے ہوا۔ البتہ اس کے حالات برے ہیں۔ ابن الاثیر(3) نے اس کے حالات میں ابن عبد البر سے کچھ مزید لکھا ہے، مختار اور شعبی کے درمیان کوئی ایسی بات تھی کہ ان میں سے ایک کی بات دوسرے کے خلاف نہیں سنی جائے گی، ابن اثیر نے اتنی مقدار ابن عبد البر کے حوالے میں درج کی ہے جو وہاں نہیں ہے۔ اور نہ یہ صحیح ہے اس واسطے کہ شعبی اس سے نقل کرنے میں تھا نہیں۔ شعبی کے ثقہ ہونے پر اتفاق ہے۔ اور مختار کا معاملہ اس کے برعکس ہے۔ اہل بیت کی ایک جماعت نے اس کے خلاف دعویٰ نبوت اور واضح جھوٹ کی گواہی دی ہے۔ اس سلسلہ میں ایک روایت وہ ہے جو امام احمد رحمہ اللہ نے مسند عمرو بن احنف میں بطریق السدی عن رفاعہ الثقفی نقل کی ہے۔\nفرماتے ہیں: میں مختار کے پاس گیا، اس نے مجھے ایک تکیہ دیا اور کہنے لگا: اگر میرا بھائی جبرائیل اس سے نہ اٹھ کے گیا ہوتا اور دوسرے تکیے کی طرف اشارہ کیا) تو میں تمہیں وہ دے دیتا۔ فرماتے ہیں: میرا جی چاہا کہ اس کی گردن اڑا دوں... پھر قصہ ذکر کیا، اور عمرو بن حبق سے حدیث روایت کی۔\nابن حبان نے ثقات میں صفیہ بنت ابی عبید کے سوانح میں فرمایا: وہ مختار کی بہن ہیں جس نے عراق میں نبوت کا دعویٰ کیا تھا، اس سے زیادہ قوی وہ روایت ہے جسے مسلم نے اپنی صحیح میں بحوالہ اسماء بنت ابو بکر نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ثقیف میں ایک جھوٹا اور ایک ظالم ہوگا۔“(4) سیدہ اسماء رضی اللہ عنہا نے گواہی دی کہ جھوٹا مختار ہے جس کا یہ ذکر ہے۔ ابن اثیر کا قول ہے: مختار سیدنا حسین رضی اللہ عنہ کے خون کا بدلہ لینے کے لیے منظر عام پر آیا تو شیعان کوفہ میں سے بہت بڑی تعداد اس کے پاس جمع ہوگئی، وہ کوفہ پر غالب آگیا اور سیدنا حسین رضی اللہ عنہ کے قاتلوں کو تلاش کرنے لگا۔ پھر انہیں قتل کر دیا۔ اس نے شمر بن ذی جوشن کو قتل کیا جو سیدنا حسین رضی اللہ عنہ کے قتل میں شریک تھا۔ اور خولی بن یزید کو جو آپ رضی اللہ عنہ کا سر کوفہ لے گیا، عمر بن سعد بن ابو وقاص کو جو اس لشکر کا امیر تھا جس نے سیدنا حسین رضی اللہ عنہ سے جنگ کی تھی یہاں تک کہ آپ رضی اللہ عنہ کو شہید کر دیا، اس کے ساتھ اس کے بیٹے حفص کو قتل کر دیا، ابراہیم بن اشتر کے ساتھ بہت بڑا لشکر بھیجا جس نے عبید اللہ بن زیاد سے لڑائی کی، یہ وہ شخص تھا جس نے سیدنا حسین رضی اللہ عنہ سے جنگ کے لیے لشکر تیار کیا تھا، اور آپ رضی اللہ عنہ سے لڑائی کی تھی۔ عبید اللہ بن زیاد اس واقعہ میں قتل ہوا، ابن اثیر کا قول ہے: اس وجہ سے بہت سے مسلمان مختار کے گرویدہ ہو گئے۔ اس نے اس بارے میں بہت سے کارنامے انجام دیے۔ فرماتے ہیں: وہ سیدنا ابن عمر کی طرف مال بھیجتا تھا، وہ اس کی سسرالی رشتہ دار اور اس کی بہن صفیہ بنت ابو عبید کے شوہر تھے، سیدنا ابن عباس اور حضرت ابن حنیفہ کی طرف مال بھیجتا، وہ اسے قبول کر لیتے پھر اس کی طرف بصرہ سے مصعب گیا، اس نے مختار کو قتل کر دیا۔\nمختار کا سب سے پہلا معاملہ یہ ہوا کہ سیدنا ابن زبیر رضی اللہ عنہ نے اسے کوفہ بھیجا تا کہ وہ ان کی بیعت کو مضبوط کرے اور عبد اللہ بن مطیع کو کوفہ کا امیر بنا دیا، مختار نے یہ ظاہر کیا کہ ابن زبیر اصل میں سیدنا حسین رضی اللہ عنہ کے خون کا بدلہ لینا چاہتے ہیں، پھر اس نے اپنے قدم جمانے شروع کر دیے، اور یہ دعویٰ کیا کہ محمد بن حنیفہ مہدی ہیں جو آخری زمانے میں ظاہر ہوں گے، انہوں نے اسے حکم دیا ہے کہ وہ لوگوں کو ان کی بیعت کی طرف بلائیں، اس نے اپنے پاس سے ایک خط بھی لکھ لیا، بہت بڑی جماعت اس کی مطیع ہوگئی، ان لوگوں سے اسے تقویت ملی، وہ سیدنا حسین رضی اللہ عنہ کے قاتلوں کو چن چن کر قتل کرنے لگا۔ جو لوگ اہل بیت سے محبت رکھتے تھے ان سے بھی اسے تقویت ملی پھر ابن زبیر، ابن حنیفہ اور ابن عباس کے درمیان جو ہوا سو ہوا، کیونکہ وہ دونوں ان کی بیعت کرنے سے رک گئے تھے۔ انہوں نے ان دونوں کا اور جو لوگ ان کے ساتھ شریک تھے ان کا ایک گھاٹی میں محاصرہ کر لیا، ان پر ابو عبد اللہ جدلی کو امیر بنایا، انہوں نے مکہ پر حملہ کر دیا، اور انہیں گھاٹی سے نکال لیا۔ وہ طائف چلے گئے، تو لوگوں نے اس بات پر مختار کی قدر دانی کی، جس کے متعلق مختار خود کہتا ہے، اور مرزبان نے اس پر شعر نقل کیا ہے:\n”میں نے ہوان سے مضبوط زرہ پہنی جو سدھائی ہوئی اونٹنیوں کے ذریعے اونچے لوگوں کو ہٹا دیتی ہے، یہ وہی لوگ ہیں جنہوں نے آل رسول صلی اللہ علیہ وسلم کی مدد کی، جبکہ لوگوں پر ایک مصیبت پڑ چکی ہے، انہوں نے اپنے امام سے جو عہد کیا اسے پورا کیا اور اسلام سے ظالموں کی تلوار کو روک دیا“۔\nابن سعد نے، بحوالہ واقدی اپنی اسانید سے ذکر کیا ہے کہ ابو عبیدہ مختار کے والد سیدنا عمر رضی اللہ عنہ کے زمانے میں طائف آئے جب لوگوں کو عراق کے لیے پکارا، ابو عبیدہ نکلے اور جسر کے دن شہید ہو گئے، ان کا بیٹا مدینہ میں رہا، ابن عمر نے صفیہ بنت ابو عبید سے نکاح کر لیا، مختار مدینہ میں بنو ہاشم کے ساتھ رہا، پھر سیدنا علی رضی اللہ عنہ کے ساتھ عراق میں رہا۔ سیدنا علی رضی اللہ عنہ کے بعد بصرہ میں فروش ہوا، ان کا سیدنا حسن بن علی کے ساتھ قصہ ہے، جب آپ خلیفہ بنے، عبید اللہ زیاد سے آپ کی یہ چغلی کھائی کہ وہ سیدنا حسین کے قتل کا انکار کرتے ہیں، تو اس نے اسے کوڑے لگانے اور قید کرنے کا حکم دیا، تو عبد اللہ بن عمر نے اس بارے میں سفارشی پیغام بھیجا تو اس نے اسے طائف کی طرف جلا وطن کر دیا، جہاں وہ یزید بن معاویہ کی وفات تک مقیم رہا۔ سیدنا ابن زبیر خلافت کی تلاش میں اٹھ کھڑے ہوئے، تو آپ کے پاس آپ کی امداد کے لیے آپ پہنچا اور آپ سے خیر خواہانہ باتیں کرتے کرتے کوفہ کی طرف جانے کی اجازت لے لی، تا کہ عبد اللہ بن مطیع کو آپ کی فرماں برداری میں دعوت دینے کے لیے امداد پہنچائے، آپ نے اس پر بھروسہ کر لیا اور اسے نامزد کر دیا، پھر اس سے جو ہوا سو ہوا پھر مصعب بن زبیر جو اپنے بھائی عبد اللہ بن زبیر کی طرف سے بصرہ کے گورنر تھے انہوں نے بہت سے کوفہ کے ایسے لوگوں کے ذریعے جو مختار کے دامِ تزویر میں آ چکے تھے اور جب اس کے جھوٹ اور فریب کاریاں ظاہر ہوئیں تو اس سے الگ ہو گئے، مختار پر دسترس حاصل کر لی۔ ادھر محمد بن سعد نے محمد بن حنیفہ کے حالات میں اس بارے میں کئی باتیں ذکر کی ہیں جب مختار اور مصعب کا آمنا سامنا ہوا تو جو لوگ مختار کے ساتھ تھے، انہوں نے اس کا ساتھ دینے سے دستبرداری کر لی یوں مختار کا محل میں محاصرہ کر لیا گیا۔ پھر اسے اور اس کے ساتھیوں کو قتل کر دیا گیا۔ پھر جب مختار کا فتنہ ہوا تو عبدالملک بن مروان کچھ وقت بعد شام کے لشکروں کو لے کر مصعب بن زبیر کے مقابلے میں جا پہنچا، مصعب قتل ہو گئے اور عبد الملک نے بصرہ اور پھر کوفہ پر قبضہ کر لیا۔ عبد الملک بن عمر کا بیان ہے کہ انہوں نے عبد اللہ بن زیاد کو دیکھا کہ اس کے پاس سیدنا حسین کا سر لایا گیا، پھر مختار کو دیکھا کہ اس کے پاس عبد اللہ بن زیاد کا سر لایا گیا، پھر مصعب بن زبیر کو دیکھا کہ ان کے پاس مختار کا سر لایا گیا۔ پھر عبد الملک بن مروان کے پاس مصعب کا سر لایا گیا۔","",{"fn":"(1) اسد الغابہ (۴۷۹۱) استیعاب (۲۵۵۱) تجرید (۶۴/۲)\n(2) اسد الغابہ (۹۲/۴)\n(3) اسد الغابہ (۹۲/۴)\n(4) مسلم (۲۴۴۲) (۸۷/۲)"}],[8525,"§۸۵۵۰ ۔ مُدرک بن عمارہ(1)\nروایت کیا جاتا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے۔ تا کہ وہ آپ صلی اللہ علیہ وسلم سے بیعت کریں تو آپ صلی اللہ علیہ وسلم نے ان پر خوشبو کا رنگ دیکھ کر اپنا ہاتھ کھینچ لیا۔\nابن عبد البر نے ان کا ذکر کیا ہے، اور فرمایا: ان کی حدیث میں اضطراب اور ان کے صحابی ہونے میں تردد ہے، اگر وہ عقبہ بن معیط کے دادا ہیں تو نہ وہ صحابی ہیں نہ انہیں ملاقات اور دیدار حاصل ہے۔ اگر ان کی حدیث بحوالہ ان کے والد ہے تو وہ بھی صحیح نہیں۔ ابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مدرک بن عمارہ اور بطریق عمر بن ابی زائدہ ان کے حوالے سے حدیث نقل کیا ہے، فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کی مسجد سے گزرا۔ نبی کریم صلی اللہ علیہ وسلم اس میں تھے، اسی طرح ان کی کتاب میں ہے۔","",{"fn":"(1) استیعاب (۴۲۸/۳)"}],[8526,"§۸۵۵۱ ۔ مذکور القبطی(1)\nمستغفری نے ان کا ذکر کیا ہے اور حدیث جابر سے نقل کیا ہے، فرماتے ہیں: انصار کے ایک شخص نے اپنا مذکور نامی مدبر غلام آزاد کیا... (الحدیث)(2) یہ معاضر کا وہم ہے جو اس روایت کو عن اعمش، عن سلمہ بن کہیل، عن عطاء ان کے حوالے سے روایت کرنے والے ہیں، حدیث سیدنا جابر رضی اللہ عنہ سے مشہور ہے لیکن غلام کا نام یعقوب ہے۔ اور جسے مدبر بنایا تھا وہ ابو مذکور ہے، یہ نام الف کیا اور اس سے لفظی غلطی ہوئی۔","",{"fn":"(1) اسد الغابہ (۴۸۱۲) تجرید (۶۶/۲)\n(2) اسد الغابہ (۱۰۰/۴)"}],[8527,"§۸۵۵۲ ۔ مُرارہ بن سلمی(1)\nیمامی، حنفی۔ ان کے بیٹے مجاہ کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن مندہ کا قول ہے: انہیں اور ان کے بیٹے مجاہ کو وفد میں آنے کی سعادت حاصل ہے۔ پھر بطریق ابن ابو عاصم نقل کیا ہے، فرماتے ہیں: ہم سے جزاح بن مخلد نے بحوالہ مرارہ، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کیا ہے، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا۔ آپ صلی اللہ علیہ وسلم نے مجھے زمین کا ایک ٹکڑا دیا اور ایک تحریر لکھ کر دی... (الحدیث)(2) اسے ابو نعیم نے بطریق ابن ابو عاصم(3) نقل کیا ہے، اور اس طرف اشارہ کیا ہے کہ انہوں نے خطا کی، اس میں وہم کی وجہ بیان نہیں کی، فرماتے ہیں کہ ان سے حارث بن مرہ کے شیخ کا نام رہ گیا وہ بلال بن سراج بن مجاہ بن مرارہ ہیں۔ حدیث کا مدار سراج بن مجاہ پر ہے، ان کے دادا مرہ ہیں۔ انہوں نے یہ نتیجہ اخذ کیا ہے کہ قصہ مرارہ کا ہے جبکہ ایسا نہیں۔\nبغوی نے بحوالہ زیاد بن ایوب، انہوں نے بلال بن سراج بن مجاہ کے حوالے سے، انہوں نے اپنے والد سراج سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مجاہ بن مرارہ کو زمین عطا فرمائی... (الحدیث)","",{"fn":"(1) اسد الغابہ (۴۸۱۵) تجرید (۶۷/۲)\n(2) ابوداؤد (۳۹۹۰) جامع المسانید والسنن (۸۲/۱۱) اسد الغابہ (۱۰۱/۴)\n(3) الآحاد والمثانی (۱۶۸۶/۲)"}],[8528,"§۸۵۵۳ ۔ مُرّہ ذوالکلاع\nابن قانع نے اسے نقل کیا ہے اور بطریق ابو الھب عبد الملک بن عمیر بحوالہ ابی روح مرہ ذی الکلاع نقل کیا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں صبح کی نماز پڑھائی اور سورہ روم کی تلاوت فرمائی۔ آپ صلی اللہ علیہ وسلم نے آیت بار بار پڑھی... (الحدیث) ابن قانع کا قول ہے: اسی طرح فرمایا: اسے زائدہ نے بحوالہ شعیب ابی روح نقل کیا ہے۔\nمیں کہتا ہوں: پہلی روایت میں لفظی غلطی ہے۔ صحیح میم کے نیچے زیر اور نون ساکن کے ساتھ ہے۔ رہا مُرّ یعنی میم کے پیش اور را کی تشدید کے ساتھ، تو وہ لفظی غلطی ہے۔ حرف شین میں اس بارے میں گزر چکا ہے۔"],[8529,"§۸۵۵۴ ۔ مُرشد بن ظبیان عبدی(1)\nابن قانع نے اسی طرح ان کا ذکر کیا ہے، اس میں غلط ملط ہے، انہوں نے بطریق طالب بن حجیر، بحوالہ ھود بن عبد اللہ نقل کیا ہے، میں نے مرشد عبدی کو فرماتے ہوئے سنا: میں نبی کریم صلی اللہ علیہ وسلم کے پاس تھا، ابن عبد القیس آئے... (الحدیث)(2) وہ غلطی ہے جو تصحیف سے ہوئی، وہ مریدہ ہیں جو ھود بن عبد اللہ کے نانا ہیں۔ قسم اول میں صحیح گزر چکا ہے۔ صحابہ میں مرشد بن ظبیان بھی ہیں، وہ سدوسی ہیں، قریب میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۶۷/۲)\n(2) مسند احمد (۶۸/۵)"}],[8530,"§۸۵۵۵ ۔ مُرداس عنبری\nوہ ابن عففان ہیں، جن کا ذکر گزر چکا ہے۔ ذہبی رحمہ اللہ نے انہیں دو قرار دیا ہے، جبکہ وہ ایک شخص ہیں۔ واللہ اعلم"],[8531,"§۸۵۵۶ ۔ مُرّہ بن حبیب فہری(1)\nان سے ان کی بیٹی ام سعد نے حدیث روایت کی۔ ذہبی رحمہ اللہ نے ان کا ذکر کیا ہے، انہوں نے ان کے اور مرہ بن عمرو بن حبیب کے درمیان جو قسم اول میں گزر چکے ہیں، فرق کیا ہے۔ جبکہ وہ ایک ہیں وہ اپنے دادا کی طرف منسوب ہیں۔","",{"fn":"(1) تجرید (۷۰/۲)"}],[8532,"§۸۵۵۷ ۔ مُرّہ بن مالک داری\nاسی طرح واقدی کی روایت میں ہے۔ دوسرے راویوں نے ان کا نام مردان لیا ہے۔ ان کا ذکر گزر چکا ہے، یہی صحیح ہے۔"],[8533,"§۸۵۵۸ ۔ مُرّہ بن مربع\nابو عمر نے ان کا ذکر کیا ہے، اسی طرح تجرید میں ہے، استیعاب میں جن کا ذکر ہے وہ مُرارہ ہیں، جیسا کہ گزر چکا ہے۔ یہی صحیح ہے۔"],[8534,"§۸۵۵۹ ۔ مُرّہ ہمدانی\nبغوی رحمہ اللہ نے بطریق محمد بن جحادہ، بحوالہ بنت مرہ ہمدانی، انہوں نے اپنے والد سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اپنے رشتہ دار یا کسی اور کے یتیم بچے کی کفالت کرنے والا جب وہ تقویٰ اختیار کرے میرے ساتھ جنت میں ان دو انگلیوں کی طرح ہوگا۔ یعنی شہادت والی انگلی(1) اور اس کے ساتھ والی انگلی۔\nمرہ بن عمرو بن حبیب فہری جو بنو محارب بن فہر کے سوانح میں بطریق صفوان بن سلیم وغیرہ بحوالہ ام سعد بنت مرہ فہری گزر چکا ہے، انہوں نے اپنے والد سے روایت کی ہے، یہ روایت محفوظ ہے۔ واللہ اعلم","",{"fn":"(1) مجمع الزوائد (۱۶۳/۸) المعجم الکبیر (۳۲۰/۲) ادب المفرد (۱۳۳)"}],[8535,"§۸۵۶۰ ۔ مربح بن یاسر جہنی\nاسی طرح ابن مندہ نے ان کا ذکر کیا ہے۔ صحیح یہ ہے: مسروح بن یاسر، جیسا کہ قسم اول میں گزر چکا ہے۔"],[8536,"§۸۵۶۱ ۔ مستورد بن سلامہ\nبن عمرو فہری، صحابی ہیں، فتح مصر میں شریک تھے۔ انہیں وہاں حکومت کی طرف سے پلاٹ ملا۔ فرماتے ہیں: اسکندریہ میں ۴۵ھ میں وفات پائی۔\nان سے علی بن رباح، ورقاء بن شریح نے روایت کی۔ اسی طرح ذہبی رحمہ اللہ نے تجرید میں اسے نقل کیا ہے۔ بقی بن مخلد نے ان سے مروی کئی احادیث کی نشاندہی کی ہے۔ پھر اس کے بعد فرمایا: مستورد بن شداد بن عمرو فہری، صحابی ہیں، جو کوفہ میں اور پھر اس کے بعد مصر میں فروکش ہوئے، ان سے ایک جماعت نے روایت کی، یہ دونوں ایک ہیں، ان کے والد کے نام میں تبدیلی ہے۔ صحیح یہی ہے، جو دوسرے قول میں شداد ہے۔ وہ ابن یونس کی کتاب میں ہے۔"],[8537,"§۸۵۶۲ ۔ مسعدہ(1)\nلشکروں والے ہیں: اسی طرح ذہبی رحمہ اللہ(2) نے تجرید میں مسند بقی بن مخلد کے حوالے سے ان کا نسب بیان کیا ہے۔ صحیح ابن مسعدہ ہے، انہوں نے ذکر کیا کہ ان کا نام عبد اللہ ہے۔ پہلی قسم میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۷۲/۲)\n(2) تجرید (۷۲/۲)"}],[8538,"§۸۵۶۳ ۔ مسعود بن اوس(1)\nابو نعیم نے ان کے اور مسعود بن اوس بن اصرم کے درمیان فرق کیا ہے، یحییٰ بن عبدالوہاب بن مندہ نے اپنے دادا کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے ذیل میں ان کا تعاقب کیا ہے۔ انہوں نے اچھا کیا، وہ ایک ہیں، ابن مندہ نے ان کا ذکر کیا ہے، جیسا کہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۷۵) استیعاب (۲۹۰۶) تجرید (۷۳/۲)"}],[8539,"§۸۵۶۴ ۔ مسعود بن خلدہ(1)\nبن عامر بن مخلد بن زریق انصاری زرقی۔ جعفر مستغفری نے ان کا ذکر کیا ہے اور ان کے والد کے نام میں لفظی غلطی ہے، وہ مسعود بن خالد ہیں جیسا کہ صحیح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۷۴) استیعاب (۲۴۰۶) تجرید (۱۳۹۲/۲)"}],[8540,"§۸۵۶۵ ۔ مسعود بن سعد(1)\nبن قیس بن خلدہ، وہ پہلے والے ہیں، ان کے نسب میں لفظی غلطی ہے۔ ابو عمر نے بے فائدہ اسے دوبارہ نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۸۷) استیعاب (۲۴۰۹) تجرید (۷۴/۲)"}],[8541,"§۸۵۶۶ ۔ مسعود بن سنان سلمی(1)\nابن اثیر(2) نے ان کے اور مسعود بن سنان اسلمی میں فرق کیا ہے۔ وہ ایک ہیں جیسا کہ میں نے پہلی قسم میں بیان کر دیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۸۳) تجرید (۷۴/۲)\n(2) اسد الغابہ (۱۲۰/۴)"}],[8542,"§۸۵۶۷ ۔ مسعود بن عبد سعد(1)\nبن عامر، وہ مسعود بن سعد بن عامر ہیں۔ ابو عمر(2) نے انہیں دو کہا ہے، جبکہ وہ ایک ہیں۔ ان کے والد کے نام میں اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (۴۸۹۲) استیعاب (۲۴/۳) تجرید (۷۴/۲)\n(2) استیعاب (۴۴۹/۳)"}],[8543,"§۸۵۶۸ ۔ مسعود بن عدی لخمی(1)\nابن مندہ نے ان کے اور مسعود بن ضحاک بن عدی کے درمیان فرق کیا ہے۔ ابن مندہ نے ان کے دادا تک ان کا نسب بیان کیا ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، وہ ایک ہیں۔","",{"fn":"(1) استیعاب (۲۴۱۲) تجرید (۷۴/۲)"}],[8544,"§۸۵۶۹ ۔ مسعود بن عمار\nبن ربیعہ قاری، ذہبی نے ان کے اور مسعود بن ربیعہ بن عمرو کے درمیان فرق کیا ہے، وہ ایک ہیں اور ان کے والد کے نام میں اختلاف ہے، ثانی قول زیادہ صحیح ہے۔ ابو عمر نے ان کے دادا تک ان کا نسب بیان کیا ہے۔ فرماتے ہیں: وہ مسعود بن عمرو قاری ہیں، احتمال ہے کہ دوسرے، پہلے والے کے چچا ہوں، پہلی قسم میں ان کا ذکر گزر چکا ہے۔"],[8545,"§۸۵۷۰ ۔ مسعود بن قیس(1)\nبن خلدہ بن مخلد زرقی، ابو عمر(2) نے ان کا ذکر کیا ہے۔ فرماتے ہیں: بدر میں شریک تھے۔ اسی طرح ابن کلبی(3) کا قول ہے: اس میں تردد ہے۔\nمیں کہتا ہوں: مسعود بن سعد بن قیس، آخر تک نسب بیان کیا۔ ان کے والد کا ذکر چھوڑ دیا، تو وہ اپنے دادا کی طرف منسوب ہو گئے، یوں ان کے بارے میں اشکال ہو گیا۔","",{"fn":"(1) اسد الغابہ (۴۸۹۸) استیعاب (۲۴۰/۸)\n(2) استیعاب (۴۵/۳)\n(3) اسد الغابہ (۱۲۲/۴)"}],[8546,"§۸۵۷۱ ۔ مسلم بن سائب(1)\nبن خباب، ان کے والد کے صحابی ہونے میں اختلاف ہے، رہے وہ تو انہوں نے کچھ احادیث مرسل روایت کی ہیں۔ بغوی رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے۔ فرماتے ہیں: میرے گمان میں یہ صحابی نہیں ہیں۔ انہوں نے اپنے والد اور اُم رافع سے روایت کی، ان کی مذکورہ حدیث کو نسائی، بغوی وغیرہ نے بروایت سلیمان بن یسار ان کے حوالے سے روایت کیا ہے، فرماتے ہیں: انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم کیسے بخشش طلب کریں؟ پھر حدیث ذکر کی۔ نسائی کی روایت میں بحوالہ خباب بن الارت مروی ہے، ان کا قول ہے: ابن الارت خطا ہے، صحیح اس کا حذف کرنا ہے، حدیث خباب سے مروی ہے جو مسلم کے دادا ہیں، اس کی طرف بغوی نے اشارہ کیا ہے۔ ابو حاتم رازی کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل حدیث نقل کی ہے، وہ تابعین میں سے ہیں، بعض نے یہ گمان کرتے ہوئے کہ انہیں شرف صحابیت حاصل ہے، صحابہ میں ان کا ذکر کیا ہے، جبکہ ایسا نہیں۔ ابو احمد عسکری کا قول ہے: ان کی حدیث مرسل ہے، ابن حبان نے ثقات تابعین میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ مرسل احادیث روایت کرتے ہیں۔ اسی طرح بخاری رحمہ اللہ اور کئی لوگوں نے تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۹۰۷) الاستيعاب (۲۴۲۳) تجرید اسماء الصحابہ (۷۶/۲)"}],[8547,"§۸۵۷۲ ۔ مسلم بن سلیم\nمرسل حدیث کے روایت کرنے کی وجہ سے بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابن ابی حاتم رحمہ اللہ نے بحوالہ اپنے والد فرمایا: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل حدیث روایت کی، اسی طرح عسکری کا قول ہے۔"],[8548,"§۸۵۷۳ ۔ مسلم بن عبیداللہ(1)\nبن عبد اللہ بن مسلم بن شہاب زہری کے والد ہیں، انہوں نے ابو رغال کے قصے میں نبی کریم صلی اللہ علیہ وسلم سے روایت کیا۔ بعض نے صحابہ میں ان کا ذکر کیا ہے، کئی لوگوں نے یقین کیا ہے کہ انہیں شرف صحابیت اور دیدار حاصل نہیں۔ بخاری رحمہ اللہ اور ابو حاتم کا قول ہے: ان کی حدیث مرسل ہے، اسی طرح ابو احمد عسکری کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۴۹۰۵) استیعاب (۲۴۲۶) تجرید (۷۶/۲)"}],[8549,"§۸۵۷۴ ۔ مسلمہ بن شیبان(1)\nبن محارب بن فہر، ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ فرماتے ہیں: حبیب بن مسلمہ کے والد ہیں۔ اس کی نسبت مستغفری کی طرف ہے۔ صحیح یہ ہے کہ وہ مسلمہ بن مالک ہیں جیسا کہ قسم اول میں گزر چکا ہے، ان کے اور شیبان کے درمیان چھ پشتوں کا فرق ہے، وہ مسلمہ بن مالک بن وہب بن ثعلبہ بن وائلہ بن عمرو بن شیبان بن محارب ہیں۔","",{"fn":"(1) اسد الغابہ (۴۹۲۲) تجرید (۷۷/۲)"}],[8550,"§۸۵۷۵ ۔ مسلمہ بن عبداللہ عدوی\nتابعی ہیں، ان کی حدیث مرسل ہے، بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ عسکری نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کی حدیث مرسل ہے۔"],[8551,"§۸۵۷۶ ۔ مُسیل بن صعصعہ(1)\nان لوگوں میں سے ہیں جو علاء بن حضرمی کے دور میں تھے، ابن فتحون اور ذہبی رحمہ اللہ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ وہ خطا ہے جو لفظی غلطی اور تبدیلی سے پیدا ہوئی۔ وہ مستنیر بن ابی صعصعہ ہیں، قسم اول میں صحیح گزر چکا ہے۔","",{"fn":"(1) تجرید (۷۸/۲)"}],[8552,"§۸۵۷۷ ۔ مُصرّف بن کعب\nبن عمرو یامی، ابن ابی حاتم نے ان کا ذکر کیا ہے، فرماتے ہیں: انہیں شرف صحابیت حاصل نہیں، اسی طرح ابن فتحون نے ان سے نقل کیا ہے اور وہ وہم ہے، ابن ابی حاتم کے الفاظ ہیں۔ مصرف بن کعب بن عمرو، انہوں نے اپنے والد سے روایت کی، بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے، ان کے قول ”لہ“ میں ضمیر ان کے والد کی طرف راجع ہے۔ وہ کعب ہیں۔ اس کے بارے میں اختلاف کعب بن عمرو اور عمرو بن کعب میں گزر چکا ہے، روایت بطریق لیث بن ابی سلیم بحوالہ طلحہ بن مصرف مروی ہے۔ انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی۔ دادا کے بارے میں قول ہے کہ انہیں شرف صحابیت اور نبی کریم صلی اللہ علیہ وسلم سے روایت حاصل ہے۔ ان کے نام کے بارے میں اختلاف ہے۔ رہے مصرف تو انہیں یقینا شرف صحابیت حاصل نہیں۔"],[8553,"§۸۵۷۸ ۔ مُصدق النبی\nبغوی رحمہ اللہ نے حرف میم میں صحابہ میں ان کا ذکر کیا ہے۔ اور بطریق سوید بن غفلہ نقل کیا ہے، فرماتے ہیں: ہمارے پاس مصدق النبی آئے اور فرمایا... پھر حدیث ذکر کی، گویا انہیں وہم ہوا ہے کہ وہ نام ہے۔ رہا لفظ نبی، گویا انہوں نے اسے لکھا نہیں ہے، جائز ہے کہ یہ صفت یا نسب ہو جبکہ ایسا نہیں ہے، وہ صدقہ سے اسم فاعل ہے، اور لفظ نبی مضاف الیہ ہے، اس کی جگہ مبہمات میں ہے۔"],[8554,"§۸۵۸۰ ۔ مُعاذ اسدی\nبشر کے والد ہیں، ان کے والد کے سوانح میں گزر چکے ہیں، اور وہ مختلق ہیں۔"],[8555,"§۸۵۸۱ ۔ معاذ بن حارث\nبن سواد بن مالک بن غنم، بغوی رحمہ اللہ نے بحوالہ ابن اسحاق ان کا ذکر کیا ہے کہ انہوں نے بدر میں حاضر ہونے والوں میں ان کا ذکر کیا ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، وہ وہم ہے جو رہ جانے سے پیدا ہوا، وہ معاذ بن رفاعہ بن حارث بن سواد ہیں، ان کے نسب سے دو آدمی رہ گئے ہیں قسم اول میں صحیح گزر چکا ہے، وہ ابن عفراء کے نام سے معروف ہیں۔"],[8556,"§۸۵۸۲ ۔ معاذ بن رباح(1)\nبعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، ان کے بیٹے ابو زہیر بن معاذ کو شرف صحابیت حاصل ہے، کنیتوں میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۴۹۶۳) تجرید (۸۱/۲)"}],[8557,"§۸۵۸۳ ۔ معاذ بن زہرہ(1)\nیحییٰ بن یونس شیرازی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، وہ تابعی ہیں۔ انہوں نے مرسل حدیث روایت کی ہے۔ ابو داؤد رحمہ اللہ نے مراسیل میں ان کا ذکر کیا ہے۔\nجعفر مستغفری کا قول ہے: جس کا یہ گمان ہے کہ وہ صحابی ہیں اسے وہم ہوا ہے، بخاری نے بحوالہ یحییٰ بن معین فرمایا: ان کی حدیث مرسل ہے، بغوی رحمہ اللہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، لیکن فرمایا: مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہے کہ نہیں؟","",{"fn":"(1) ابوداؤد فی مراسیلہ (حدیث: ۹۱)"}],[8558,"§۸۵۸۴ ۔ معاذ بن سعوہ\nذہبی رحمہ اللہ نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے، فرماتے ہیں: منتقی میں مخلص کے بارے میں ان کی حدیث ہے۔ میں کہتا ہوں: یہ عبد الکریم بن ابی مخارق کی بحوالہ سنان بن سلمہ، ان کے حوالے سے روایت ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کا ہدی کا جانور تھک جائے وہ اسے نحر کر لے...“ (الحدیث) اس روایت میں عبد الکریم کے ضعیف ہونے کے ساتھ ساتھ ان سے روایت کرنے والوں میں اختلاف ہے۔ بعض کا قول ہے: ان سے بحوالہ سنان بن سلمہ روایت ہے، انہوں نے سلمہ بن محبق سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا ہے، بعض کا قول ہے: عن عبد الکریم عن معاذ بن سعوہ عن سنان بن سلمہ عن سلمہ بن محبق، بخاری رحمہ اللہ نے تابعین میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی حدیث مرسل ہے۔"],[8559,"§۸۵۸۵ ۔ معاذ بن معدان(1)\nعمران بن خدیر نے ان سے روایت کی کہ قطبہ بن جریر نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے بیعت کی۔ ابو عمر(2) کا قول ہے: بعض کا قول ہے: ان کی حدیث مرسل ہے۔\nمیں کہتا ہوں: ابن ابی حاتم سے ان کا نام منقول ہے، وہ مقاتل بن معدان ہیں، قطبہ کے سوانح میں دو مقامات پر ان کا صحیح نام منقول ہے۔ مقاتل بالاتفاق تابعی ہیں، قطبہ، ابو یصلہ ہیں، حرف قاف کی قسم اول میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۴۹۷۲) استیعاب (۲۴۵۴)\n(2) استیعاب (۴۶۷/۳)"}],[8560,"§۸۵۸۶ ۔ معاویہ بن ثعلبہ جمانی(1)\nتابعی ہیں، انہوں نے مرسل حدیث روایت کی ہے، اسماعیلی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: مجھے معلوم نہیں انہیں شرف صحابیت حاصل ہے یا نہیں۔\nان کی حدیث بطریق عامر بن سمط، بحوالہ ابو الجحاف، ان کے حوالے سے منقول ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے علی! جس نے تم سے محبت کی، اس نے مجھ سے محبت کی...“(2) (الحدیث) اسے ابو موسیٰ نے نقل کیا ہے۔ بخاری(3) نے یہ حدیث اس طریق سے بروایت معاویہ بن ثعلبہ، بحوالہ ابو ذر نقل کی ہے۔ اسی طرح ابو حاتم وغیرہ نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۴۹۷۷) تجرید (۸۲/۲)\n(2) جامع المسانید والسنن (۵۲۹/۱۱) اسد الغابہ (۱۵۱/۴)\n(3) تاریخ کبیر (۳۳/۴)"}],[8561,"§۸۵۸۷ ۔ معاویہ بن حزن\nاسی طرح میں نے مؤتلف میں خطیب کی تحریر میں دیکھا ہے۔ جو کہ حزن ضبہ کے بارے میں ہے، میرے خیال میں وہ لفظی غلطی کی وجہ سے حیدہ سے حزن ہو گیا۔ قسم اول میں ان کا ذکر گزر چکا ہے۔"],[8562,"§۸۵۸۸ ۔ معاویہ بن درہم\nقسم اول میں ان کی طرف اشارہ گزر چکا ہے۔"],[8563,"§۸۵۸۹ ۔ معاویہ بن ربیعہ جُشمی\nعبد اللہ بن ابو بکر بن ربیعہ میں ان کا ذکر گزر چکا ہے۔"],[8564,"§۸۵۹۰ ۔ معاویہ بن زہرہ\nبعض نے ان کا ذکر کیا ہے، ان کی حدیث مرسل ہے، یہ عسکری کا قول ہے۔ اسی طرح میں نے مغلطائی کی تحریر میں پڑھا ہے، مجھے خوف ہے کہ وہ معاذ ابن زہرہ ہوں، جن کے حالات قریب میں گزر چکے ہیں۔"],[8565,"§۸۵۹۱ ۔ معاویہ بن عبادہ(1)\nبن عقیل، کعب اخیل بن رجال کے والد ہیں، انہیں وفد کے ساتھ آنے کی سعادت حاصل ہے، اسی طرح تجرید(2) میں ہے: یہ غلطی ہے جو رہ جانے سے پیدا ہوئی، وفد میں آنے کی سعادت ان کے بیٹے ہبیرہ بن معاویہ کو حاصل ہوئی، جیسا کہ ان کے حالات میں حرف حاء میں آئے گا، رہے معاویہ تو انہیں ”فارس ہزار“ کہا جاتا تھا، ہزار ان کا گھوڑا تھا جو جاہلیت میں مشہور تھا۔ ابن کلبی نے ذکر کیا ہے کہ یہ وہی ہیں جنہوں نے زہیر بن جذیمہ رئیس بنی عبس کو جاہلیت میں نیزہ مارا تھا، ان کے بیٹے کا ذکر جاہلیت میں ہے، اسے ابن المفاضہ کہا جاتا ہے، ان کے بھائی بہیرہ کے سوانح میں ان کا ذکر آئے گا۔ میں کہتا ہوں: کعب اخیل کے نام سے معروف ہیں، وہ مشہور قبیلہ کے جد امجد ہیں، اس سے عبد الملک بن مروان کے زمانے میں لیلیٰ اخیلیہ شاعرہ تھیں، وہ لیلیٰ بنت عبد اللہ بن معاذ ابن شداد بن کعب ہیں۔","",{"fn":"(1) تجرید (۸۳/۲)\n(2) التجرید (۸۳/۲)"}],[8566,"§۸۵۹۲ ۔ معاویہ بن عبداللہ(1)\nبن ابی احمد، ابن ابی علی نے صحابہ میں ان کا ذکر کیا ہے، وہ وہم ہے جو حذف کی وجہ سے پیدا ہوا، انہوں نے بطریق عبد الرحمن بن حارث بحوالہ عاصم بن عبید اللہ، انہوں نے ان کے حوالے سے نقل کیا ہے۔ فرماتے ہیں: میں نے حمنہ بنت جحش کو دیکھا وہ اُحد کے دن پیاسوں کو پانی پلاتی تھیں اور زخمیوں کا علاج کرتی تھیں، اس حدیث کو معاویہ نے اس طریق سے بحوالہ انس نقل کیا ہے، اسی طرح بخاری(2) رحمہ اللہ اور ابو حاتم(3) وغیرہ نے ان کا ذکر کیا ہے۔ فرماتے ہیں کہ ابو ضمرہ نے ان سے روایت کی، ابو ضمرہ بعض تابعین سے ملے، ان کے دادا ابو احمد مشہور صحابی ہیں، ان کے والد عبد اللہ بن ابو احمد ہیں، انہیں دیدار حاصل ہے۔ ذہبی رحمہ اللہ کا گمان ہے کہ یہ دوسرے ہیں، فرماتے ہیں: معاویہ بن عبد اللہ بن احمد احد میں شریک ہوئے، مجھے معلوم نہیں کہ حالت ایمان میں یا حالت کفر میں حمنہ ان کے والد کی پھوپھی ہیں۔","",{"fn":"(1) اسد الغابہ (۴۹۸۶) تجرید (۸۳/۲)\n(2) تاریخ کبیر (۳۳۱/۴)\n(3) الجرح والتعدیل (۳۷۹/۸)"}],[8567,"§۸۵۹۳ ۔ معاویہ بن معبد\nابن قانع نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، یہ وہم ہے۔ انہوں نے بطریق عاصم بن سوید، بحوالہ عبد الرحمن، انہوں نے اپنے دادا معاویہ بن معبد سے نقل کیا ہے، مالک بن کعب نے کہا:(1) ”سخینہ کا گمان ہے کہ وہ اپنے مالک پر غالب آ جائے گی اور مغالب الغلاب ضرور مغلوب ہوگا۔“ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے تمہاری اس بات کی قدردانی کی کہ تم نے ٹھیک کہا“۔(2)","",{"fn":"(1) اسد الغابہ (۴۹۹۸) استیعاب (۲۴۷۱)\n(2) جرح والتعدیل (۲۷۹/۸)"}],[8568,"§۸۵۹۴ ۔ معبد بن خالد جہنی(1)\nتابعی ہیں، مرسل حدیث روایت کرتے ہیں، بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، بعض کا قول ہے، وہ معبد جہنی ہے جس نے سب سے پہلے بصرہ(2) میں تقدیر پر بحث کی تھی، وہ صحابہ رضی اللہ عنہم کے زمانے میں تھا۔ لیکن صحابی نہیں، اس کے والد کے نام میں اختلاف ہے، جیسا کہ پہلی قسم میں گزر چکا ہے۔ مہ واللہ اعلم(3)","",{"fn":"(1) استیعاب (۴۷۸/۳)\n(2) اسد الغابہ (۵۰۰۲) استیعاب (۲۴۷۴) تجرید (۸۵/۲)\n(3) ابن عدی الکامل فی الضعفاء (۱۰۲۷/۳) نصب الرایہ (۵۱/۱) جامع المسانید والسنن (۶۶۹/۱۱) اسد الغابہ (۱۶۲/۴)"}],[8569,"§۸۵۹۵ ۔ معبد بن صبیح(1)\nابو نعیم نے ان کا تذکرہ کیا ہے اور بطریق اسحاق بن ابراہیم، بحوالہ معبد روایت نقل کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز پڑھ رہے تھے کہ ایک نابینا آیا اور گڑھے میں گر گیا۔۔۔۔ (الحدیث) اس میں ہے ”تم میں سے جو اونچی آواز میں ہنسے، وہ اپنے وضو اور نماز کو لوٹائے“(2)\nابو نعیم کا قول ہے: اسے اسد بن عمرو نے بحوالہ ابو حنیفہ روایت کیا ہے، فرماتے ہیں: معبد بن صبیح، اور اسے مکی بن ابراہیم نے بحوالہ ابو حنیفہ روایت کیا ہے، فرماتے ہیں: معبد بن ابی معبد اسے ابو موسیٰ نے اسی طرح بغیر زیادتی کے نقل کیا ہے۔ ابن اثیر(3) نے ابو موسیٰ پر اپنے استدراک میں ان کا ذکر کرنے کی وجہ سے ان پر نکیر کی ہے، فرماتے ہیں: ابن مندہ نے معبد بن ام معبد نقل کیا ہے، نماز میں ہنسنے کے بارے میں ان کی حدیث نقل کی ہے، تو ابو موسیٰ کے استدراک کی کوئی وجہ نہیں ہے۔ میں کہتا ہوں: حدیث قہقہہ کے راوی، بعض کا قول ہے: معبد جہنی ہے، جو تقدیر کے بارے میں بحث کرتا تھا، اس سے پہلے والے حالات میں اس کا ذکر ہے۔ بعض کا قول ہے: وہ معبد بن ام معبد ہیں جن کے پاس سے ہجرت کے وقت نبی کریم صلی اللہ علیہ وسلم گزرے تھے، یہ درست نہیں(4)، کیونکہ حدیث قہقہہ کے روایت کرنے والے جنی ہیں اور ام معبد کا بیٹا خزاعی ہے، میں نے قسم اول میں ان کے سوانح میں ذکر کیا ہے، نام اور والد کی کنیت کے اشتراک سے ایسا ہوا ہے۔","",{"fn":"(1) اسد الغابہ (۱۶۸/۴)\n(2) مسند بزار (۱۳۴۱) مجمع (۵۵/۶)\n(3) اسد الغابہ (۴۹۹۴) استیعاب (۲۴۷۲) تجرید (۸۵/۲)\n(4) استیعاب (۴۷۹/۳)"}],[8570,"§۸۵۹۶ ۔ مُعبد\nابو زہیر نمری ہیں، اسی طرح ابن عبد البر نے ان کا ذکر کیا ہے، کنیتوں میں ان کی مخالفت کی ہے، ان کا نام یہ بھی لیا ہے، صحیح ہے، کئی لوگوں نے اس پر اعتماد کیا ہے، جیسا کہ آگے آئے گا۔"],[8571,"§۸۵۹۷ ۔ معبد یکرب(1)\nان سے خالد بن معدان نے حدیث نقل کی ہے، اسے ابو موسیٰ نے ذیل میں نقل کیا ہے۔ ابن اثیر(2) رحمہ اللہ نے ان کے اور معبد یکرب ہمدانی کے درمیان فرق کیا ہے، جن کا ابو احمد عسکری نے ذکر کیا ہے۔ فرماتے ہیں: مجھے معلوم نہیں کہ وہ ایک ہیں، یا دو ہیں؟\nمیں کہتا ہوں: دونوں طریق کے راوی خالد بن معدان ہیں، جو ایک ہونے کی دلیل ہے۔(3)","",{"fn":"(1) اسد الغابہ (۵۰۲۸)\n(2) اسد الغابہ (۱۶۸/۴)\n(3) جامع المسانید والسنن (۶۲۸/۱۱)"}],[8572,"§۸۵۹۸ ۔ معروف ثقفی\nابن قانع نے ان کے حالات نقل کیے ہیں، انہیں وہم ہوا ہے کیونکہ وہ صفت ہے، نام نہیں، فرماتے ہیں: ہم سے عبد اللہ بن احمد نے بحوالہ عبد اللہ بن عثمان ثقفی، انہوں نے ثقیف کے ایک آدمی سے روایت کی، انہیں معروف کہا جاتا ہے، انہوں نے ان کے بارے میں اچھے الفاظ کہے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ولیمہ ایک حق ہے...“(1) پھر اسے بطریق حجاج بحوالہ ہمام روایت کیا ہے، فرماتے ہیں: اس میں ہے: بحوالہ زہیر بن عثمان، اعور، ابن قانع کا قول ہے: قتادہ کو اس میں شک ہے۔ انہوں نے بحوالہ بہز بن اسد، انہوں نے بحوالہ عبد اللہ بن عثمان، انہوں نے ثقیف کے ایک اعور شخص سے روایت کی۔ قتادہ کا قول ہے: انہیں معروف کہا جاتا تھا۔ یعنی ان کے بارے میں اچھے الفاظ کہے جاتے تھے۔ قتادہ کے قول کی مراد کی تفسیر بہز نے ان الفاظ میں کی ہے: انہیں معروف کہا جاتا تھا۔ جس کی تائید حجاج بن منہال کی روایت میں ان کا نام زہیر بن عثمان بتانے سے بھی ہوتی ہے، اسی طرح عبد الصمد بن عبد الوارث نے بحوالہ ہمام ان کا نام لیا ہے۔ اسے احمد رحمہ اللہ نے بھی نقل کیا ہے۔ دارمی رحمہ اللہ نے اپنی مسند میں فرمایا: ہمیں عفان نے بحوالہ ہمام بتایا، انہوں نے ان کا تذکرہ ان الفاظ میں کیا ہے جس سے اشکال بالکل رفع ہو جاتا ہے۔ چنانچہ فرماتے ہیں: ثقیف کے امر معروف نامی شخص سے روایت کی جاتی ہے، یعنی ان کے بارے میں اچھے الفاظ کہے جاتے تھے، اگر ان کا نام زہیر بن عثمان نہیں ہے تو مجھے معلوم نہیں کہ ان کا کیا نام ہے۔ اسی طرح یہ ابو داؤد، نسائی کے ہاں بحوالہ عفان مروی ہے، حرف زاء، قسم اول میں گزر چکا ہے۔ واللہ اعلم!","",{"fn":"(1) ابوداؤد (۳۷۴۵) ابن ماجہ (۱۹۱۵) مسند احمد (۲۰۳۴۵) سنن دارمی (۱۰۵/۲) السنن الکبریٰ (۲۶۰۱) کنز (۴۶۲۳)"}],[8573,"§۸۵۹۹ ۔ مُعلیٰ بن اسماعیل\nمرسل حدیث کی وجہ سے بعض نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، جسے عمارہ بن غزیہ وغیرہ نے ان کے حوالے سے، نبی کریم صلی اللہ علیہ وسلم سے نقل کیا ہے۔ بخاری رحمہ اللہ کا قول ہے: یہ روایت مرسل ہے۔"],[8574,"§۸۶۰۰ ۔ معمر(1)\nابو خزیمہ کے والد ہیں، بعض نے مرسل حدیث کے روایت کرنے کی وجہ سے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ ابو موسیٰ(2) نے ذیل میں ان کا ذکر کیا ہے، اور تاریخ یعقوب بن سفیان کے حوالے سے نقل کیا ہے، وہ عمر ہیں، ان کے مقام پر ان کا ذکر آئے گا۔ اس کے بارے میں اختلاف حارث بن سعد کے حالات میں گزر چکا ہے، اور اس قسم میں سعد بن ہذیم کے سوانح میں بھی گزر چکا ہے۔(3)","",{"fn":"(1) اسد الغابہ (۵۰۴۵) تجرید (۸۹/۲)\n(2) ابن ماجہ (۳۴۳۷) مسند احمد (۴۲۱/۳) مستدرک حاکم (۱۹۹/۴) جامع المسانید والسنن (۷۱۹/۱۱)\n(3) اسد الغابہ (۵۰۴۰) تجرید (۸۸/۲)"}],[8575,"§۸۶۰۱ ۔ معمر مدنی\nنبی کریم صلی اللہ علیہ وسلم ان کے پاس سے گزرے، وہ اپنی ران کھولے ہوئے تھے۔ ابو موسیٰ نے ابن شاہین کے اتباع میں ان میں اور معمر بن عبد اللہ بن نصلہ میں فرق کیا ہے۔ وہ ایک ہیں، جیسا کہ قسم اول میں میں نے اس کی وضاحت کر دی ہے۔"],[8576,"§۸۶۰۲ ۔ معمر انصاری(1)\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور بطریق روح، بحوالہ معمر انصاری، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جس نے وہ علم سیکھا جس سے اللہ تعالیٰ آخرت میں نفع دیتا ہے، اور یہ اسے دنیا کی نیت سے سیکھتا ہے تو اللہ اس کے لیے جنت کی خوشبو حرام کر دے گا۔ ابو موسیٰ(2) کا قول ہے: میرا خیال ہے وہ عبد اللہ بن عبد الرحمن بن معمر ہیں، شاید انہوں نے لفظی غلطی کی ہے۔\nمیں کہتا ہوں: ایسا ہی ہے جو انہوں نے گمان کیا، کیونکہ یہ متن ابو طوالہ کی روایت سے معروف ہے، ان کا نام عبد اللہ بن عبد الرحمن ہے، اسے سعید بن سیار نے روایت کیا ہے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ اسے ابو داؤد اور نسائی نے بطریق فلیح بن سلیمان ان کے حوالے سے نقل کیا ہے، شاید عبد العزیز نے اسے مرسل نقل کیا ہے۔ ابن معمر لفظی غلطی کی وجہ سے معمر ہو گیا، اس طرح ایک صحابی کا نام پیدا ہوا جس کا وجود نہیں۔ واللہ المستعان!","",{"fn":"(1) ابوداؤد (۳۶۶۴) ابن ماجہ (۲۵۴) مسند احمد (۳۳۸/۲) مستدرک حاکم (۸۵/۱) صحیح ابن حبان (۷۸) جامع المسانید والسنن (۷۲۰/۱۱)\n(2) میزان الاعتدال (۱۵۶/۴) (۸۶۹۱)"}],[8577,"§۸۶۰۳ ۔ معمر بن بُریک\nذہبی رحمہ اللہ نے میزان میں ان کا ذکر کیا ہے، تجرید الصحابہ میں ان کا ذکر نہیں کیا۔ وہ ان کی شرط کے مطابق ہیں، میزان میں یہ الفاظ ہیں: معمر یا معمر بن بُریک، میں نے ایک صفحہ دیکھا اس میں کچھ احادیث تھیں، مجھ سے ان کے صحیح ہونے کے بارے میں پوچھا گیا، میں نے جواب دیا کہ وہ باطل ہیں، وہ واضح جھوٹ ہیں، ان میں ہے: ہمیں احمد بن ابراہیم سامی نے، وہ فرماتے ہیں: ہمیں عبد اللہ بن اسحاق سنجاری نے، وہ فرماتے ہیں: ہمیں عبد اللہ بن موسیٰ سنجاری نے، وہ فرماتے ہیں کہ میں نے علی بن اسماعیل سنجاری سے سنجار میں ۶۲۷ ھ میں فرماتے ہوئے سنا، وہ فرماتے ہیں کہ میں نے معمر بن بریک سے فرماتے ہوئے سنا کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”آدمی بوڑھا ہو جاتا ہے اور اس کی دو خصلتیں جوان ہوتی ہیں: حرص اور اُمید۔۔۔۔“ اس میں ہے: ”چار آدمیوں کو جہنم کے کنارے سولی دی جائے گی، فیصلے میں ظلم کرنے والا اور آل محمد صلی اللہ علیہ وسلم سے بغض رکھنے والا۔۔۔۔ (الحدیث) شیبانی کا قول ہے: ہمیں عبد الحمود مورب نے سنجار میں بتایا کہ ہمیں صدر نے بحوالہ عبد الوہاب بتایا کہ میں نے علی بن اسماعیل سنجاری کو کہتے ہوئے سنا کہ میں نے معمر بن بُریک سے سنا کہ وہ فرماتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جس نے گلاب کی خوشبو سونگھی اور مجھ پر درود نہ پڑھا اس نے مجھ سے جفا کی۔“ ذہبی رحمہ اللہ کا قول ہے: یہ رتن ہندی کا طرز ہے۔ اللہ اس کا برا کرے جو جھوٹ بولتا ہے۔"],[8578,"§۸۶۰۴ ۔ مَعَمَّر(1)\nیہ فرضی شخصیت ہے، کسی مغربی کذاب نے اس کا نام گھڑا ہے۔ ہمیں کمال ابو البرکات بن ابی زید مکناسی نے تحریری اجازت دی، فرماتے ہیں: مجھ سے میرے والد نے مصافحہ کیا، وہ سو(۱۰۰) برس تک زندہ رہے، فرماتے ہیں: مجھ سے شیخ ابو الحسن علی حطاب نے تونس میں مصافحہ کیا وہ ایک سو تیس(۱۳۰) برس زندہ رہے، فرماتے ہیں: مجھ سے شیخ ابو عبد اللہ محمد صقلی نے مصافحہ کیا، وہ ایک سو ساٹھ(۱۲۰) برس زندہ رہے، فرماتے ہیں: مجھ سے عبد اللہ معمر نے مصافحہ کیا، ان کی عمر چار سو(۴۰۰) سال تھی، فرماتے ہیں: ”مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے مصافحہ کیا اور مجھے دعا دی، فرمایا: اے معمر اللہ تمہیں لمبی عمر دے۔“\nمیں کہتا ہوں: یہ رتن، قیس بن تمیم، ابو الخطاب، مکلمہ اور نسطور کی طرح ہیں، لسان المیزان میں میں نے معمر کے سوانح میں تفصیل سے ذکر کیا ہے۔ میں ان کا یہاں طویل ذکر نہیں کرنا چاہتا۔ مجھے معمر کی ایک اور حدیث ملی ہے، جسے میں نے حرف عین میں عمار کے سوانح میں ذکر کیا ہے۔ ان کا قصہ رتن ہندی سے ملتا ہے، جو ان کے زمانے میں تھے۔ ابو حسن بن ابی نصر بجانی نے ذکر کیا ہے کہ انہوں نے انہیں قطنہ نامی شہر میں دیکھا ہے جو بلادِ ترک کے آخر میں ہے، ان کی ایک اور حدیث مجھے ملی ہے جسے میں نے حرف جیم میں جبیر بن حارث میں ذکر کیا ہے کہ وہ چھٹی صدی کے بعد تھا۔ اسے ناصر لدین اللہ العباسی نے روایت کیا ہے کہ وہ ایک دفعہ شکار کرنے گیا تھا، تو شکار انہیں ایک ایسے مقام پر لے گیا کہ وہاں انہیں ایک بستی نظر آئی، اس بستی والوں کا کہنا تھا کہ ہم سب معمر کی اولاد ہیں۔ میں نے الحمد للہ، اللہ کی توفیق سے، کتاب المعمرین میں ان سب کے مکمل حالات قلم بند کیے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۰۵)"}],[8579,"§۸۶۰۵ ۔ معن بن یزید خفاجی(1)\nخفاجہ عقیل سے ہیں، انہیں شرف صحابیت حاصل ہے۔ ابو نعیم نے ان کا ذکر کیا ہے۔ قسم اول میں ان کے حالات میں نے ذکر کر دیے ہیں۔","",{"fn":"(1) اسد الغابہ (۵۰۵۵) تجرید (۹۰/۲)"}],[8580,"§۸۶۰۶ ۔ معن بن زائدہ\nابو الحسن بن قصار مالکی نے ذکر کیا ہے کہ سیدنا عمر رضی اللہ عنہ کے پاس ایک خط لایا گیا جو معن بن زائدہ نے اپنے پاس سے سیدنا عمر رضی اللہ عنہ کی طرف سے لکھا اور اس پر ان کی انگوٹھی کی مہر کی طرح مہر تھی، سیدنا عمر رضی اللہ عنہ نے انہیں سو(۱۰۰) کوڑے مارے پھر انہیں قید میں ڈال دیا، پھر کچھ لوگوں نے ان کی سفارش کی، انہوں نے کہا: تم نے مجھے طعن یاد دلایا میں اسے بھول گیا تھا، پھر انہیں سو(۱۰۰) اور کوڑے مارے پھر تیسری دفعہ سو(۱۰۰) کوڑے اور مارے۔ اس وقت علما موجود تھے، کسی نے ان پر نکیر نہ کی، یہ اجماع تھا۔\nمیں کہتا ہوں: اس بارے میں حقیقت یہ ہے۔ اگر یہ ثابت ہو تو احتمال ہے کہ یہ اجتہاد ہو، اس لیے انہوں نے اس پر نکیر نہ کی، کیونکہ ایک مجتہد کا قول دوسرے پر حجت نہیں ہے۔ اس سے لازم نہیں آتا کہ وہ لوگ اس کے جواز کے قائل ہوں، تو اجتماع کہاں ہوا؟ یہ حکم کی حیثیت سے تھا، معن کا دور نبوی نہ پانا واضح ہے، اگر یہ ثابت ہو تو میں نے قسم ثالث میں ان کا ذکر کر دیا ہے، لیکن معن بن زائدہ نے یہ زمانہ نہیں پایا، وہ بنو امیہ کے دور حکومت کے آخر اور بنو عباس کی حکومت کے شروع میں تھے، یمن کے امیر بنائے گئے، شجاعت اور سخاوت کے بارے میں ان کے مشہور واقعات ہیں، احتمال ہے کہ یہ محفوظ ہو، اور ان لوگوں میں سے ہوں جن کا نام اور ان کے والد کا نام موافق ہو گیا ہو، اگر چہ یہ بعید ہے۔"],[8581,"§۸۶۰۷ ۔ معیقیب بن مُعَرَّض یمامی(1)\nشام صوریہ بن عبید نے ان کی حدیث، بحوالہ معترض بن عبد اللہ بن معیقیب، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے نقل کی ہے، فرماتے ہیں: میں نے حجۃ الوداع کے سال حج کیا۔۔۔۔ (الحدیث)(2) ابن مندہ نے ذکر کیا ہے کہ ابو نعیم کا قول ہے: یہ وہم ہے، وہ معرض بن معیقیب ہیں، یعنی ان کا نام الٹ گیا ہے، صحیح گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۵۹) تجرید (۹۰/۲)\n(2) دلائل النبوۃ (۵۹/۶) (۶۰/۶) کنز (۲۵۴۰۱) جامع المسانید والسنن (۶۷۹/۱۱) اسد الغابہ (۱۷۸/۴)"}],[8582,"§۸۶۰۸ ۔ مغیرہ بن حارث(1)\nبن ہشام مخزومی، ابو نعیم نے ان کا ذکر کیا ہے، فرماتے ہیں: ان کے صحابی ہونے میں اختلاف ہے، حضرمی یعنی محمد بن عبد اللہ جو معروف ہیں، مطین کے نام سے، انہوں نے وحدان میں ان کا ذکر کیا ہے اور بحوالہ مغیرہ بن حارث بن ہشام، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مؤمن کے لیے مہینے میں ایک بار جماع کرنا کافی ہے۔“(2)\nمیں کہتا ہوں: مغیرہ اور حارث کے درمیان عبد الرحمن کا ذکر رہ گیا ہے، اسی طرح بخاری(3) رحمہ اللہ نے اپنی تاریخ میں ان کے پوتے کے سوانح میں ذکر کیا ہے، فرماتے ہیں: مغیرہ بن یحییٰ بن مغیرہ بن عبد الرحمن بن حارث، قدامہ بن محمد مدنی نے ان کے حوالے سے، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے مرسل روایت کیا ہے۔\nمیں کہتا ہوں: عبد الرحمن بن حارث کو دیدار حاصل ہے، وہ ابو بکر کے والد ہیں جو فقہائے مدینہ میں سے ہیں، یہ مغیرہ ان کے بھائی ہیں، خلافت معاویہ میں ان کی ولادت ہوئی، انہوں نے زمانہ نبوت ہرگز نہیں پایا۔","",{"fn":"(1) اسد الغابہ (۵۰۶۹) تجرید (۹۱/۲)\n(2) کنز العمال (۴۴۸۶۷) اسد الغابہ (۱۸۱/۴)\n(3) تاریخ کبیر (۳۳۸/۴)"}],[8583,"§۸۶۰۹ ۔ مغیرہ بن سلمان خزاعی(1)\nتابعی ہیں، انہوں نے مرسل حدیث روایت کی، ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق حمید طویل، ان کے حوالے سے نقل کیا ہے کہ دو آدمی کسی چیز کے بارے میں اپنا جھگڑا لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا تمہیں آدھے میں رغبت ہے، اور اپنے دست مبارک سے اشارہ کیا۔“ ابے بغوی(2) نے صحیح سند سے نقل کیا ہے جسے وہ حمید تک لے گئے ہیں۔ ابن ابی حاتم نے مغیرہ کو جن کا ذکر ہو رہا ہے، تابعین میں ذکر کیا ہے۔ فرماتے ہیں: انہوں نے سیدنا ابن عمر رضی اللہ عنہما سے روایت کی، اسی طرح ابن حبان نے ثقات میں ان کا ذکر کیا ہے۔ ان کی ابن عمر رضی اللہ عنہما کے حوالے سے روایت نسائی کے ہاں ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۶۳) تجرید (۹۱/۲)\n(2) اسد الغابہ (۱۸۱/۴)"}],[8584,"§۸۶۱۰ ۔ مغیرہ بن فلان\nیا فلان بن مغیرہ مخزومی۔ بنو مخزوم سے ہیں، ابن سعد نے طبقات میں بحوالہ شعبی روایت نقل کیا ہے، فرماتے ہیں: مجھ سے فاطمہ بنت قیس نے نقل کیا ہے کہ وہ مغیرہ ابن فلان یا فلان ابن مغیرہ کی زوجہ تھیں، جو بن مخزوم سے تھے، پھر حدیث ذکر کی۔\nمیں کہتا ہوں: ایسا لگتا ہے اس حدیث کے راوی کو ان کا نام یاد نہیں، انہوں نے انہیں ان کے جد اعلیٰ کی طرف منسوب کر دیا، با وجودیکہ انہیں تردد ہوا تو انہوں نے اسے الٹ کر دیا، کہا: مغیرہ ابن فلاں، یہ دونوں غلط ہیں۔ وہ ابو عمرو بن حفص بن مغیرہ بن عبد اللہ بن عمر بن مخزوم ہیں۔ بعض کا قول ہے: وہ ابو حفص بن عمرو بن عمرو بن مغیرہ ہیں، کنیتوں میں ان کا ذکر آئے گا۔"],[8585,"§۸۶۱۱ ۔ مغیرہ بن عتبہ\nابن نحاس، تابعی ہیں، انہوں نے مرسل حدیث نقل کی ہے، ابن فتحون نے استیعاب کے ذیل میں ان کا ذکر کیا ہے اور بحوالہ محمد بن عثمان بن ابی شیبہ، انہوں نے یعلی بن یحییٰ محاربی سے، انہوں نے اپنے والد سے بحوالہ مغیرہ بن عتبہ نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کی مدحے پر تھے اور سیدنا علی رضی اللہ عنہ آپ کے پیچھے سوار تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”کہو! اے اللہ! میری مغفرت فرما، اے اللہ! مجھ پر رحم فرما، اے اللہ! مجھ پر مہربانی فرما، شاید تمہیں ان میں سے کوئی حاصل ہو“۔\nابن فتحون کا قول ہے: سیف نے فتوح میں ذکر کیا ہے کہ خالد بن ولید نے مغیرہ کے والد ابن عقبہ کو بکر بن وائل میں سے لہازم پر تیر انداز صحابہ رضی اللہ عنہم میں سے جنگ کے موقع پر مقرر کیا، یعنی جب ان کے والد صحابی ہیں تو جائز ہے کہ ایسا ہی ہو، لیکن حقیقت اس کے برعکس ہے، ان کا شمار صغار تابعین کے طبقہ میں ہوتا ہے، جنہوں نے کبار تابعین سے روایت کی جیسے موسیٰ بن طلحہ، ابن ابی حاتم وغیرہ نے ان کی کنیت نقل کی ہے۔"],[8586,"§۸۶۱۲ ۔ مفروق بن عمرو(1)\nقسم ثالث میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۷۴)"}],[8587,"§۸۶۱۳ ۔ مُفَضَّل بن ابی الہیثم تغلبی\nابن قانع نے ان کا ذکر کیا ہے، فرماتے ہیں: ہم سے بشر بن موسیٰ نے بحوالہ مفضل بن ابی الہیثم نقل کیا، جو ان کے حلیف ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے پیشاب، پاخانے میں قبلہ رخ ہونے سے منع کیا ہے۔ ابن قانع کا قول ہے: اسی طرح بشر کا قول ہے، میرے نزدیک وہ خطا ہے۔ صحیح یہ ہے کہ وہ معقل ہیں۔"],[8588,"§۸۶۱۴ ۔ مقطم بن مقدام صحابی\nفرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی سفر کا ارادہ کرتا ہے تو اپنے گھر والوں کے پاس سب سے بہتر چیز دو رکعتیں چھوڑتا ہے جو وہ ان کے پاس ادا کرتا ہے۔“ اسے طبرانی(1) نے نقل کیا ہے، حافظ زین الدین بن رجب حنبلی نے ان کا تعاقب کیا ہے، میں نے ان کے قلم سے لکھا ہوا پڑھا ہے، جس کی عبارت یہ ہے: اسی طرح میں نے نووی کے قلم سے لکھا ہوا پڑھا ہے۔ ان سے عجیب لفظی غلطی ہوئی کیونکہ یہ وہی روایت ہے جسے طبرانی رحمہ اللہ نے اپنی کتاب مناسک میں نقل کیا ہے، بحوالہ مطعم بن مقدام صنعانی، انہوں نے مطعم کو مقطم کر دیا اور صنعانی کو صحابی کر دیا۔ مطعم بن مقدام تبع تابعین میں سے ہیں، ان کی بحوالہ مجاہد اور سعید بن جبیر وغیرہ سے روایات مشہور ہیں۔ انہوں نے یہ حدیث مرسل نقل کی ہے، حالانکہ یہ معضل ہے، اسے ابو بکر بن ابی شیبہ نے اپنی مصنف میں بحوالہ مطعم بن مقدام نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا پھر اسے ذکر کیا، طبرانی نے اس طریق سے اسے نقل کیا ہے۔ ایسا ہی ہے جیسے ابن رجب کا قول ہے مطعم کی سنن ابو داؤد اور نسائی میں تابعین کی ایک جماعت سے روایت ہے، ان میں سے مجاہد ہیں جو اوزاعی کے شیوخ میں سے ہیں، اور ابو اسحاق فزاری، ایک جماعت نے انہیں ثقہ قرار دیا ہے، ہاں ابن حبان نے ثقات تابعین میں ان کا ذکر کیا ہے، فرماتے ہیں: محمد بن مسلمہ سے اسی طرح مروی ہے، فرماتے ہیں: میں اسے وہم گمان کرتا ہوں اور محمد بن مسلمہ کے حوالے سے مرسل حدیث نقل کی ہے، پھر میں نے تاریخ ابن عساکر میں دیکھا ہے کہ انہوں نے ابو ہریرہ رضی اللہ عنہ اور محمد بن مسلمہ سے مرسل حدیث نقل کی ہے۔ پھر ان کے شیوخ میں تابعین کی ایک جماعت کو شمار کیا ہے۔ ان سے روایت کرنے والوں میں اسماعیل بن عیاش، یحییٰ بن حمزہ وغیرہ کا ذکر کیا ہے، اور ان کی وہ حدیث نقل کی ہے جو اذکار میں بطریق ولید بن مسلم مروی ہے، فرماتے ہیں: میں نے اوزاعی کو فرماتے ہوئے سنا کہ مجھ سے ایک ثقہ راوی مطعم بن مقدام نے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی شخص سفر پر جانے کا ارادہ کرتا ہے تو اپنے گھر والوں کے پاس جو چیز سب سے بہتر چھوڑتا ہے وہ دو رکعت نماز ہے جسے وہ ادا کرتا ہے۔“ پھر بطریق ولید اسی طرح منقول ہے، فرماتے ہیں: میں نے اوزاعی کو فرماتے ہوئے سنا: مسلمانوں کو مطعم بن مقدام صنعانی کی مصیبت سے بڑی مصیبت نہیں پہنچی۔ ان کی روایت میں جسے یحییٰ بن حمزہ دمشقی نے ان کے حوالے سے نقل کیا ہے، وہ ولید بن مسلم کے طبقہ سے ہیں، انہوں نے ان سے بحوالہ حسن روایت کیا ہے کہ سیدنا معاویہ رضی اللہ عنہ نے سہل بن حنظلیہ سے پوچھا تو انہوں نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”گھوڑوں کی پیشانی سے خیر بندھی ہوئی ہے“۔ (الحدیث)(2) ابن ابی حاتم کا قول ہے: میں نے اپنے والد سے ان کے بارے میں پوچھا، انہوں نے کہا: یہ میرے نزدیک وہم ہے، اسے ابو اسحاق فزاری نے بحوالہ سہل نقل کیا ہے، ابو حاتم کا قول ہے، مطعم، سیدنا حسن سے روایت کی صلاحیت نہیں رکھتے، حسن بن سہل بن حنظلیہ روایت نہیں کرتے۔","",{"fn":"(1) مصنف ابن ابی شیبہ (۸۱/۲)\n(2) مسلم (۲۲۸۹) ترمذی (۱۶۳۶) نسائی (۳۵۶۴) ابن ماجہ (۲۷۸۶)"}],[8589,"§۸۶۱۵ ۔ مقعد(1)\nاسے مستغفری نے اسماء میں نقل کیا ہے، انہوں نے حدیث نقل کی جسے ابو داؤد نے بطریق یزید بن نمران نقل کیا ہے، فرماتے ہیں: میں نے تبوک میں ایک شخص مقعد کو دیکھا، انہوں نے کہا: میں نبی کریم صلی اللہ علیہ وسلم کے سامنے سے گزرا، میں گدھے پر سوار تھا۔ (الحدیث)(2)\nمیں کہتا ہوں: وہ وہم ہے یہ تو صفت ہے۔ اس کی جگہ مہمات میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۷۹) تجرید (۹۲/۲)\n(2) ابوداؤد (۷۰۵، ۷۰۶) مسند احمد (۶۴/۴) (۳۷۷/۵)"}],[8590,"§۸۶۱۶ ۔ مقنّع\nمقنع میں ان کا ذکر آئے گا۔"],[8591,"§۸۶۱۷ ۔ مقوقس\nیہ لقب ہے، ان کا نام مجریج بن مینا بن قرقب ہے، بعض نے مینا کا ذکر نہیں کیا، جیسا کہ ابو عمر کندی نے امراء مصر میں ان کا یقین کیا ہے۔ فرماتے ہیں: مقوقس بن قرقوب ہیں، مصر میں روم کے بادشاہ کی طرف سے قبط کے امیر تھے۔ ابن مندہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: مقوقس سکندریہ کے حاکم تھے، ان سے عبید اللہ بن عبد اللہ بن عقبہ نے روایت کیا پھر بطریق حسین بن حسن اسواری روایت نقل کی ہے کہ ہم سے مندل بن علی نے بحوالہ عبید اللہ نقل کیا ہے، وہ فرماتے ہیں کہ مجھ سے مقوقس نے نقل کیا ہے، فرماتے ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم کو شیشے کا پیالہ دیا، آپ نے پیا اور اس میں پانی نوش فرماتے تھے۔ فرماتے ہیں: اسے اسماعیل بن عمرو نے بحوالہ مندل ان کی اسناد سے روایت کیا، فرماتے ہیں: بحوالہ ابن عباس رضی اللہ عنہ، فرماتے ہیں: مقوقس نے نبی کریم صلی اللہ علیہ وسلم کو ہدیہ دیا۔ سے ابو نعیم نے اس طرح نقل کیا ہے، ان دنوں سے پہلے ابن قانع نے اسے نقل کیا ہے، لیکن اس سے پہلے صاحب اسکندریہ نہیں لکھا، انہوں نے حسین بن حسن کے طریق سے حدیث نقل کی ہے۔ ابن اثیر(1) نے اس کے ذکر سے انکار کیا ہے، فرماتے ہیں: صحابہ رضی اللہ عنہم میں اس کا شمار نہیں کیونکہ وہ اسلام نہیں لایا، نصرانی رہا۔ اس میں سے خلافت عمر میں مسلمانوں کا مصر فتح کرتا ہے، ان کے ذکر کی کوئی وجہ نہیں، ان دونوں کے ہاں اس طرح کے واقعات ہیں۔ میں کہتا ہوں: اگر ابن مندہ کا یہ قول نہ ہوتا کہ وہ صاحب اسکندریہ ہیں تو احتمال تھا کہ وہ کوئی اور گمان کرتے، جیسا کہ ابن قانع کے طرز سے ظاہر ہوتا ہے، اگر چہ انہوں نے صحابہ رضی اللہ عنہم میں اس کا ذکر کر کے اچھا نہیں کیا۔ مقوقس کا رسول اللہ صلی اللہ علیہ وسلم کو ہدیہ بھیجنا اور آپ صلی اللہ علیہ وسلم کا اس کے ہدیے کو قبول کرنا اہل السیر والفتوح کے ہاں مشہور ہے، ابو قاسم بن عبد الحکم نے فتوح مصر میں فرمایا: ہم سے ہشام بن اسحاق وغیرہ نے بیان کیا، فرماتے ہیں: جب ہجرت کا چھٹا سال ہوا اور آپ صلی اللہ علیہ وسلم حدیبیہ سے واپس آئے تو آپ صلی اللہ علیہ وسلم نے بادشاہوں کی طرف پیغام بھیجا، سیدنا حاطب بن ابی بلتعہ کو مقوقس کے ہاں بھیجا، جب وہ اسکندریہ پہنچے تو دیکھا کہ وہ سمندر کے اوپر بلند عمارت سے جھانک رہا ہے، آپ کشتی پر سوار ہوئے، جب اس کی نشست گاہ کے سامنے پہنچے تو اس خط کے ذریعے اشارہ کیا جو آپ کی انگلیوں کے درمیان تھا۔ مقوقس نے انہیں دیکھا تو انہیں اپنے پاس لانے کا حکم دیا، چنانچہ اس تک پہنچا دیئے گئے، جب اس نے خط پڑھا، کہنے لگا: اگر وہ نبی ہی ہے تو میرے لیے بددعا کیوں نہیں کرتا، تا کہ میرے اوپر کوئی عذاب مسلط ہو، حاطب اس سے کہنے لگے عیسیٰ علیہ السلام نے ان لوگوں کے لیے بددعا نہیں کی جنہوں نے آپ کو اذیت پہنچانے کا ارادہ کیا تھا؟ اس بات کی وجہ سے وہ نرم دل ہو گیا، پھر کہنے لگا: دوبارہ یہ بات کرو تو انہوں نے دوبارہ یہ بات کی، پھر حاطب نے اس سے کہا: تم سے پہلے ایک شخص گزرا، جس کا گمان تھا کہ وہ رب الاعلیٰ ہے تو اللہ تعالیٰ نے اس سے انتقام لیا، لہذا تم اس سے عبرت حاصل کرو، تمہارا ایک مذہب ہے جسے تم ہرگز چھوڑنے والے نہیں، ہاں! اس صورت میں کہ اس سے بہتر کوئی دین ہو اور وہ اسلام ہے، حضرت موسیٰ علیہ السلام کی حضرت عیسیٰ علیہ السلام کے بارے میں ایسی ہی بشارت ہے، جیسے عیسیٰ علیہ السلام کی حضور محمد صلی اللہ علیہ وسلم کے بارے میں ہے۔ ہم تمہیں دین عیسوی سے نہیں روکتے بلکہ اس کا حکم دیتے ہیں، پھر وہ خط پڑھا جس میں لکھا تھا، اللہ کے رسول محمد (صلی اللہ علیہ وسلم) کی جانب سے قبط کے بادشاہ مقوقس کی طرف، جو شخص ہدایت کی پیروی کرے اس پر سلامتی ہو۔ پھر ویسا ہی خط ذکر کیا جیسا ہر قل کی طرف بھیجا گیا تھا، خط پڑھ کر جب وہ فارغ ہوا تو اس خط کو ہاتھی دانت کی بنی ڈبیہ میں رکھ دیا، اور اس پر مہر لگا دی، پھر بطریق ابان بن صالح روایت کی ہے کہ مقوقس نے سیدنا حاطب کی طرف پیغام بھیجا کہ میں تم سے تین باتیں پوچھتا ہوں، سیدنا حاطب فرمانے لگے: تم مجھ سے جو بات بھی پوچھو میں تم سے سچ کہوں گا، وہ کہنے لگا: محمد صلی اللہ علیہ وسلم کس چیز کی طرف بلاتے ہیں، میں نے کہا: ان کی دعوت یہ ہے کہ اللہ کو اکیلا پوجا جائے، نماز پنجگانہ کی رات دن میں ادائیگی کا حکم دیتے ہیں، رمضان کے روزے رکھنے، حج بیت اللہ کرنے، وعدہ پورا کرنے کا حکم دیتے ہیں۔ مردار اور خون کھانے سے منع کرتے ہیں۔ یہاں تک کہ اس نے کہا کہ مجھے ان کا حلیہ بتاؤ، چنانچہ میں نے مختصراً آپ صلی اللہ علیہ وسلم کا حلیہ مبارک بیان کیا، وہ کہنے لگا: کچھ چیزیں تم نے ذکر نہیں کیں، ان میں سے ان کی آنکھوں کی سرخی جو کم ہی ان سے دور ہوتی تھی اور ان کے کندھوں کے درمیان مہر نبوت ہے اور وہ گدھے پر سوار ہوتے ہیں، چادر اوڑھتے ہیں، بدلے میں کھجوریں اور ٹکڑے دیتے ہیں، اس کی پروا نہیں کرتے ان سے چچا ملے یا چچا زاد، کہنے لگا: یہ ان کی علامات ہیں، میرا گمان تھا کہ آپ شام میں ظاہر ہوں گے کیونکہ ان سے پہلے کے انبیاء وہیں مبعوث ہو گزرے ہیں، میں نے دیکھا کہ وہ عرب کی سرزمین میں ظاہر ہوئے ہیں جو بھوک اور جنگوں کی زمین ہے اور قبطی قوم ان کی اتباع میں میری بات نہیں مانتی وہ تمام علاقوں پر غالب آجائیں گے اور ان کے ساتھی ہمارے اس علاقے میں اتریں گے یہاں تک کہ یہاں ہر چیز پر غلبہ پالیں گے، میں ان میں سے کوئی بات بھی قبطیوں سے نہیں کرتا، اور نہ یہ چاہتا ہوں کہ میری اور تمہاری گفتگو کا کسی کو پتہ چلے۔\nابو القاسم کہتے ہیں کہ ہم سے ہشام بن اسحاق وغیرہ نے بیان کیا پھر اس نے عربی لکھنے والا کاتب بلایا اور لکھوایا: محمد بن عبد اللہ من مقوقس سلام، اما بعد! میں نے آپ کا خط پڑھا ہے، پھر اسی طرح کا واقعہ لکھا جیسا سیدنا حاطب کا ہے، اور اس میں یہ اضافہ ہے: میں نے آپ کے قاصد کی عزت کی ہے، اور آپ کی طرف ایک خچر کا ہدیہ بھیجا ہے تا کہ آپ اس پر سوار ہوں اور دو باندیاں جن کی قبط میں بڑی شان و شوکت ہے اور کچھ کپڑے بھیجے ہیں۔ والسلام\nابو القاسم ہی کا قول ہے: ہم سے بھائی بن متوکل نے بحوالہ ابن لہیعہ، بحوالہ یزید بن ابی حبیب روایت کی ہے کہ جب مقوقس کے پاس وہ خط پہنچا تو اس نے اسے اپنے سینے سے لگایا اور کہنے لگا: یہ وہ وقت ہے جب ایک نبی ظاہر ہوگا جس کی صفات ہم اللہ تعالیٰ کی کتاب میں دیکھتے ہیں ہم اس کی نشانیوں میں سے ایک نشانی یہ لکھی ہوئی پاتے ہیں کہ وہ دو بہنوں کو ایک نکاح میں نہیں رکھے گا، اور یہ کہ وہ ہدیہ قبول کرے گا اور زکوۃ اور صدقات قبول نہیں کرے گا، اور اس کے ہمنشین مسکین ہوں گے پھر ایک عق کو بلایا اس کے بعد پورے مصر میں ماریہ اور ان کی بہن سے زیادہ کسی حسین کو نہیں چھوڑا، اور ان دونوں کو رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا دیا اور ایک سرخ خچر اور سرخ گدھا مصر قبطی کے بنے ہوئے کپڑے اور مقام بنھا کا شہر بھیجا، اور آپ کی طرف مال اور صدقہ روانہ کیا، اس نے اپنے قاصد کو کہہ رکھا تھا کہ وہ آپ صلی اللہ علیہ وسلم کی مجلس میں بیٹھنے والوں کو اور آپ صلی اللہ علیہ وسلم کی پشت پر دیکھے کیا اسے کوئی بڑا اتل نظر آتا ہے جس کے اوپر بال ہیں؟ چنانچہ اس نے ایسا ہی کیا، جاتے ہی اس نے دونوں بہنیں اور دونوں سواریاں پیش کیں اس کے بعد شہد اور کپڑے پیش کئے اور ان سب چیزوں کے بارے میں بتا دیا کہ یہ ہدیہ ہیں چنانچہ آپ صلی اللہ علیہ وسلم نے وہ ہدیہ قبول کر لیا اور جب ماریہ اور ان کی بہن کو دیکھا تو دونوں آپ کو بڑی پسند آئیں لیکن دونوں کو ایک ساتھ رکھنا پسند نہ کیا۔ جس کی تفصیل سیدہ ماریہ رضی اللہ عنہا کے حالات میں بیان ہوگی، راوی کا بیان ہے آپ صلی اللہ علیہ وسلم کو وہ خچر اور گدھا تمام سواریوں میں سے پسند تھا، خچر کا نام آپ نے دلدل اور گدھے کا نام یعفور رکھا اور شہد بھی آپ کو پسند آیا، آپ صلی اللہ علیہ وسلم نے مقام بنھا کے شہر کے لیے برکت کی دعا کی، وہی کپڑے آپ صلی اللہ علیہ وسلم کے پاس رہے جن میں سے کسی ایک میں آپ صلی اللہ علیہ وسلم کو کفن دیا گیا، یہاں تک تو ان کی بات ہوئی صحیح یہ ہے کہ صحیح بخاری میں حدیث عائشہ رضی اللہ عنہا میں ہے کہ آپ صلی اللہ علیہ وسلم کو یمنی کپڑے میں کفن دیا گیا۔\nواقدی رحمہ اللہ کا بیان ہے کہ مجھے بحوالہ مغیرہ بن شعبہ یہ حدیث سنائی گئی ہے کہ جب یہ لوگ طائف سے مقوقس کی طرف روانہ ہوئے اس کے پاس پہنچے تو اس نے ان سے کہا کہ تم مجھ تک کیسے پہنچے حالانکہ میرے اور تمہارے درمیان محمد اور اس کے ساتھی حائل ہیں؟ انہوں نے کہا: ہم سمندر کے ذریعے آئے ہیں وہ کہنے لگا: جس بات کی محمد صلی اللہ علیہ وسلم نے دعوت دی ہے تم نے اس کا کہاں تک جواب دیا، انہوں نے کہا: ہم میں سے تو کسی نے اس کی پیروی نہیں کی، اس نے کہا: اس کی قوم نے کیا کہا؟ یہ بولے: چند نو جوانوں نے اس کی پیروی کی ہے، اس کے مخالفین نے کئی مقامات پر اس سے مقابلہ کیا ہے۔ وہ کہنے لگا: کس بات کی دعوت دیتا ہے، انہوں نے کہا: ہم اکیلے اللہ کی عبادت کریں اور جن کی ہمارے آباء و اجداد عبادت کرتے تھے انہیں چھوڑ دیں، نماز اور زکوۃ کی دعوت دیتا ہے، رشتہ داری کو جوڑنے، وعدہ پورا کرنے کا حکم دیتا ہے، زنا، سود اور شراب کو حرام بتاتا ہے، مقوقس کہنے لگا: یہ تو سارے لوگوں کی طرف بھیجا ہوا رسول ہے۔ اگر قبطیوں اور رومیوں کو ان تک پہنچ ہو جائے تو سب اس کی اتباع کر لیں، جس کا انہیں عیسیٰ علیہ السلام نے حکم دیا ہے، اور یہ صفات جو تم نے اس کی بیان کی ہیں، انہی صفات کے ساتھ پہلے انبیاء علیہم السلام مبعوث ہوئے، اس کا اچھا انجام ہوگا اور کوئی بھی اس سے نہیں جھگڑے گا اس کا دین جہاں تک اونٹ اور گھوڑے پہنچ سکتے ہیں غالب ہوگا، وہ کہنے لگے: اگر سارے لوگ بھی مسلمان ہو گئے تو ہم مسلمان نہیں ہوں گے۔ مقوقس نے اپنا سر جھٹکا اور کہنے لگا: ”تم لوگ کھیل کود میں پڑے ہو پھر ان سے اس طرح کی باتیں پوچھیں جیسا کہ ہر قل کے واقعہ میں ہے، اس کے آخر میں ہے: میثرب کے یہودیوں نے کیا کیا؟ ہم نے کہا: اس کی مخالفت کی ہے، جس کی وجہ سے ان سے جنگ ہوئی وہ کہنے لگا: یہ حاسد قوم ہے۔ ان لوگوں کو جتنا ان کے بارے میں پتہ ہے ہم اتنا نہیں جانتے پھر مغیرہ نیا شوشہ کا وہ واقعہ ذکر کیا جس میں انہوں نے اپنے ساتھیوں سے جو سلوک کیا اور ان کا اسلام لانا مذکور ہے، لمبا واقعہ ہے۔ ابن عبد الحکم نے فتوح مصر میں عبد اللہ بن ابی جعفر وغیرہ سے، سیدنا عمرو بن العاص رضی اللہ عنہ کے قبط کے قلعے کا محاصرہ کرنے کے بارے میں روایت کی ہے کہ جب مقوقس کو اپنی اور اپنے متبعین کی جان کا خدشہ ہوا تو سیدنا عمرو بن عاص کو صلح کی اپیل کی پھر ایک لمبا واقعہ ذکر کیا۔ خالد بن مرشد کے طریق سے تابعین کی ایک جماعت سے مروی ہے کہ مقوقس اور قبط کے کچھ خاص لوگوں نے جزیرہ رُخ نماز پڑھی اور الا عیرج کو قلعے کا نائب مقرر کیا، پھر مقوقس سے ذکر کیا جاتا ہے کہ وہ مسلمانوں کے ساتھ صلح پر برقرار رہا جب روم سے عہد شکنی ہوئی، اس طرح کے کئی واقعات ہیں جس سے پتہ چلتا ہے کہ وہ مرتے دم تک نصرانیت پر ڈٹا رہا، اس بارے میں اس کا واقعہ ہر قل سے ملتا جلتا ہے۔ جیسا کہ ان شاء اللہ تعالیٰ اس کے حالات میں بیان ہوگا۔","",{"fn":"(1) اسد الغابہ (۱۸۷/۴)"}],[8592,"§۸۶۱۸ ۔ مقوقس\nمعجم ابن قانع میں ان کا ذکر ہے، شاید یہ ایک ہی ہیں، ذہبی رحمہ اللہ کا یہ قول تجرید میں ہے، انہیں وہم ہوا ہے۔ اگر وہ اس حدیث کی مراجعت کر لیتے جو ابن مندہ اور ابو نعیم نے ذکر کی ہے تو یہ بات ثابت ہو جاتی کہ وہ ایک ہی شخصیت ہیں، تمام راویوں نے ان کے طریق سے ایک سند سے حدیث نقل کی ہے۔"],[8593,"§۸۶۱۹ ۔ مکلبہ بن ملکان خوارزمی(1)\nجھوٹا شخص ہے یا اس کا وجود نہیں۔ اسے یہ گمان ہے کہ اسے شرف صحابیت حاصل ہے، خطیب، ابو اسحاق مستملی، مستغفری نے بطریق مظفر بن عاصم بن ابوائز مجلی اس کی حدیث نقل کی ہے، اس کی کنیت ابو قاسم تھی، وہ سامر سے خوارزم کی طرف ۳۱۱ھ میں آیا، کذاب راویوں میں سے ایک ہے۔ اس نے بیان کیا کہ وہ آپ صلی اللہ علیہ وسلم کے ساتھ چو میں غزوات اور آپ صلی اللہ علیہ وسلم کے بھیجے گئے سرایا میں شریک رہا۔ مستملی نے بحوالہ حارث بن احمد بن حارث بلخی اس کا قصہ ذکر کیا ہے کہ انہوں نے مظفر سے بغداد میں فرماتے ہوئے سنا کہ میں نے مکلبہ سے خراسان میں کہتے ہوئے سنا۔ مستملی کی روایت میں ہے خوارزم کا گورنر اس وقت فرجسید تھا، انہوں اسی طرح روایت کیا، ابن اثیر(2) کا قول ہے: اس کو چھوڑ دینا درست ہے۔ ذہبی(3) رحمہ اللہ نے اس کے نقل کرنے کے بعد فرمایا: یہ کذاب ہے۔ ابن جوزی(4) رحمہ اللہ نے مظفر کے سوانح میں فرمایا: اس کا گمان ہے کہ وہ بعض صحابہ سے ملا، اس نے جھوٹ کہا۔\nمیں کہتا ہوں: مظفر کی بحوالہ مکلبہ روایت ہے، جو ابن فلان کے سوانح میں مہمات میں آئے گی ان شاء اللہ تعالیٰ۔","",{"fn":"(1) اسد الغابہ (۵۰۸۳) تجرید (۹۳/۲)\n(2) جامع المسانید والسنن (۵۲/۱۲) اسد الغابہ (۱۸۸/۴)\n(3) اسد الغابہ (۱۸۹/۴)\n(4) اسد الغابہ (۵۰۸۷)"}],[8594,"§۸۶۲۰ ۔ مکین جہنی(1)\nاسے ابو بکر بن ابی علی زکوانی نے بطریق عبد الرزاق، بحوالہ رافع بن مکین(2)، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”نیکی عمر میں اضافہ کرتی ہے، اسے ابو موسیٰ نے نقل کیا ہے، فرماتے ہیں: اسے عبد الرزاق نے ان اسناد کے ساتھ بنو رافع کے کسی شخص سے، انہوں نے اپنے والد سے نقل کیا ہے، حدیث رافع سے مروی ہے، یہی صحیح ہے۔\nمیں کہتا ہوں: اسی طرح مصنف عبد الرزاق میں سے، اسی طرح اسے ابن شاہین نے بحوالہ عبد الرزاق نقل کیا ہے۔","",{"fn":"(1) مصنف عبد الرزاق (۱۳۲، ۱۳۱/۱۱)\n(2) جامع المسانید (۱۲/۵۶)، اسد الغابہ (۱۸۹/۴)"}],[8595,"§۸۶۲۱ ۔ ملحان قیسی(1)\nاسے ابو عمر نے ذکر کیا ہے، فرماتے ہیں: وہ عبد الملک کے والد ہیں، بعض کا قول ہے: قتادہ بن ملحان قیسی کے والد ہیں، ان کے بارے میں اختلاف ہے، ایام بیض کے روزوں کے بارے میں ان کی حدیث ہے، ان کی حدیث شعبہ کے ہاں بحوالہ انس بن سیرین ہے، اس میں شعبہ سے اوپر اور انس بن سیرین کے اوپر کے راویوں میں اختلاف ہے، ابو ولید نے بحوالہ شعبہ، انہوں نے انس بن سیرین سے، انہوں نے عبد الملک بن ملحان سے، انہوں نے اپنے والد سے نقل کیا ہے، یزید بن ھارون کا قول ہے: بحوالہ شعبہ، انہوں نے انس بن سیرین سے، انہوں نے عبد الملک بن منھال سے، انہوں نے اپنے والد سے نقل کیا ہے۔ یحییٰ بن معین کا قول ہے: یہ خطا ہے، صحیح ابن ملحان ہے جیسا کہ طیالسی وغیرہ کا قول ہے۔ اس حدیث(2) کو حمام نے بحوالہ انس بن سیرین نقل کیا ہے، فرماتے ہیں: مجھ سے عبد الملک بن قتادہ بن ملحان قیسی نے بحوالہ اپنے والد نقل کیا ہے، ابو عمر کا قول ہے: یہ خطا ہے، صحیح وہی ہے جو شعبہ نے کہا، حمام ایسے راوی نہیں جنہیں شعبہ کے مقابل لایا جا سکے۔۔۔۔\nان کے علاوہ دوسرے ائمہ نے جو اطلاق کیا ہے کہ حمام کی روایت صحیح ہے اور یہ کہ ملحان نام، منھال سے زیادہ صحیح ہے اور یہ کہ نسب میں قتادہ کا اضافہ ضروری ہے، حمام کی بحوالہ ابو داؤد، نسائی اور ابن ماجہ روایت ہے جو شعبہ سے مروی ہے۔ اسے نسائی نے بطریق خالد بن حارث بحوالہ شعبہ، انہوں نے انس بن سیرین سے، انہوں نے عبد الملک نامی ایک شخص سے، انہوں نے اپنے والد سے نقل کیا ہے، اور ان کا نام نہیں لیا۔ اسی طرح اسے بروایت عبد اللہ بن مبارک، انہوں نے شعبہ سے روایت کیا ہے، فرماتے ہیں: بحوالہ انس، انہوں نے عبد الملک بن منھال سے، انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: قتادہ کی کنیت ابو منھال ہے۔ شعبہ کی روایت حمام کی روایت کے ساتھ ایک ہو گئی ہے، ہشام دستوائی نے تمام سے موافقت کی ہے، اسے روح بن عبادہ نے بحوالہ ھشام اور حمام دونوں سے روایت کیا ہے، بحوالہ انس، انہوں نے عبد الملک بن قتادہ سے، انہوں نے اپنے والد سے نقل کیا ہے، اسے حارث بن ابو اسامہ سے ان کے حوالے سے نقل کیا ہے، اس سے ظاہر ہوا کہ حمام کی روایت صحیح ہے اور یہ کہ حدیث کے روایت کرنے والے صحابی قتادہ بن ملحان ہیں، منھال نہیں اور یہ کہ عبد الملک کے والد قتادہ ہیں، اور جس نے یہ کہا: ابن منھال یا ابن ملحان، انہوں نے ان کے دادا کی طرف ان کی نسبت کی ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۸۹)، استیعاب (۲۶۰۰)، تجرید (۹۳/۲)\n(2) ابوداؤد (۲۴۴۹)، نسائی (۲۴۲۹)، (۲۴۳۰)، ابن ماجہ (۱۷۰۷)، مسند احمد (۲۷/۵)"}],[8596,"§۸۶۲۲ ۔ ملفع بن حُصین تمیمی سعدی(1)\nان کی ایک حدیث ہے، اس کی اسناد تو قوی نہیں، یہ ابو عمر(2) کا قول ہے۔ میں کہتا ہوں: اس میں لفظی غلطی ہے، وہ منقع ہیں، اپنے مقام پر ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۹۰)، استیعاب (۲۶۰۱)، تجرید (۹۳/۲)\n(2) طبرانی (۷۱۲/۲۰)، الآحاد والمثانی (۱۰۵/۵)، (۱۰۶/۵)، مجمع الزوائد (۱۴۱/۱)"}],[8597,"§۸۶۲۳ ۔ ملقام بن تلب\nابن قانع نے ان کا ذکر کیا ہے اور بطریق غالب بن جبیرہ ان کی حدیث ذکر کی ہے کہ مجھ سے ام عبد اللہ بنت ملقام نے بحوالہ اپنے والد نقل کیا ہے، فرماتے ہیں: قحط آیا، میرے پاس اناج تھا، نبی کریم صلی اللہ علیہ وسلم نے مجھ سے بطور قرض لے لیا۔ میں کہتا ہوں: سند سے صحابی ساقط ہیں، وہ ملقام کے والد ہیں، اسی طرح طبرانی نے اسے اس طریق سے نقل کیا(1) ہے، فرماتے ہیں: بحوالہ ان کے والد، انہوں نے اپنے والد سے نقل کیا ہے، بخاری(2) رحمہ اللہ نے تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تاریخ الکبیر (۵۳/۸)، طبقات الکبریٰ (۶۳/۷)\n(2) تاریخ الکبیر (۷۲/۴)"}],[8598,"§۸۶۲۴ ۔ مُلکیہ\nمیرے بعض شیوخ نے ذکر کیا ہے کہ یہ اس شخص کا نام ہے جس نے سیدنا معاذ رضی اللہ عنہ کے پیچھے نماز پڑھی تھی، کہا جاتا ہے کہ جب سیدنا معاذ رضی اللہ عنہ کی نماز طویل ہو گئی تو واپس آگئے، کسی نے یہ بات مستند ذکر نہیں کی۔"],[8599,"§۸۶۲۵ ۔ مُلیل(1)\nاس کے آخر میں لام تصغیر ہے، ابن عبد الکریم بن خالد بن عجلان انصاری، ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، انہیں وہم ہوا ہے، ابن مندہ نے ان کا ذکر کیا ہے، فرماتے ہیں ملیل بن وبرہ بن عبد الکریم قسم اول میں صحیح گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۹۱)"}],[8600,"§۸۶۲۶ ۔ مُنبہ(1)\nانہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس شخص کے بارے میں حدیث نقل کی ہے جس نے عمرے کا احرام باندھا ہو اس پر جنبہ ہو اور وہ خوشبو لگائے ہوئے ہو، کہ اسی طرح ابن عبد البر(2) نے نقل کیا ہے اور ابن فتحون نے ان کا تعاقب کیا ہے، فرماتے ہیں: یہ وہم ظاہر ہے۔ صحیحین میں حدیث یعلی بن امیہ سے مروی ہے، وہ ابن منبہ ہیں، یہ ان کی والدہ یا دادی ہیں، امیہ ان کے والد ہیں، ابو عمر نے یعلی کے سوانح میں صحیح ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۹۵)، تجرید (۹۴/۲)\n(2) زعفران لگانا"}],[8601,"§۸۶۲۷ ۔ منتذر(1)\nمنکدر کے وزن پر ہے، جعفر مستغفری نے بحوالہ یحییٰ بن یونس شیرازی ان کا ذکر کیا ہے، ابو موسیٰ نے ابن مندہ پر اپنے استدراک میں ان کا ذکر کیا ہے، ابن مندہ نے تغیر کے ضعیف میں ان کا ذکر کیا ہے، یہی معروف ہے۔ منذر کا قول ہے: بعض نے کہا: منذر، پھر ان کی حدیث نقل کی، اپنی جگہ پر ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۹۸)"}],[8602,"§۸۶۲۸ ۔ منذر بن ابی راشد\nابن فتحون نے ذیل میں ان کا ذکر کیا ہے اور طبرانی کی طرف اس کی نسبت کی ہے بطریق صالح بن کیسان، بحوالہ زبیر بن منذر بن ابی راشد نے اپنے والد کے حوالے سے حدیث نقل کی ہے کہ نبی کریم صلی اللہ علیہ وسلم مدینہ کے بازار سے گزرے اور فرمایا: ”یہ تمہارا بازار ہے، اس میں کمی نہ کرو، اور نہ اس کے لیے اجرت لو۔“\nمیں کہتا ہوں: ان کے قول ابن ابی راشد میں تہہ تیلی ہے، وہ ابن ابی اسید ہے۔ بخاری نے زبیر بن منذر بن ابی اسید ذکر کیا ہے، منذر بن ابی اسید کا ذکر قسم ثانی میں گزر چکا ہے، یہ ان لوگوں میں سے ہیں جنہیں دیدار حاصل ہے، نبی کریم صلی اللہ علیہ وسلم سے ان کی روایت مرسل کے حکم میں ہے۔"],[8603,"§۸۶۲۹ ۔ منذر بن عباد(1)\nبن قول، ابن عبد البر نے ان کا ذکر کیا ہے، منذر بن عبد اللہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۰۹۹)، استیعاب (۲۵۱۸)"}],[8604,"§۸۶۳۰ ۔ منذر بن عرفجہ(1)\nبن کعب بن خطاب بن کعب بن جارثہ بن غنم بن سلم بن مالک بن اوس انصاری اودی، بدر میں شریک تھے، اسی طرح ابو عمر نے منذر بن قدامہ انصاری کے سوانح کے بعد نقل کیا ہے، جو غنم بن بن مالک بن اوس سے ہیں، موسیٰ بن عقبہ وغیرہ نے بدری صحابہ میں ان کا ذکر کیا ہے۔ انہوں نے ان سے صرف نظر کیا ہے حالانکہ یہ ایک ہی شخص ہے۔ وہ منذر بن قدامہ بن عرفجہ ہیں، بعض شخوں میں منذر اور عرفجہ کے درمیان قدامہ رہ گئے ہیں یوں انہیں دو مرا شخص سمجھ لیا۔","",{"fn":"(1) اسد الغابہ (۵۱۱۳)، استیعاب (۲۵۲۱)"}],[8605,"§۸۶۳۱ ۔ منفعہ(1)\nایک شخص ہیں، جن کا صحابہ میں ذکر ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ان کے بیٹے کلیب بن منفعہ نے روایت کی، ابو عمر(2) نے ان کا اسی طرح ذکر کیا ہے۔ وہ روایت جسے ابن قانع نے بطریق ضمضم بن عمرو غنی نے بحوالہ کلیب بن منفعہ نقل کی کی ہے۔ میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم میں کس سے حسن سلوک کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: اپنی والدہ اور اپنے والد سے”۔۔۔۔ الحدیث(3) اسے بغوی نے بطریق حارث بن مرہ، بحوالہ کلیب بن منفعہ نقل کیا ہے، فرماتے ہیں: میرے دادا نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور فرمایا: میں کس سے حسن سلوک کروں؟۔۔۔۔ الحدیث\nاسے ابو داؤد نے نقل کیا ہے، فرماتے ہیں: بحوالہ کلیب بن منفعہ، انہوں نے اپنے دادا سے نقل کیا ہے، اور ان کا نام نہیں لیا، ابن مندہ نے ان کا نام لیا ہے۔ کلیب حرف کاف میں گزر چکے ہیں، میں نے اس حدیث کے کسی طریق میں منفعہ کی روایت نہیں دیکھی۔","",{"fn":"(1) اسد الغابہ (۵۱۲۶)، استیعاب (۲۶۰۷)، تجرید (۲۹۷/۲)\n(2) استیعاب (۴۷/۴)\n(3) ابوداؤد (۵۱۳۶)، ترمذی (۱۸۹۷)، مسند احمد (۵/۳)، (۵/۵) مستدرک حاکم (۶۲/۴)، (۱۵/۴)"}],[8606,"§۸۶۳۲ ۔ مہاجر بن مسعود(1)\nصحاب میں ان کا ذکر ہے۔ یہ وہم ہے، ابن ابی خیثمہ نے بطریق داؤد بن ابی ہند، بحوالہ شعیب نقل کیا ہے، فرماتے ہیں: مہاجر بن مسعود حمص میں تھے، سیدنا عمر رضی اللہ عنہ نے انہیں کوفہ کی طرف لوٹا دیا۔ میں کہتا ہوں: وہ گمان جس سے مہاجر کے صحابی ہونے کا گمان ثابت ہوتا ہے یہ ہے کہ روایت ہم کے زیر کے ساتھ ہے، اور وہ صحابی کا نام ہے، جبکہ ایسا نہیں، شعبی رضی اللہ عنہ نے بیان کیا ہے کہ سیدنا عبد اللہ بن مسعود فتوحات کے زمانہ میں شام کی سرزمین کی طرف ہجرت کر گئے اور حمص فروکش ہوئے، پھر سیدنا عمر رضی اللہ عنہ نے انہیں کوفہ کی طرف لوٹا دیا، ھاجر جس ہے اور حمیم کے زیر کے ساتھ ہے۔ ابن مسعود، عبد اللہ ہیں جو ان کی ہجرت کے بارے میں بتایا گیا ہے۔ وہاں سے ابن ابی خیثمہ نے اس حدیث کو سیدنا عبد اللہ بن مسعود کے سوانح میں نقل کیا ہے۔","",{"fn":"(1) سنن الکبریٰ (۱۷۹/۴)، معجم الکبیر (۱۹/۱۹)، (۱۹/۱۹)، جامع المسانید والسنن (۱۲/۱۲)، اسد الغابہ (۱۹۹/۴)"}],[8607,"§۸۶۳۳ ۔ مہاجر کلاعی(1)\nنبی کریم صلی اللہ علیہ وسلم سے ان کی حدیث مرسل ہے، وہ تابعی ہیں، اسی طرح ذہبی رحمہ اللہ نے تجرید میں اپنے استدراک میں ان کا ذکر کیا ہے، اور اس روایت کی طرف اشارہ کیا جسے ابن قانع(2) نے بطریق عاصم بن محاجر کلاعی، بحوالہ اپنے والد سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اچھی تحریر حق کی زیادہ واضح کرتی ہے۔“۔ ابن قانع کا قول ہے: مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہو۔","",{"fn":"(1) کنز العمال (۲۹۳۹)، (۲۹۳۹)\n(2) اسد الغابہ (۵۱۲۴)، تجرید (۹۸/۲)"}],[8608,"§۸۶۳۴ ۔ مہدی جزری(1)\nمعروف تابعی ہیں، انہوں نے مرسل حدیث نقل کی ہے، علی بن سعید عسکری نے صحابہ میں ان کا ذکر کیا ہے۔ ابو موسیٰ نے ذیل میں اپنے طریق سے ان کا ذکر کیا ہے اور بطریق ولید بن فضل، بحوالہ محمدی جزری حدیث نقل کی ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تین آدمیوں کو بد اخلاقی میں معذور قرار دیا جائے گا، بیمار، مسافر اور روزہ دار۔“۔","",{"fn":"(1) اسد الغابہ (۲۰۲/۴)"}],[8609,"§۸۶۳۵ ۔ مہران(1)\nتابعی ہیں، انہوں نے مرسل حدیث نقل کی ہے، جعفر مستغفری نے صحابہ میں ان کا ذکر کیا ہے، ابو موسیٰ نے ان کی پیروی کی ہے، اور اپنے طریق سے پھر عبد الصمد بن فضل کی روایت سے بحوالہ ابن جریج نقل کیا ہے کہ مجھے محمد بن مہران نے بتایا کہ انہوں نے اپنے والد کو فرماتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر فرمایا: ”اے تاجرو! میں تمہارے کندھوں کے درمیان یہ حکم پھینک رہا ہوں کہ قافلوں کو پہلے سے جا کر نہ لو اور نہ کوئی شہری دیہاتی سے کوئی چیز خریدے۔“(2) محمد بن مہران کا ابن حبان نے ثقات کے طبقہ ثالثہ میں ذکر کیا ہے، فرماتے ہیں: شیخ ہیں جو مرسل احادیث روایت کرتے ہیں، ان سے ابن جریج نے روایت کی۔","",{"fn":"(1) تجرید (۹۸/۲)\n(2) بخاری (۲۱۵۰)، مسلم (۲۷۹۴)، ابوداؤد (۳۴۴۲)"}],[8610,"§۸۶۳۶ ۔ مہلب بن ابی صفرہ ازدی(1)\nان کی کنیت ابو سعید ہے، حرف ظاء میں ان کے والد کے سوانح میں ان کا ذکر گزر چکا ہے، وہاں ان کا نسب بیان کیا، اسی طرح حرف حاء میں حذیفہ بن یمان ازدی کے سوانح میں ذکر کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کے زمانہ کے فتح کے سال پیدا ہوئے۔ حاکم نے تاریخ نیشاپور میں ان صحابہ کے باب میں ان کا ذکر کیا ہے، جو وہاں آئے، ابو صفرہ کے سوانح میں مہلب کی روایت آئے گی، فرماتے ہیں: میں نے اپنے والد کو فرماتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((أَطْوَلُکُنَّ طَاقًا أَعْظَمُکُنَّ أَجْرًا۔۔۔۔)) (الحدیث)(2) محمد بن قدامہ جوہری نے کتاب الاخوان میں فرمایا: مہلب فتح کے سال پیدا ہوئے۔ حاکم کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے زمانہ میں پیدا ہوئے، ان کے والد ابو بکر رضی اللہ عنہ کے پاس وفد میں آئے، ان کے ساتھ ان کے دس بیٹے تھے، مہلب ان میں سب سے چھوٹے تھے۔ سیدنا عمر رضی اللہ عنہ نے انہیں دیکھا تو ابو صفرہ سے فرمایا: یہ ان کا سردار ہے، اور مہلب کی طرف اشارہ کیا، پھر اس کا ذکر کیا۔ حاکم رحمہ اللہ کا ان کی ولادت کے بارے میں قول اس روایت کے معارض ہے جو حذیفہ بن یمان ازدی کے سوانح میں گزر چکا ہے کہ ابو صفرہ سیدنا ابو بکر رضی اللہ عنہ کی خلافت میں تابالغ لڑکے تھے، اس سے چار سال پہلے ان کی اولاد کیسے ہو سکتی ہے، حاکم نے اس بارے میں ان کی موافقت کی ہے، جنہوں نے ان کی تاریخ وفات ۸۳ بتائی ہے وہ ۷۶ برس کے تھے۔ ابن سعد(3) نے ذکر کیا ہے کہ ابو صفرہ ان لوگوں میں سے تھے جو مرتد ہو گئے تھے، پھر مسلمان ہو گئے، اور سیدنا عمر رضی اللہ عنہ کے پاس آئے، انہیں اہل بصرہ کے تابعین کے طبقہ اولیٰ میں شمار کیا گیا ہے، عسکری رحمہ اللہ کا قول ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل احادیث نقل کیں وہ اور ان کے والد سیدنا عمر رضی اللہ عنہ کے زمانہ میں مدینہ میں آئے۔ میں کہتا ہوں: پہلے اثر کو عبد الرزاق نے اپنے مصنف میں نقل کیا ہے۔ فرماتے ہیں: ابو صفرہ سیدنا عمر رضی اللہ عنہ کے پاس اپنے دس بیٹوں کے ساتھ آئے، ان میں سب سے چھوٹے مہلب تھے، سیدنا عمر رضی اللہ عنہ نے ان سے فرمایا: یہ تمہاری اولاد کا سردار ہے۔ اصحاب سنن نے مہلب کی روایت سے نبی کریم صلی اللہ علیہ وسلم سے نئے والے کی شخص سے روایت کیا ہے، فرماتے ہیں: وہ جب تم شب خون مارو تو تمہارا شعار یہ ہونا چاہیے حم طہ لا ینصرون، ان کی سنن میں اس کے علاوہ روایت نہیں ہے۔ اسے احمد نے اپنی روایت سے بحوالہ سمرہ بن جندب حدیث نقل کی ہے۔ وہ اسی طرح ابن عمر، ابن عمرو، ابن عمر و امام سے روایت کرتے ہیں، ان سے مالک ابن حرب، ابو اسحاق سبیعی، عمر بن سیف نے روایت کی، ابن تجیب کا قول ہے: لوگوں میں سب سے بہادر تھے۔ جب اہل بصرہ کو جلا وطن کیا گیا تو انہوں نے ان کو خوارج سے بچایا، ان پر صرف جھوٹ کا عیب لگا۔ میں کہتا ہوں: مرد نے ذکر کیا ہے کہ ایسا ہوا ہے جنگوں میں کرتے تھے، ابو عمر کا قول ہے: وہ ثقہ ہیں، جس نے ان پر جھوٹ کی تہمت لگائی ہے، اس کی کوئی وجہ نہیں، کیونکہ انہیں جنگوں میں اس کی ضرورت پڑتی تھی، تاکہ خوارج کو دھوکا ہو۔ انہوں نے نئے کی وجہ سے انہیں چھوٹا کہا ہے۔ ابن عبد البر کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل احادیث روایت کی ہیں، محمد بن قدامہ نے اخبار الخوارج میں بحوالہ مہلب نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب تمہارے اور قبلہ رخ جانب کے درمیان کجاوے کی لکڑی کے پچھلے حصے کے برابر کوئی سترہ ہو تو (اے گزرنے والے) نماز نہیں ٹوٹے گی۔“\nابو اسحاق سبیعی کا قول ہے: میں نے مہلب سے بہتر کوئی امیر نہیں دیکھا محمد بن قدامہ نے کتاب اخبار الخوارج میں کہا ہے: کوفیوں نے بحوالہ ابو اسحاق، انہوں نے اپنے اصحاب سے روایت کیا ہے: مہلب نے اپنی رائے سے کبھی امیر نہیں بنایا بلکہ لوگوں کی ضرورت کی وجہ سے بنایا، ابو اسحاق کا قول ہے: وہ حج کہتے ہیں، یہ پہلے ہیں جنہیں سیدنا علی بن ابو طالب نے جھنڈا دیا جب جمل کے دن ازد کو شکست ہوئی، مہلب ازارقہ کے خوارج سے لڑائی کے اس وقت امیر بنائے گئے جب انہوں نے لشکروں کو شکست دے کر شہروں پر غلبہ حاصل کر لیا، انہوں نے ان کے لئے یہ شرط رکھی کہ جس شہر سے وہ خوارج کو نکالیں گے تو انہیں اس سال خراج پر تصرف حاصل ہو گا، انہوں نے ان سے کئی سال لڑائی کی، یہاں تک کہ اللہ تعالیٰ نے ان کے ہاتھ پر نو سال بعد ان کی جمعیت کو توڑنے کی آسانی پیدا کی۔ وہ زندہ رہے یہاں تک کہ ۸۲ھ میں وفات پائی، بعض کا قول ہے: ۸۳ھ میں فوت ہوئے، وہ ۷۶ سال کے تھے۔\nمیں کہتا ہوں: یہ مہلب بن ابو صفرہ ہیں، وہ مرسل روایت کرتے ہیں، جیسا کہ میں نے ان سے پہلے والے سوانح میں بیان کر دیا ہے۔","",{"fn":"(1) مجمع الزوائد (۶۴۳۱)\n(2) الطبقات الکبریٰ (۲۴۷/۷)\n(3) کنز العمال (۱۹۲۸)، (۱۹۲۹)، تاریخ دمشق (۴۸/۸)، مصنف عبد الرزاق (۲۲۷/۲)"}],[8611,"§۸۶۳۷ ۔ مہلب بے نسبت\nبے نسبت۔ ابن شاہین نے ان کا ذکر کیا ہے اور بطریق مُسدد نے نقل کیا ہے کہ ہم سے محمد بن عیینہ نے بحوالہ ذکوان جو ہمارے مولیٰ ہیں نقل کیا، فرماتے ہیں: مہلب کا شعار حم طہ لا ینصرون تھا، مہلب کا قول ہے: یہ رسول اللہ صلی اللہ علیہ وسلم کا شعار تھا۔"],[8612,"§۸۶۳۸ ۔ موسی بن شیبہ\nعسکری نے صحابہ میں ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل روایت کی، اسی طرح ابو حاتم نے ان کی روایت کو مرسل کہا ہے۔"],[8613,"§۸۶۳۹ ۔ موسی انصاری\nیہ بہت جھوٹا شخص ہے، یا بعض کذاب نے اسے گھڑ لیا ہے، ابو الفرج بن جوزی نے موضوعات میں حزر ابو جاہل کا ذکر کرنے کے بعد بطریق محمد بن ادھم قرشی، بحوالہ ابراہیم بن موسیٰ انصاری، انہوں نے اپنے والد سے نقل کیا ہے... پھر طویل حدیث نقل کی یہ حدیث موضوع ہے، اس کی اسناد منقطع ہے، صحابہ میں ایسا کوئی شخص نہیں جس کا نام موسیٰ ہو، اس کے اکثر رجال مجہول ہیں۔"],[8614,"§۸۶۴۰ ۔ مُویک\nابو حبیب سلامانی، ابن شاہین نے ان کا عنوان قائم کیا ہے، اور حرف میم میں ان کا ذکر کیا ہے، اس میں لفظی غلطی ہے۔ اس کے شروع میں فاء ہے، جس میں کوئی اختلاف نہیں، اختلاف واؤ کے بارے میں ہے، اسے ابنوی نے بطریق عثمان بن ابی شیبہ اپنی سند سے نقل کیا ہے، اسے ابنوی وغیرہ نے حرف فاء میں اس سند سے نقل کیا ہے جسے ابن شاہین نے بیان کیا ہے۔ فدیک نامی لوگوں میں ان کا نام گزر چکا ہے۔"],[8615,"§۸۶۴۱ ۔ مینا بن ابی مینا جرار(1)\nسیدنا عبد الرحمن بن عوف کے مولیٰ ہیں، انہوں نے اپنے مولیٰ، سیدنا عثمان، سیدنا علی، ابن مسعود، ابن ہریرہ، سیدہ عائشہ رضی اللہ عنہم سے روایت کی، ان سے حمام نے روایت کی جو عبد الرزاق کے والد ہیں۔ ابو حاتم رازی کا قول ہے: منکر الحدیث ہے، اس نے صحابہ کے بارے میں منکر احادیث روایت کیں، اس کی روایت کردہ حدیث کی پرواہ نہیں کی جائے گی وہ جھوٹا شخص تھا۔ عباس دوری نے بحوالہ ابن معین فرمایا: ثقہ نہیں، اسی طرح نسائی کا قول ہے، جوزجانی نے کہا: ائمہ حدیث نے ان کے برے عقیدے کی وجہ سے ان کی حدیث کا انکار کیا ہے۔ یعقوب بن سفیان کا قول ہے: نہ ثقہ ہیں اور نہ مامون، ابو زرعہ کا قول ہے: قوی نہیں، ترمذی اور عقیلی کا قول ہے: منکر احادیث روایت کیں، عقیلی نے یہ اضافہ کیا ہے، ان کی حدیث کی متابعت نہیں کی جائے گی، ابن عدی کا قول ہے: ان کی حدیث سے ظاہر ہوتا ہے کہ وہ شیعیت میں غالی تھے، حاکم رحمہ اللہ نے عجیب کام کیا ہے، انہوں نے مناقب فاطمہ میں بطریق عبد الرزاق نقل کیا ہے کہ مجھ سے میرے والد نے بحوالہ اپنے والد، انہوں نے مینا بن ابی مینا مولیٰ عبد الرحمن بن عوف سے نقل کیا ہے، انہوں نے کہا: مجھ سے احادیث لے لو، اس سے پہلے کہ احادیث باطل روایات سے مل جائیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: ”میں درخت ہوں، فاطمہ اس کی شاخ ہے اور علی اس کا رس ہے۔۔۔۔“ الحدیث(2)، حاکم کا قول ہے: اسحاق، ان کے والد اور ان کے دادا ثقہ ہیں، مینا نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا اور آپ سے سنا، یہ متن شاذ ہے۔\nمیں کہتا ہوں: اس میں کئی اعتراضات ہیں۔\n(۱) ان کا یہ قول کہ حدیث ابی، عن ابی اس میں ایک راوی کا اضافہ ہے، یہ روایت تو عبد الرزاق اپنے والد سے بحوالہ مینا نقل کرتے ہیں، عبد الرزاق کے والد اور مینا کے درمیان کوئی واسطہ نہیں۔\n(۲) عبد الرزاق کے دادا ان لوگوں میں سے ہیں جن کے بارے میں معلومات نہیں، نہ ان کا تذکرہ ملتا ہے، نہ روایت۔\n(۳) ان کا یہ کہنا کہ ”مینا نے دور نبوی پایا ہے اور نبی کریم صلی اللہ علیہ وسلم سے سامع کیا ہے“ قابل تردید ہے۔ اس لئے کہ مینا خود اپنے بارے میں بتاتے ہیں کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد پیدا ہوئے، ان کا بیان ہے کہ وہ اس وقت بالغ تھے جب سیدنا عثمان رضی اللہ عنہ کی بیعت لی گئی، یہ ۲۳ھ کے آخر کا دور ہے، اس لحاظ سے مینا کی ولادت زمانہ نبوی کے آخر میں ہوئی۔\n(۴) مینا، یہ حدیث اپنے مولیٰ سیدنا عبد الرحمن بن عوف سے روایت کرتے ہیں جیسا کہ ابن عدی نے الکامل میں بروایت حسن بن علی بن عیسیٰ بن ابی عبد الغنی، عن عبد الرزاق درج کی ہے۔ تو یہ حدیث عبد الرحمن کی ہوئی نہ کہ مینا کی۔\n(۵) ان کا یہ کہنا ”ھذا المتن شاذ“ اگر ان کی مراد یہ ہے کہ وہ اس میں متفرد ہیں، قطع نظر اس سے کہ اس کے موافق کوئی روایت مل جائے، تو اس پر صحیح ہونے کا حکم لگایا جائے گا، تو شاذ نہیں، اور اگر یہ مراد ہے کہ یہ اپنے راویوں کے ثقہ ہونے کے باوجود شاذ ہے تو پھر مطابقت اور اختصار کا احتمال ہے۔","",{"fn":"(1) تجرید (۱۰۰/۲)\n(2) مستدرک حاکم (۱۶/۳)، کامل فی الضعفاء (۲۴۵/۶)، تاریخ مختصر دمشق (۳۲۱/۴)، میزان الاعتدال (۱۸۹۶)، (۱۸۹۸)، تذکرۃ الموضوعات (۹۹۵)، اللآلی المصنوعۃ (۲۲/۱)"}],[8616,"§۸۶۴۲ ۔ نابغہ جعدی(1)\nلمبی عمر والے مشہور شاعر ہیں، ان کے نام میں اختلاف ہے، بعض کا قول ہے: قیس بن عبد اللہ بن عدس بن ربیعہ بن جعدہ، بعض کا قول ہے: عدس کے بدلے وجوح ہے، جعدہ وہ ابن کعب بن ربیعہ بن عامر بن صعصعہ ہیں۔ بعض نے کہا: نابغہ کا نام عبد اللہ ہے، بعض نے کہا: حبان بن قیس بن عمرو بن عدس ہیں، ایک قول ہے: حبان بن قیس بن عبد اللہ بن قیس، بقول بعض قیس کو عبد اللہ پر تقدیم حاصل ہے، متحدی ابو فرج اصبہانی نے اس پر اعتماد کیا ہے، پہلے قول پر ابن کلبی، ابوحاتم(2) سجستانی، ابوعبیدہ محمد بن سلام جمحی وغیرہ نے اعتماد کیا ہے، اسے بغوی رحمہ اللہ نے ان کے حوالے سے نقل کیا ہے، ابو فرج اصبہانی نے نقل کیا ہے کہ وہ غلط ہے، کیونکہ ان کا ایک بھائی تھا، جس کا نام وحول بن قیس تھا، وہ جاہلیت میں قتل ہو گیا، نابغہ نے اس کا مرثیہ کہا۔(3)\nمیں کہتا ہوں: احتمال ہے کہ وحول ان کے ماں شریک بھائی ہوں، حسن بن سفیان نے اپنی مسند میں بحوالہ یعلی بن اشدق نقل کیا ہے کہ مجھ سے قیس بن عبد اللہ بن عدس بن ربیعہ نابغہ بن جعدہ نے بیان کیا، پھر حدیث ذکر کی، ابو فرج کا قول ہے: ایک مدت تک انہوں نے شعر و شاعری ترک کر دی، پھر شعر کہنے لگے تو انہیں ”نبغ“ کہا جانے لگا، ایک قول ہے: وہ شعر و شاعری کرتے تھے، پھر انہوں نے اسے جاہلیت میں ترک کر دیا، جب اسلام لائے تو پھر شعر کہنے لگے تو انہیں ”نبغ“ کہا گیا، تحذمی کا قول ہے: نابغہ قدیم شاعر تھے، عجیب کلام کہنے والے، جاہلیت اور اسلام میں طویل عمر پانے والے ہیں، کہتے ہیں: انہوں نے نابغہ ذبیانی سے زیادہ طویل عمر پائی، ان کے اشعار جوان کی لمبی عمر پر دلالت کرتے ہیں یہ ہیں:\n”سنو! بنو اسد کا گمان ہے کہ میں لمبی عمر والے بیٹے کا باپ ہوں، مجھ سے اگر کوئی میرے بارے میں پوچھے تو میں خنان نامی بیماری کے سالوں والے جوانوں میں سے ہوں جس سال میری ولادت ہوئی اسے گزرے ہوئے ایک سو بارہ(۱۱۲) سال ہو چکے ہیں، زمانے کے حوادثات نے مجھے ایسے ہی باقی رکھا ہے جیسے میں نے یمنی تلوار کو باقی رکھا ہے۔“\nابوحاتم بجستانی(4) کتاب المعمرین میں لکھتے ہیں: دوسو(۲۰۰) سال زندہ رہے، انہوں نے کہا:\n”امامہ نے کہا: کتنی عمر ہے تمہاری، بتوں پر تم نے بھینٹ چڑھائی، میں بازار عکاظ کی جگہ کو اس کے بننے سے پہلے دیکھ چکا ہوں، اور میں نوجوانوں میں شمار ہوتا تھا، اس وقت منذر بن محرق اپنی بادشاہت پر قائم تھا، میں نعمان کے ہجائن کے دن موجود تھا، میں نے اتنی عمر پائی کہ احمد صلی اللہ علیہ وسلم ہدایت لے کر آگئے، اور ایسی آیات پڑھیں جو کھٹکھٹانے والی تھیں، میں نے اسلام میں داد و دہش کا وہ کشادہ کپڑا پہنا جس میں نہ محرومی ہے، نہ احسان کا جتلاوا۔“\nابن عبد البر(5) کا قول ہے: مؤرخین نے اس بات کو دلیل بنا کر کہا ہے کہ وہ نابغہ ذبیانی سے عمر رسیدہ ہیں، کیونکہ انہوں نے کہا ہے کہ انہوں نے منذر بن محرق کا زمانہ پایا ہے، اور نابغہ ذبیانی نے نعمان بن منذر کا زمانہ پایا ہے، نابغہ ذبیانی ان سے مدت پہلے وفات پاگئے تھے، اس لیے یہ خیال کیا جاتا تھا کہ نابغہ ذبیانی، جعدی سے بڑے ہیں، عمر بن شبہ نے بحوالہ اپنے شیوخ ذکر کیا ہے کہ ان کی عمر ایک سو اسی(۱۸۰) سال تھی، انہوں نے سیدنا عمر بن خطاب رضی اللہ عنہ کے سامنے یہ شعر پڑھا:\n”کچھ لوگوں کے ساتھ میں رہا وہ فنا ہو گئے، ان کے بعد پھر کچھ اور لوگوں کا زمانہ میں نے پایا وہ بھی فنا ہو گئے، تین صدیوں کے لوگ میرے سامنے صفحہ ہستی سے مٹ گئے، بس اللہ کی ذات ہی ہے جو سب کے عوض ہے۔“(6)۔\nان سے سیدنا عمر رضی اللہ عنہ نے فرمایا: آپ ہر زمانے والوں کے ساتھ کتنا عرصہ رہے؟ انہوں نے کہا: ساٹھ(۶۰) سال۔(7) ابن قتیبہ کا قول ہے: اس کے بعد وہ سیدنا عبد اللہ بن زبیر رضی اللہ عنہ کے زمانے تک زندہ رہے، اور اصبہان میں وفات پائی ان کی عمر دوسو بیس(۲۲۰) برس تھی۔ مرزبانی(8) نے اسی طرح ذکر کیا ہے، لیکن ان کی عمر میں اختلاف کیا ہے۔ انہوں نے یہ اضافہ کیا ہے کہ وہ سیدنا علی رضی اللہ عنہ کے ساتھیوں میں سے تھے، ان کے سیدنا معاویہ رضی اللہ عنہ کے ساتھ بھی واقعات ہیں، اصمعی رحمہ اللہ کے حوالے سے روایت ہے کہ وہ دوسو تیس(۲۳۰) برس زندہ رہے، ہم نے حاکم کی کتاب میں بطریق نضر بن شمیل روایت کیا ہے کہ ان سے پوچھا گیا کہ انہوں نے سب سے لمبی عمر والے کس شیخ سے ملاقات کی ہے؟ النتجع الاعرابی کہتے ہیں: میں نے ان سے پوچھا: آپ سب سے بڑی عمر والے کس شخص سے ملے ہیں؟ انہوں نے فرمایا: النابغہ الجعدی۔ فرماتے ہیں: میں نے ان سے پوچھا: آپ نے جاہلیت کا کتنا زمانہ پایا ہے؟ کہنے لگے: ”دارین“۔ نضر فرماتے ہیں: یعنی دوسو سال، ابو عبیدہ معمر بن المثنی کا قول ہے: نابغہ ان لوگوں میں سے ہیں جنہوں نے جاہلیت میں سوچ و بچار سے کام لیا، شراب، نشہ آور اشیاء کا انکار کیا۔ تقسیم کے تیروں کو چھوڑا اور بتوں سے دور رہے، دین ابراہیمی کا پرچار کیا۔ وہی اپنے ایک قصیدے میں کہتے ہیں:\n”تمام تعریف اللہ تعالیٰ کے لیے ہے، اس کا کوئی شریک نہیں، جس نے یہ نہ کہا تو اس نے اپنے نفس پر ظلم کیا۔“\nابو عمر(9) کا قول ہے: اس قصیدے میں توحید کی اقسام، بعث بعد الموت جزا و سزا اور جنت جہنم کا اقرار ہے۔ جیسا امیہ بن ابی الصلت کے اشعار ہوتے ہیں۔ بقول بعض: یہ امیہ کا شعر ہے۔ لیکن حماد راویہ، یونس بن حبیب، محمد بن سلام جمحی اور علی بن سلیمان الاخفش نے نابغہ کا صحیح قرار دیا ہے۔ میں نے قاہرہ میں علی بن محمد مشقی کے سامنے قاہرہ میں عن سلیمان بن حمزہ وہ فرماتے ہیں: ہمیں علی بن الحسین نے زبانی بتایا کہ ابوالقاسم ابن البناء نے ہمیں تحریراً بتایا۔ ابوالنصر الطوسی، ابوطاہر المخلص، ابوالقاسم بغوی، داؤد بن رشید، ان کے سلسلہ سند میں یعلی بن الاشدق سے روایت ہے کہ میں نے نابغہ الجعدی کو کہتے سنا: میں نے نبی صلی اللہ علیہ وسلم کے سامنے یہ شعر پڑھا:\nبلغنا السماء مجدنا وجدودنا . وانا لنرجو فوق ذلك مظهرا\n”ہمیں ہماری قدر و منزلت اور عزت نے آسمان تک پہنچا دیا جبکہ ہم اس سے زیادہ اوپر کی ظاہر ہونے کی جگہ کے امیدوار ہیں۔“\nآپ علیہ السلام نے فرمایا: ابولیلی، مظہر کہاں ہیں؟ میں نے عرض کی: جنت میں۔ آپ نے فرمایا: ہاں۔ ان شاء اللہ تعالی، پھر کہا:\nولاخير في حلم اذا لم يكن له بوادر تحمى صفوه ان يكدرا\n”اس بردباری، برداشت اور عقلمندی میں کوئی بھلائی نہیں جس کی ایسی علامات نہ ہوں جو اس کی صفائی کو مکدر و خراب ہونے سے بچا سکیں۔“\nولا خير في جهل اذا لم يكن له حليم اذا ما اورد الامر اصدرا\n”اور نہ اس جہالت میں کوئی بھلائی ہے جس کے لیے کوئی بردبار نہ ہو جب وہ کوئی اعتراض کرے تو اس کا جواب دے دے۔“\nتو رسول اللہ صلی اللہ علیہ وسلم نے دوبارہ فرمایا: ”اللہ تمہارے دانت سلامت رکھیں۔“(10) اسی طرح یہ روایت بزار، حسن بن سفیان نے اپنی اپنی مسند میں، ابونعیم نے ”تاریخ اصبہان“ میں اور شیرازی نے ”الالقاب“ میں سب کے سب بروایت یعلی بن الاشدق نقل کرتے ہیں۔ جو ایسا راوی ہے جس کی حدیث ساقط الاعتبار ہے۔ ابو نعیم لکھتے ہیں: یہ روایت یعلی سے ایک جماعت نقل کرتی ہے جن میں ہاشم بن قاسم حرانی، ابو بکر باہلی اور عروہ العرقی سرفہرست ہیں۔ لیکن ان کی متابعت کی گئی ہے۔ ہمیں خطابی کی غریب الحدیث میں ایک واقعہ ملا ہے اور مرجبی کی کتاب العلم میں بطریق مہاجر بن سلیم عن عبد اللہ بن جراد مروی ہے کہ میں نے نابغہ الجعدی کو کہتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے اپنا یہ شعر پڑھا: عَلَونَا السَّمَاء، تو آپ ناراض ہو گئے۔ اور فرمانے لگے: ابولیلی! مظہر کہاں ہے؟ میں نے عرض کی: جنت میں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں! ان شاء اللہ تعالی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”اپنا شعر مجھے سناؤ۔“ تو میں نے یہ دو اشعار سنائے، ولا خیر فی حلم، آپ صلی اللہ علیہ وسلم نے فرمایا: ”بہت اچھا! اللہ تمہارا منہ سلامت رکھے۔“ تو میں نے ان کے دانت دیکھے تو جیسے اولے ہوتے ہیں، نہ ان کا کوئی دانت جدا ہوا اور نہ نکل کر گیا۔\nاور ہم نے مؤتلف میں، دارقطنی کے مختلف میں، ابن سکن کے صحابہ، وغیرہ کتابوں میں بطریق رحال بن منذر روایت کی ہے کہ مجھ سے میرے والد نے بحوالہ اپنے والد کرز بن اسامہ نقل کیا ہے، انہیں نابغہ جعدی کے ساتھ آنے کی سعادت حاصل ہے، پھر اس روایت کو اسی مفہوم میں ذکر کیا ہے۔ ہم نے سلفی کی کتاب اربعین البلدانیہ میں بطریق ابو عمرو بن علا، بحوالہ نصر بن عاصم لیثی، انہوں نے اپنے والد سے نقل کیا ہے کہ میں نے نابغہ کو کہتے ہوئے سنا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو میں نے یہ شعر سنایا: أتیت رسول اللہ.... شعر، اس کے بعد بلغنا السماء.... شعر۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کہاں تک؟ اے ابو لیلی؟“ میں نے کہا: جنت تک، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ان شاء اللہ....“۔ جب میں نے آپ کو اپنا یہ شعر سنایا: ولا خیر فی جہل اور ولا خیر فی حلم۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے سچ کہا، اللہ تمہارا منہ سلامت رکھے۔ تو بقیہ عمر ان کے دانت سب لوگوں سے اچھے تھے، جب بھی کوئی دانت گرتا تو اس کی جگہ دوسرا آجاتا۔ اس وقت وہ عمر رسیدہ تھے۔\nہم نے اسے مسند حارث بن ابی اسامہ میں بطریق حسن بن عبید اللہ عنبری نقل کیا ہے، فرماتے ہیں: مجھ سے اس شخص نے بیان کیا جس نے نابغہ جعدی سے یہ کہتے ہوئے سنا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ صلی اللہ علیہ وسلم کے سامنے یہ اشعار پڑھے:\n”ہم ایسی قوم ہیں جب ہم دشمن سے ملتے ہیں تو ہم اپنے گھوڑوں کو نہیں موڑتے یہاں تک کہ وہ خود ہی بہت جائیں یا بدک جائیں، جنگ کے دن ہم اپنے گھوڑوں کے رنگ نیزہ بازی کی وجہ سے بھول جاتے ہیں۔ حالت یہ ہو جاتی ہے کہ ہم سفید کو سرخ سمجھنے لگتے ہیں، ہمارے لیے یہ بات اچھی نہیں ہوتی کہ ہم ان گھوڑوں کو صحیح سالم لوٹائیں، اور نہ یہ بات عجیب سمجھی جاتی ہے کہ ان پر گرد و غبار پڑے، ہم نے آسمان کی بلندیوں کو چھولیا.... بقیہ قصیدہ اسی طرح ہے۔“\nہم نے اس روایت کو مسلسلۃ بالشعراء بروایت دعمل بن علی شاعر، عن ابی نواس، عن والبہ بن خباب، عن فرزدق، عن طرماح، بحوالہ نابغہ، یہ روایت ابو زرعہ رازی جو متاخر ہیں ان کی کتاب الشعراء میں موجود ہے۔\n”مَنْ جاوز المائۃ“ نامی کتاب میں ان کے حالات اور جو کچھ کوئی ان کے اور ماجرایات کے درمیان جیسے لیلیٰ اخیلیہ توبہ کی محبوبہ، اور اوس مرئی وغیرہ کے درمیان جاری رہی، طویل انداز سے اس کتاب میں بیان ہوئی ہے، ابو نعیم نے تاریخ اصبہان میں لکھا ہے کہ یہ وہ قیس بن عبد اللہ ہیں جو اصبہان میں فوت ہوئے، لکھتے ہیں کہ امیر معاویہ نے انہیں حارث بن عبد اللہ بن عوف بن اصرم کے ساتھ اصبہان روانہ کیا تھا، اور وہ سیدنا علی رضی اللہ عنہ کی طرف سے اصبہان کے والی تھے اور پھر بطریق امام اصمعی رحمہ اللہ عن ہانی بن عبد اللہ عن ابیہ عن عبد اللہ بن صفوان مندا نقل کیا ہے کہ نابغہ ایک سو بیس(۱۲۰) سال زندہ رہے۔ ابن عبد البر(11) نے نقل کیا ہے کہ نابغہ کا قصیدہ تقریباً دو سو(۲۰۰) اشعار پر مشتمل طویل قصیدہ ہے۔ اس کا مطلع ہے:\n”میرے دوستو! گھڑی بھر آ تخصیص سچ لو یا چھوڑ دو جو کچھ زمانے نے تمہیں نہیں کیا ہے، اس پر ملامت کرو یا چھوڑ دو۔“\nاسی میں کہتے ہیں:\n”میں اس وقت اللہ کے رسول کے پاس آیا جب آپ ہادی بن کے آئے اور آپ ایسی کتاب کی تلاوت کیا کرتے تھے جو کہکشاں کی طرح روشن تھی۔“\nاسی میں سے یہ اشعار ہیں:\n”میں نے فاقے کی اتنی مشقت اٹھائی کہ مجھے یہ بھی محسوس نہ ہوا کہ میرے ساتھ جو ہے جب وہ چکتا ہے، سہیل ستارہ ہے پھر وہ ڈوب جاتا ہے۔ میں تقویٰ پر قائم رہتا ہوں اور تقویٰ کے کاموں پر راضی ہوں اور میں اس جہنم سے جس کا لوگ خوف کرتے ہیں زیادہ ڈرنے والا ہوں۔“\nابو نعیم فرماتے ہیں: میرا خیال ہے کہ انہوں نے یہ پورا قصیدہ نبی علیہ السلام کے سامنے پڑھا ہے، پھر ابو عمر، ابو الفرج ریاشی تک اپنی سند سے لکھتے ہیں کہ اس قصیدے میں سے چونتیس(۳۴) اشعار ہیں۔\nعمر بن شبہ، مسلمہ بن محارب سے روایت کرتے ہیں کہ نابغہ جعدی سیدنا علی رضی اللہ عنہ کے پاس آئے پھر ایک واقعہ ذکر کیا۔ تاریخ اصبہان میں ابو نعیم کا بیان ہے اور ابن ابی خیثمہ نے اپنی تاریخ میں بحوالہ زبیر بن بکار روایت کی ہے، اور مجھ سے میرے بھائی ہارون بن ابی بکر نے عن یحیی بن ابی قتیلہ، عن سلیمان بن محمد بن یحیی بن عروہ، عن ابیہ، عن عمہ عبد اللہ بن عروہ بیان کیا: نابغہ بنی جعدہ پر خشک سالی مسلط ہوئی تو وہ سیدنا ابن زبیر رضی اللہ عنہ کے پاس مسجد حرام میں آئے اور یہ اشعار سنائے، جب تم ہمارے والی بنے تو تم نے ہمارے سامنے صدیق اکبر، عثمان غنی اور فاروق اعظم رضی اللہ عنہم جیسی مثال پیش کی، جس سے نادار شخص نے راحت پائی۔ آپ نے لوگوں میں حق دینے میں برابری کی یہاں تک کہ وہ برابر ہو گئے، پھر رات کی تاریکی میں پھنسا ہوا روز روشن کی طرح لوٹ آیا، ابو لیلیٰ کے آپ کے پاس آیا ہے، تاریکیاں یعنی شب دیجور سے اسے لے لیں اور وقت صحراؤں میں گھما رہی ہیں، تاکہ آپ اس کی اس جانب کو مرمت کریں، جسے راتوں کی گردش اور سخت زمانے کے اتار چڑھاؤ نے توڑ دیا ہے۔ سیدنا ابن الزبیر رضی اللہ عنہ فرمانے لگے: ابو لیلیٰ! اپنے اوپر رحم کیجئے! کیونکہ اشعار آسان ہیں اور آپ کا سوال کنندہ ہمارے پاس ہے۔ اللہ کے مال میں آپ کا دہرا حق ہے۔ ایک حق رسول اللہ صلی اللہ علیہ وسلم کا دیدار کرنے کی وجہ سے اور دوسرا حق آپ کا مسلمانوں کے ساتھ غموں میں شرکت کی بنا پر، پھر ان کا ہاتھ پکڑ کر دارالنعم (اصطبل) میں لے گئے جہاں سے انہیں سات اونٹنیاں، بار برداری کے جانور اور گھوڑے دیئے اور ان پر گندم، کھجوریں اور کپڑے لاد دیئے۔ نابغہ جلدی کرنے لگے اور صرف دانے کھانے لگے۔ ابن زبیر فرمانے لگے: ابو لیلیٰ کا بھلا ہو انہیں سخت بھوک لگی ہے۔ نابغہ نے کہا: میں گواہی دیتا ہوں میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: قریش جب بھی والی و حکمران بنے تو انہوں نے عدل کیا۔ رحم کی درخواست کی گئی تو رحم کیا بات کی تو سچ بولا، جو اچھا وعدہ کیا اسے پورا کیا، میں اور انبیاء اور تابعین کی جماعت(12) (عرش کے سائے تلے ہوگی)۔ یہ حدیث ہمیں عالی سند سے حدیث ابن الزبیر سے موافق ملی ہے، قرأت علی فاطمۃ بنت محمد بن المنجی بدمشق عن سلیمان بن حمزہ، انبانا محمود بن ابراھیم فی کتاب انبانا مسعود بن حسن انبانا ابو بکر السمسار انبانا ابو اسحاق بن خرشہ، انبانا ابو الحسن المخزومی۔ فرماتے ہیں: ہم سے زبیر بن بکار نے مکمل حدیث بیان کی۔ اسے ابن جریر نے اپنی تاریخ میں ابن ابی خیثمہ سے اور ابو الفرج الاصبہانی نے ”الاغانی“ میں ابن جریر سے اور ابن ابی عمر نے اپنی مسند میں ہارون سے اور ابن اسکن نے محمد بن ابراہیم الانماطی سے اور طبرانی ”الصغیر“ میں عن حسین بن الفہم اور ابو الفرج اصبہانی نے حرمی بن العلاء سے تینوں زبیر سے نقل کرتے ہیں جو ہمیں عالی کے بدل واقع ہوئی۔ ابو نعیم نے بحوالہ طبرانی اطراف میں اس کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۶۲) استیعاب (۲۶۸۴) تجرید (۱۰۰/۲)\n(2) المعمرین (۸۱)\n(3) جامع المسانید والسنن (۸۵/۱۲)\n(4) المعمرین (۸۴)\n(5) استیعاب (۷۷/۴)\n(6) الاوس: عطیہ و عوض\n(7) اسد الغابہ (۲۰۹/۴) استیعاب (۷۷/۴) الشعر والشعراء (۲۹۰/۱) وسط اللآلی (۲۴۸/۱)\n(8) الشعر والشعراء (۳۹۵/۱) الروض الأنف (۵۳/۱)\n(9) استیعاب (۷۷/۴)\n(10) جامع المسانید (۸۵/۱۲) اسد الغابہ (۲۱۰/۴) استیعاب (۷۷/۴) الشعر والشعراء (۲۸۱/۱) معجم الشعراء (۱۹۵)\n(11) استیعاب (۷۷/۴)\n(12) اسد الغابہ (۵۱۶۳) الاستیعاب (۱۶۸۵) تجرید اسماء الصحابہ (۱۰۰/۲)"}],[8617,"§۸۶۴۳ ۔ نابل الحبشی (ایمن کے والد)\nابو احمد العسال کا قول ہے: صحابی ہیں۔ ابو عمر(1) کا قول ہے: مجھے کوئی ایسی حدیث نہیں ملی جو ان کی ملاقات پر دلالت کرتی ہو، ابو موسیٰ نے ذیل میں بطریق ابو شیخ بحوالہ ایمن بن نابل، انہوں نے اپنے والد سے نقل کیا ہے کہ ایک اعرابی شخص نے رسول اللہ صلی اللہ علیہ وسلم کو دو اونٹنیاں ہدیہ دیا، آپ صلی اللہ علیہ وسلم نے انہیں بدلہ دیا تو انہوں نے دو مرتبہ انکار کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے پکا ارادہ کر لیا ہے کہ قریش، انصاری اور ثقفی کے علاوہ کسی کا ہدیہ قبول نہیں کروں گا۔“ ابو موسیٰ(2) کا قول ہے: اسے ایک جماعت نے بحوالہ بکار نقل کیا ہے۔\nمیں کہتا ہوں: وہ ضعیف ہیں۔","",{"fn":"(1) استیعاب (۸۳/۴)\n(2) المعجم الکبیر (۹۳۳/۱۸) مجمع الزوائد (۲۵/۱۰) اسد الغابہ (۲۱۱/۴) استیعاب (۸۳/۴)"}],[8618,"§۸۶۴۴ ۔ ناجیہ بن اعجم اسلمی(1)\nابن سعد(2) نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ فرماتے ہیں: ان کی اولاد نہیں۔ انہوں نے بحوالہ واقدی، انہوں نے عطاء بن ابی مروان سے، انہوں نے اپنے والد سے نقل کیا ہے کہ مجھ سے ان چودہ(۱۴) افراد نے نقل کیا ہے۔ جو نبی کریم صلی اللہ علیہ وسلم کے اصحاب میں سے تھے اور اسلام لائے تھے کہ ناجیہ بن اعجم وہ شخص ہیں جو حدیبیہ کے دن رسول اللہ صلی اللہ علیہ وسلم کا وہ تیر لے کر کم پانی والے کنوئیں میں اترے تھے، جو آپ صلی اللہ علیہ وسلم نے اپنے ترکش سے انہیں عطا فرمایا تھا، اور انہیں حکم دیا تھا کہ اسے پانی میں گاڑ دیں، اور اس میں رسول اللہ صلی اللہ علیہ وسلم کے وضو کا پانی ڈال دیں، انہوں نے ایسا ہی کیا، فرماتے ہیں: بعض کا قول ہے، کنوئیں میں اترنے والے ناجیہ بن جندب تھے، جیسا کہ ان کے سوانح میں آئے گا، عطوی کا قول ہے: رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ اسلم کو فتح کے دن دو جھنڈے دیئے، ان میں سے ایک ناجیہ بن اعجم کو اور دوسرا بریدہ بن حصیب کو دیا۔ اسے ابن ابی حاتم نے ذکر کیا ہے، اور بحوالہ اپنے والد نقل کیا ہے کہ انہوں نے فرمایا: میں انہیں نہیں جانتا، ابن شاہین نے صحابہ میں فرمایا: مدینہ میں خلافت معاویہ کے آخر میں فوت ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۱۶۴) تجرید (۱۰۰/۲)\n(2) طبقات الکبریٰ (۲۱۴/۴)"}],[8619,"§۸۶۴۵ ۔ ناجیہ بن جندب(1)\nبن عمیر بن مہر بن دارم بن وانلہ بن سہم بن مازن بن سلامان بن اسلم اسلمی، ابن اسحاق(2) کا قول ہے: مجھ سے بعض اہل علم نے قبیلہ اسلم کے کئی لوگوں سے روایت کیا ہے کہ جو رسول اللہ صلی اللہ علیہ وسلم کا تیر لے کر کنوئیں میں اترے تھے وہ ناجیہ بن جندب اسلمی، رسول اللہ صلی اللہ علیہ وسلم کے اونٹوں والے ہیں فرماتے ہیں: بعض اہل علم کا گمان ہے کہ سیدنا براء بن عازب فرماتے ہیں: میں کنوئیں میں اترا تھا۔ ابن اسحاق کا قول ہے: قبیلہ اسلم کا کہنا ہے کہ انصار کی ایک باندی اپنا ڈول لے کر آئی اور ناجیہ لوگوں کو کنوئیں میں سے ڈول بھر بھر کے دے رہے تھے تو اس نے کہا:\n”اے ڈول بھرنے والے! میرا ڈول لے لے، میں نے دیکھا ہے کہ لوگ تیری تعریف کرتے ہیں۔“\nتو انہوں نے کہا:\n”یمنی باندی آئی اور میں لوگوں کو ڈول بھر بھر کے دے رہا ہوں، میرا نام ناجیہ ہے۔“\nسعید بن عفیر کا قول ہے: ان کا نام ذکوان تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام ناجیہ رکھا، جب انہوں نے قریش سے نجات پائی(3) ابن ابی حاتم نے بحوالہ اپنے والد نقل کیا ہے: ناجیہ رسول اللہ صلی اللہ علیہ وسلم کے اونٹوں والے تھے وہ خلافت معاویہ رضی اللہ عنہ میں مدینہ میں وفات پاگئے۔(4)\nحسن بن ابو سفیان نے اپنی مسند میں بطریق موسیٰ بن عبیدہ، بحوالہ عبد اللہ بن عمرو بن اسلم، انہوں نے ناجیہ بن جندب نقل کیا ہے، فرماتے ہیں: ہم غمیم میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس قریش کی خبر آئی کہ انہوں نے خالد بن ولید کو گھڑ سواروں کے دستے کے ساتھ رسول اللہ صلی اللہ علیہ وسلم سے لڑائی کے لیے روانہ کیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے ان سے لڑائی کو ناپسند کیا، آپ صلی اللہ علیہ وسلم ان پر مہربان تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”کیا کوئی شخص ہے جو ہمیں اس راستے کے علاوہ دوسرے راستے سے لے جائے؟“ میں نے کہا: میں، یا رسول اللہ! میرے ماں باپ آپ پر قربان ہوں۔ فرماتے ہیں، میں انہیں ایسے راستے سے لے گیا جو دشوار گزار اور گھاٹیوں والا تھا، زمین میرے لیے ہموار ہو گئی یہاں تک کہ میں نے انہیں حدیبیہ میں جا اتارا، ان دنوں اس سے پانی لیا جاتا تھا، فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے اس میں اپنے ترکش سے ایک یا دو تیر ڈالے پھر اس میں اپنا لعاب دہن ڈالا اور تیر والوں کو واپس بلایا، جس سے اس کے چشمے بہنے لگے یہاں تک کہ میں کہنے لگا: اگر ہم چاہیں تو اپنے پیالے بھر لیں، ابن مندہ کی کتاب المعرفہ میں ہمیں یہ روایت عالی سند سے ملی ہے۔ اسی طرح اسے ابن سکن اور طبرانی نے بطریق موسیٰ بن عبیدہ نقل کیا ہے۔ انہیں اس بارے میں شک ہے کہ وہ ناجیہ بن جندب ہیں یا جندب بن ناجیہ، موسیٰ ضعیف ہیں، ناجیہ بن جندب کی ایک اور حدیث ہے جسے ابن مندہ نے مجزأۃ بن زاہر کے طریق سے بحوالہ ان کے والد، انہوں نے ناجیہ بن جندب سے نقل کیا ہے۔ فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اس وقت آیا۔ جب قربانی کے جانور روک دیئے گئے تھے، میں نے کہا: یا رسول اللہ! میرے ساتھ قربانی کے جانور بھیجیں تاکہ میں انہیں حرم میں ذبح کروں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم یہ کیسے کرو گے؟ فرماتے ہیں: میں نے کہا: میں انہیں ایسی وادی سے لے جاؤں گا جس پر ان کو دسترس نہیں، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے انہیں میرے سپرد کر دیا، میں نے انہیں حرم(5) میں ذبح کر دیا۔\nابن مندہ کا قول ہے: بحوّل بن ابراہیم نے اسے اسرائیل سے، ان کے حوالے سے نقل کیا ہے، اسے ان سے ابو حاتم رازی وغیرہ نے روایت کیا ہے اسی طرح منقول ہے۔\nاسے نسائی نے بطریق عبد اللہ بن موسیٰ، بحوالہ اسرائیل انہی الفاظ میں نقل کیا ہے، اسے ابو نعیم نے بطریق محمد بن عمرو بن محمد عنقری، بحوالہ اسرائیل نقل کیا ہے، لیکن اس میں فرماتے ہیں: عن ناجیہ جندب، عن ابیہ، اسی طرح اسے طحاوی نے بطریق محول نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۶۵) استیعاب (۲۶۸۶) تجرید (۱۰۰/۲)\n(2) السیرۃ النبویۃ (۲۴۳/۳)\n(3) جامع المسانید والسنن (۱۸۸/۱۲) استیعاب (۸۳/۴)\n(4) مؤطا امام مالک (۸۸۰) جامع المسانید والسنن (۸۸/۱۲) اسد الغابہ (۲۱۲/۴) استیعاب (۸۳/۴)\n(5) جامع المسانید والسنن (۸۸/۱۲، ۸۹)"}],[8620,"§۸۶۴۶ ۔ ناجیہ بن عمرو حضرمی\nابن ابی عاصم نے وحدان میں ان کا ذکر کیا ہے، انہوں نے ابن قانع اور طبرانی نے بطریق مسلمہ بن رجاء بحوالہ عائذ بن شریح نقل کیا ہے کہ انہوں نے انس بن مالک، شعیب بن عمرو، ناجیہ بن عمرو سے سنا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو مہندی کا خضاب لگاتے ہوئے دیکھا ہے۔ بغوی(1) نے اسے ناجیہ اسلمی کے سوانح میں ذکر کیا ہے، انہیں وہم ہوا ہے۔ واللہ اعلم!","",{"fn":"(1) ہیثمی (۱۶۱/۵، ۱۶۲) المعجم الکبیر (۷۲۳۴/۷) الآحاد والمثانی (۳۱۴/۵) جامع المسانید والسنن (۱۹/۱۲)"}],[8621,"§۸۶۴۷ ۔ ناجیہ بن عمرو خزاعی(1)\nاسے ابن مندہ نے کتاب الموالاۃ میں ذکر کیا ہے اور بطریق عمرو بن عبد اللہ بن یعلی بن مرہ، انہوں نے اپنے والد سے، انہوں نے اپنے دادا سے نقل کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”میں جس کا دوست ہوں علی اس کا دوست ہے۔“(2) جب سیدنا علی رضی اللہ عنہ کوفہ آئے تو لوگوں کو یہ یاد دلایا تو دس سے زیادہ آدمیوں نے اس کا اقرار کیا، ان میں ابو ایوب، ناجیہ بن عمرو خزاعی بھی ہیں، اسے ابو موسیٰ نے حضرمی کے سوانح میں ذکر کیا ہے، جو اس سے پہلے گزرے ہیں۔ میں سمجھتا ہوں یہ اور ہیں۔","",{"fn":"(1) اسد الغابہ (۵۱۶۹) تجرید (۱۰۱/۲)\n(2) ترمذی (۳۷/۲) مسند احمد (۳۷۰/۴) مستدرک حاکم (۱۰۹/۳) صحیح ابن حبان (۶۹۳۱) المعجم الکبیر (۴۹۶۹/۵) جامع المسانید والسنن (۹۱/۱۲) اسد الغابہ (۲۱۳/۴)"}],[8622,"§۸۶۴۸ ۔ ناجیہ بن کعب خزاعی(1)\nابن شاہین وغیرہ نے ان میں اور ان سے پہلے والے میں فرق کیا ہے، امام مالک نے موطا میں بحوالہ ہشام بن عروہ، انہوں نے اپنے والد کے حوالے سے نقل کیا ہے کہ ناجیہ نبی کریم صلی اللہ علیہ وسلم کے قربانی کے جانوروں والے تھے، انہوں نے آپ صلی اللہ علیہ وسلم سے پوچھا: جو اونٹ تھک جائے اس کا کیا کروں؟ تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ جو اونٹ تھک جائے اسے ذبح کر دیں، پھر اس کے گھر اس کے خون میں لت پت کریں پھر لوگوں کو کھانے دیں.... (الحدیث)۔\nاسی طرح اسے شعیب بن اسحاق، حماد بن سلمہ، ابو خالد احمر نے نقل کیا ہے، وکیع نے بحوالہ ہشام، انہوں نے اپنے والد سے، انہوں نے ناجیہ سے نقل کیا ہے، اسے احمد(2) نے نقل کیا ہے اور وکیع بن عیینہ، عبدہ، جعفر بن عون، روح بن قاسم وغیرہ نے بحوالہ ہشام ان کی متابعت کی ہے۔\nاسے ابن خزیمہ نے بطریق عبد الرحیم بن سلیمان، انہوں نے ان کے حوالے سے نقل کیا ہے، اس میں یہ الفاظ ہیں: حدثنی ناجیہ، اس کے موصول اور مرسل ہونے میں ابو معاویہ وہب بن خالد وغیرہ سے آگے اختلاف ہے، ان میں سے کسی نے ناجیہ کے والد کا نام نہیں لیا۔ لیکن بعض نے کہا: خزاعی، بعض نے کہا: اسلمی، تعدد بعید نہیں، حدیث ابن عباس رضی اللہ عنہما سے ثابت ہوا ہے کہ وہ ذویب خزاعی نے ان سے بیان کیا کہ وہ بھی اونٹوں کے ساتھ موجود تھے۔\nاسے ابن ابی شیبہ نے بطریق عروہ نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فتح مکہ کے موقع پر ناجیہ خزاعی کو جاسوس بنا کر بھیجا تھا۔\nابو فتح ازدی اور ابو صالح مؤذن نے یقین سے کہا ہے کہ عروہ، ناجیہ خزاعی سے روایت کرنے میں متفرد ہیں، اس سے پتہ چلتا ہے کہ وہ اسلمی نہیں۔","",{"fn":"(1) اسد الغابہ (۵۱۷۰) تجرید (۱۰۱/۲) مؤطا (۸۸۰)\n(2) مسند احمد (۶۴/۴) (۳۳۴/۴)"}],[8623,"§۸۶۴۹ ۔ ناجیہ طفاوی(1)\nابن مندہ کا قول ہے: صحابہ رضی اللہ عنہم میں ان کا ذکر ہے۔ وہ قرآن پاک لکھا کرتے تھے اور بطریق فروہ بن حبیب نقل کیا ہے کہ ہم سے براء بن عازب نے بحوالہ واصل نقل کیا ہے، فرماتے ہیں: مجھے رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص ملے جنہیں ناجیہ طفاوی کہا جاتا تھا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے پانچ نمازیں پڑھائیں۔(2) طبرانی نے بطریق فروہ بن حبیب اس سند سے نقل کیا ہے، فرماتے ہیں: ناجیہ مصاحف لکھا کرتے تھے، ان کے پاس ایک خاتون آئی.... پھر طویل قصہ ذکر کیا۔","",{"fn":"(1) اسد الغابہ (۵۱۶۸) استیعاب (۲۶۸۷) تجرید (۱۰۱/۲)\n(2) جامع المسانید والسنن (۹۲/۱۲) اسد الغابہ (۲۱۳/۴)"}],[8624,"§۸۶۵۰ ۔ ناسج حضرمی(1)\nابو فتح ازدی نے مفردات صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ بخاری رحمہ اللہ نے ان کا ذکر کیا ہے فرماتے ہیں: ناسج: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے شرجیل بن شفعہ نے روایت کی، ابن شاہین نے بطریق ولید بن مسلم، بحوالہ ناسج حضرمی نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم دو آدمیوں کے پاس سے گزرے جو ایک بکری کی خرید و فروخت میں قسم کھا رہے تھے۔ پھر بکری کے پاس سے گزرے جسے اس آدمی نے خرید لیا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”ان میں سے ایک نے واجب کر لی۔“(2) ابن ابی حاتم(3) کا قول ہے: بخاری رحمہ اللہ نے ناسج حضرمی نقل کیا ہے، اسے میرے والد نے بدل دیا، فرماتے ہیں: وہ عبد اللہ بن ناسج ہیں۔\nمیں کہتا ہوں: عبد اللہ نامی لوگوں میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۷۱) تجرید (۱۱۴۲/۲)\n(2) سنن کبریٰ (۳۵/۱۰) جامع المسانید والسنن (۹۳/۱۲) اسد الغابہ (۲۱۴/۴)\n(3) جرح والتعدیل (۱۸۴/۵) (۱۸۵/۵)"}],[8625,"§۸۶۵۱ ۔ ناعم بن اجیل(1)\nہمدانی، مولیٰ ام سلمہ، مستغفری کا قول ہے: بردی نے اپنی سند سے جو مجہول ہے بحوالہ لیث نقل کیا ہے کہ وہ صحابہ میں سے ہیں۔ ابن یونس(2) نے بطریق ابن لہیعہ نقل کیا ہے، فرماتے ہیں: ناعم ہمدان کے عزت والے گھرانے میں سے تھے، جاہلیت میں وہ قیدی بنائے گئے اور ام سلمہ رضی اللہ عنہا کے ہاں آئے، انہوں نے انہیں آزاد کر دیا۔(3) ابن یونس کا قول ہے: ناعم ان فقہاء میں سے تھے جنہوں نے یزید بن ابی حبیب کا زمانہ پایا، ابو نصر اسود بن عبد الجبار کا قول ہے: مجھے یہ بات معلوم ہوئی ہے کہ وہ ۸۰ھ میں فوت ہو گئے، اسی طرح ابو عمر کندی نے اہل مصر کے موالی میں ذکر کیا ہے۔ ابن حبان نے ثقات تابعین میں ان کا ذکر کیا ہے، فرماتے ہیں: جاہلیت میں قیدی بنائے گئے، سیدہ ام سلمہ رضی اللہ عنہا نے انہیں آزاد کیا۔\nمیں کہتا ہوں: اس سے ظاہر ہوتا ہے کہ وہ صحابی ہیں، اس لیے اس احتمال کی وجہ سے میں نے اس قسم میں ان کا ذکر کیا ہے، ابن سعد، یعقوب بن سفیان اور نسائی نے انہیں ثقہ کہا ہے۔","",{"fn":"(1) اسد الغابہ (۲۱۴/۴)\n(2) اسد الغابہ (۲۱۴/۴)\n(3) اکمال (۴۵/۱)"}],[8626,"§۸۶۵۲ ۔ ناعم (مولی رسول اللہ صلی اللہ علیہ وسلم)\nعسکری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: مجھے ان کی کوئی مسند حدیث معلوم نہیں اور بطریق کعب بن علقمہ نقل کیا ہے کہ مجھ سے ناعم، مولی رسول اللہ صلی اللہ علیہ وسلم نے نقل کیا ہے، فرماتے ہیں: میں سیدنا علی رضی اللہ عنہ کے پاس موجود تھا، انہوں نے اونٹ پر خطبہ دیا، پھر آگے بڑھے اس کے بعد نیچے اتر آئے، پھر سینگوں والا مینڈھا منگوایا، اسے ذبح کیا، اور فرمایا: یہ علی اور آل علی کی طرف سے ہے۔\nابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے، فرماتے ہیں: طبرانی نے تہذیب الآثار میں بطریق کعب بن علقمہ اس قصے کو نقل کیا ہے، ابن فتحون کا قول ہے: بخاری رحمہ اللہ نے ناعم بن اجیل کا ذکر کیا ہے، شاید وہ یہی ہیں۔\nمیں کہتا ہوں: ابن یونس نے ناعم بن اجیل کے سوانح میں نقل کیا ہے کہ انہوں نے سیدنا علی، عثمان رضی اللہ عنہم وغیرہ صحابہ سے نقل کیا ہے، رواۃ میں ان کے حوالے سے کعب بن علقمہ نے ذکر کیا ہے وہ دونوں ایک ہیں، ہو سکتا ہے کہ جس نے ان کا یہ وصف بیان کیا ہے کہ وہ مولی رسول اللہ صلی اللہ علیہ وسلم ہیں، انہوں نے اسے جائز کہا ہو، اس وجہ سے کہ وہ آپ صلی اللہ علیہ وسلم کی زوجہ محترمہ کے آزاد کردہ غلام ہیں۔"],[8627,"§۸۶۵۳ ۔ نافع بن بدیل(1)\nبن ورقاء خزاعی، قدیم الاسلام صحابی ہیں۔ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں شہید ہوئے، ان کے والد کا ذکر حرف باء میں اور ان کے بھائی کا ذکر عبد اللہ نامی لوگوں میں گزر چکا ہے۔ ابن اسحاق(2) کا قول ہے: مجھ سے میرے والد نے بحوالہ مغیرہ بن عبد الرحمن بن حارث بن ہشام اور عبد اللہ بن ابو بکر وغیرہ سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے منذر بن عمرو کو اہل نجد کی طرف مسلمانوں میں سے ستر(۷۰) بہترین آدمیوں کے ساتھ بھیجا، ان میں سے حارث بن صمہ، حرام بن ملحان، فروہ بن اسماء، نافع بن بدیل بن ورقاء خزاعی ہیں، وہ سب شہید ہو گئے۔ ابن رواحہ، نافع کی موت کی خبر دیتے ہوئے کہتے ہیں:\n”اللہ تعالیٰ نافع بن بدیل پر رحم فرمائے، وہ جہاد کا ثواب چاہنے والا، صبر کرنے والا، سچی بات کہنے والا تھا، جب لوگ اکٹھے ہوتے تو صحیح بات کہتا۔“\nاسے ابو سعید عسکری نے دیوان حسان بن ثابت میں نقل کیا ہے اس میں تیسرے شعر کا اضافہ کیا ہے۔\nمذکورہ روانگی بئر معونہ کی طرف تھی، کئی راویوں نے جن میں ابن کلبی بھی ہیں، انہوں نے جمہرہ میں وضاحت کی ہے کہ نافع بئر معونہ میں شہید ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۱۷۴) استیعاب (۲۶۲۱) تجرید (۱۰۱/۲)\n(2) السیرۃ النبویۃ (۱۴۶/۳) (۱۵۰)"}],[8628,"§۸۶۵۴ ۔ نافع بن حارث خزاعی(1)\nنافع بن عبد الحارث میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۶۹) تجرید (۱۰۲/۲)"}],[8629,"§۸۶۵۵ ۔ نافع بن حارث(1)\nبن کلدہ ثقفی، ابو بکرہ کے ماں شریک بھائی ہیں، ابو عمر(2) کا قول ہے: انہوں نے ابن عباس رضی اللہ عنہما کے حوالے سے نقل کیا ہے کہ یہ ان لوگوں میں سے تھے جو رسول اللہ صلی اللہ علیہ وسلم کے پاس طائف سے آئے تھے، ان کی والدہ سمیہ مولاۃ حارث تھیں۔\nابن سعد کا قول ہے: حارث نے ان کا دعویٰ کیا ہے، اور اعتراف کیا کہ وہ اس کا بیٹا ہے، لہذا ان کا نسب اس سے ثابت ہوا، وہ پہلے شخص ہیں جنہوں نے بصرہ میں گھوڑوں کو لازم پکڑا تھا۔(3) یہ ان لوگوں میں سے تھے جنہوں نے مغیرہ کے خلاف گواہی دی، انہوں نے سیدنا عمر بن خطاب سے بصرہ میں زمین کا ٹکڑا مانگا تھا۔ انہوں نے سیدنا ابو موسیٰ کو لکھا کہ انہیں دس جراب زمین دے دیں، اس میں کسی مسلم یا ذمی کا حق نہ ہو، انہوں نے ایسا ہی کیا۔\nابن ابی شیبہ نے بطریق محمد بن عبد اللہ ثقفی نقل کیا ہے، فرماتے ہیں: ثقیف میں سے ایک شخص آیا اسے نافع ابو عبد اللہ عمر کہا جاتا تھا۔ وہ پہلا شخص تھا جس نے بصرہ میں اونٹوں کو لازم کر لیا تھا۔ اس نے کہا: اے امیر المومنین! ہمارے ہاں ایسی زمین ہے جو خراج والی نہیں اور کسی کو نقصان نہیں دیتی، مجھے اس میں سے کچھ زمین عطا فرمائیں۔ میں اس پر اپنے گھوڑوں کا اصطبل بناؤں گا، کہتے ہیں: سیدنا عمر رضی اللہ عنہ نے ابو موسیٰ کو لکھا کہ جیسا یہ کہہ رہے ہیں اگر ایسا ہی ہے تو انہیں اس میں سے دے دیں۔ ابن سعد نے ان کے سوانح میں حدیث نقل کی ہے، میں اسے نافع کے آخر میں ذکر کروں گا۔","",{"fn":"(1) اسد الغابہ (۵۱۷) استیعاب (۲۶۲۲)\n(2) استیعاب (۵۲/۴)\n(3) جامع المسانید والسنن (۹۵/۱۲) اسد الغابہ (۲۱۶/۴)"}],[8630,"§۸۶۵۶ ۔ نافع بن زید حمیری(1)\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق زکریا بن یحیی بن سعید حمیری بحوالہ ایاس بن عمر و حمیری نقل کیا ہے کہ نافع بن زید حمیری، قبیلہ حمیر کے افراد کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد کی صورت میں آئے۔ انہوں نے کہا: ہم آپ کے پاس آئے ہیں تاکہ ہم دین کی سمجھ حاصل کریں، اور اس کائنات کی ابتداء کے بارے میں پوچھیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n”اللہ تعالیٰ کے سوا کچھ نہ تھا، اس کا عرش پانی پر تھا، پھر قلم کو پیدا کیا اور فرمایا: لکھو جو کچھ ہونے والا ہے، پھر آسمانوں، زمین اور جو کچھ اس میں ہے پیدا کیا، پھر عرش پر قرار پکڑا۔“(2)\nاس میں بہت سے مجہول راوی ہیں۔","",{"fn":"(1) اسد الغابہ (۵۱۷۲)\n(2) بخاری (۳۱۹۱) (۷۴۱۸) ترمذی (۳۹۵۱) مسند احمد (۴۲۶/۹) (۴۳۶/۴) صحیح ابن حبان (۶۱۴۲)"}],[8631,"§۸۶۵۷ ۔ نافع بن سلیمان عبدی(1)\nبعض کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا اور آپ سے حدیث یاد کی، اس وقت وہ کم عمر تھے، اسحاق بن راھویہ نے اپنی مسند میں ان کی حدیث نقل کی ہے، فرماتے ہیں: مجھے سلیمان بن نافع عبدی نے حلب میں بتایا، فرماتے ہیں: مجھ سے میرے والد نے بیان کیا کہ منذر بن ساوی بحرین سے آئے ان کے ساتھ اور لوگ تھے، میں اس وقت لڑکا تھا، ان کے اونٹوں کو تھامے رکھتا، وہ اپنے ہتھیار ساتھ لے گئے اور نبی کریم صلی اللہ علیہ وسلم کو سلام کیا، منذر نے اپنے ہتھیار رکھے، اپنے پاس جو کپڑے تھے وہ پہنے، اپنی داڑھی پر تیل لگایا، پھر نبی کریم صلی اللہ علیہ وسلم کے پاس آئے، میں اونٹوں کے پاس رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہا تھا، منذر کا قول ہے: مجھ سے نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”میں نے تم میں ایسی بات دیکھی ہے جو تمہارے ساتھیوں میں نہیں ہے۔ میں نے کہا: کیا وہ میری فطرت میں ہے یا میں نے خود اختیار کی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! بلکہ تمہاری فطرت میں ہے۔ جب وہ لوگ اسلام لے آئے تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”قبیلہ عبد قیس خوشی سے اسلام آیا اور لوگ مجبوری سے اسلام لائے۔“(2) سلیمان کا قول ہے: میرے والد ایک سو بیس(۱۲۰) سال زندہ رہے۔\nاسے طبرانی(3) اور ابن قانع دونوں نے بحوالہ موسیٰ بن ہارون بحوالہ اسحاق نقل کیا ہے، موسیٰ کا قول ہے: اسحاق کے ہاں اس سے اعلیٰ سند کی روایت نہیں۔\nاسے ابن بشران نے اپنے امالی میں بحوالہ دلی، انہوں نے موسیٰ اور سلیمان سے نقل کیا ہے، ابن ابی حاتم نے بحوالہ اپنے والد سے ذکر کیا ہے، اس میں جرح کا ذکر نہیں کیا۔\nوہ قصہ جسے منذر بن ساوی کے بارے میں ذکر کیا ہے وہ اصح کا ہے۔ ان کا نام منذر بن عائذ ہے، میرے خیال میں سلیمان کو اپنے والد کی عمر کے بارے میں وہم ہوا ہے۔ اس لیے کہ وفود کے سال وہ لڑکے تھے اور اتنی مقدار زندہ رہے تو ایک سو بیس(۱۲۰) سال تک زندہ رہے ہوں گے جو باطل ہے، شاید انہوں نے کہا ہو کہ وہ ایک سو دس(۱۱۰) سال تک زندہ رہے۔ اس لیے کہ سیدنا ابو طفیل فوت ہونے والے وہ آخری صحابی ہیں جنہوں نے نبی علیہ السلام کو دیکھا تھا اور ان کی وفات زیادہ سے زیادہ ایک سو دس(۱۱۰) ہجری بتائی جاتی ہے۔ صحیحین میں یہ ثابت ہے کہ آپ صلی اللہ علیہ وسلم نے اپنی آخری عمر میں فرمایا: اس رات کے سو(۱۰۰) سال بعد زمین پر موجود لوگوں میں سے کوئی نہیں رہے گا۔ اس سے مراد صدی کا اختتام تھا، ایسا ہی ہوا۔","",{"fn":"(1) اسد الغابہ (۵۱۷۹) تجرید (۱۰۲/۲)\n(2) ابوداؤد (۵۲۲۵) مسند احمد (۲۰۵/۴) صحیح ابن حبان (۷۲۰۳) ابن ابی عاصم الآحاد والمثانی (۲۶۵/۳، ۲۶۶) سنن کبریٰ (۱۰۲/۷) دلائل نبوۃ (۳۲۷/۵، ۳۲۸) مجمع الزوائد (۳۸۷/۹، ۳۸۸)\n(3) معجم الکبیر (۷۹۹۲)"}],[8632,"§۸۶۵۸ ۔ نافع بن سہل انصاری\nاشہلی، عمر بن شبہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: یمامہ میں شہید ہوئے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8633,"§۸۶۵۹ ۔ نافع بن ظریب(1)\nبن عمرو بن نوفل بن عبد مناف، نوفلی، عدوی کا قول ہے: مسلمانان فتح مکہ میں سے ہیں، یہ وہی ہیں جنہوں نے سیدنا عمر رضی اللہ عنہ کے لیے قرآن مجید لکھا۔ زبیر بن بکار(2) کا قول ہے: ظریب کے ہاں نافع کی ولادت ہوئی، ان کی والدہ صفیہ بنت عبد اللہ بن بجاد کنانیہ ہیں، وہ ام قتال، ام محمد بن جبیر بن مطعم کے والد ہیں، ان کی والدہ عقبہ بنت ابی رہاب ہیں، جن سے عقبہ بن حارث نے نکاح کیا، پھر اس حبشی خاتون کے اس کہنے کی وجہ سے جدائی اختیار کی کہ میں نے تم دونوں کو دودھ پلایا ہے، تو عقبہ نے ان سے جدائی اختیار کر لی، تو ان نافع نے اس سے نکاح کر لیا۔\nہشام بن کلبی کا قول ہے: وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے لیے قرآن پاک لکھا کرتے تھے۔ بلاذری کا قول ہے: انہوں نے سیدنا عثمان رضی اللہ عنہ کے لیے قرآن مجید لکھا، ایک قول ہے کہ سیدنا عمر رضی اللہ عنہ کے لیے قرآن پاک لکھے۔","",{"fn":"(1) اسد الغابہ (۵۱۸۴) استیعاب (۲۶۲۶) تجرید (۱۰۲/۲)\n(2) اسد الغابہ (۲۱۹/۴) جمہرہ (۱۱۶)"}],[8634,"§۸۶۶۰ ۔ نافع بن عبد حارث(1)\nبن حبالہ بن عمیر بن نبشان خزاعی، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ابو طفیل وغیرہ نے روایت کی، بخاری رحمہ اللہ کا قول ہے، بعض نے کہا: انہیں شرف صحابیت حاصل ہے۔ ابن سعد نے صحابہ رضی اللہ عنہم کے اس طبقہ میں ان کا ذکر کیا ہے جو فتح کے دن اسلام لائے۔(2) ابن عبد البر(3) کا قول ہے: کبار اور صاحب فضیلت صحابہ رضی اللہ عنہم میں سے ہیں۔ بعض کا قول ہے: فتح کے دن اسلام لائے اور مکہ میں فروش ہوئے اور ہجرت نہیں کی۔(4) واقدی نے انکار کیا ہے کہ انہیں شرف صحابیت حاصل ہو۔\nابن حبان، عسکری اور دوسرے لوگوں نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ سنن، مسند احمد(5) میں ان کی حدیث ہے: یہ انسان کی سعادت ہے کہ اس کا پڑوسی اچھا ہو۔\nابراہیم حربی کی روایت میں ہے: نافع بن حارث اس میں عبد نہیں ہے، صحیح یہ ہے کہ عبد موجود ہے۔ سیدنا عمر رضی اللہ عنہ نے انہیں مکہ کا امیر بنایا، بخاری رحمہ اللہ نے اپنی صحیح(6) میں فرمایا: نافع بن عبد حارث نے سیدنا عمر رضی اللہ عنہ کے لیے صفوان بن امیہ سے مکہ میں تیل خانہ خریدا۔","",{"fn":"(1) اسد الغابہ (۲۱۵/۴) استیعاب (۲۶۲۸) تجرید (۱۰۲/۲)\n(2) طبقات کبریٰ (۲۴۲/۳) (۴۶۲/۵)\n(3) استیعاب (۵۴/۴)\n(4) جامع المسانید والسنن (۹۷/۱۲) اسد الغابہ (۲۱۵/۴)\n(5) مسند احمد (۴۰۷/۳)\n(6) بخاری فی کتاب الخصومات ..."}],[8635,"§۸۶۶۱ ۔ نافع بن عبد عمرو\nبن عبد اللہ بن نضلہ بن عوف بن عبید بن عویج بن عدی بن کعب بن اخی بن معمر بن نضلہ، زبیر نے ذکر کیا ہے کہ ان کا بیٹا عبد اللہ حرہ کے دن شہید ہوا، اس کا تقاضا ہے کہ وہ مسلمانان فتح مکہ میں سے ہیں۔"],[8636,"§۸۶۶۲ ۔ نافع بن عبد القیس فہری\nعاص بن وائل کے ماں شریک بھائی ہیں۔ سیدنا عمرو بن العاص کے ساتھ فتح مکہ میں شریک تھے۔ جیسا کہ عبد الحکم نے فتوح میں ان کا ذکر کیا ہے۔ عمرو نے انہیں برقد کی طرف بھیجا، یہ ابو عمر کی شرط کے مطابق ہے۔ اس کا تقاضا ہے جو انہوں نے نقل کیا ہے کہ حجۃ الوداع کے موقع پر قریش کا ہر شخص موجود تھا، یہ قریشی ہیں، سیدنا عثمان رضی اللہ عنہ کی خلافت تک زندہ رہے، یہ شرط کے مطابق ہے۔ واللہ اعلم"],[8637,"§۸۶۶۳ ۔ نافع بن عتبہ(1)\nبن ابی وقاص بن زہرہ بن کلاب بن اخی بن سعد، مسلمانان فتح مکہ میں سے ہیں، جابر بن سمرہ نے ان کے حوالے سے نقل کیا ہے، وہ ان کے چچا زاد ہیں کہ ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھے، صحیح مسلم میں ان کی حدیث ہے۔(2)","",{"fn":"(1) استیعاب (۲۶۲) تجرید (۱۰۲/۲)\n(2) مسلم (۷۲۱۳)"}],[8638,"§۸۶۶۴ ۔ نافع بن عجیر(1)\nبن عبد یزید بن مطلب بن عبد مناف قرشی، رکانہ کے بھتیجے ہیں، بغوی رحمہ اللہ نے صحابہ میں ان کا ذکر کیا ہے اور بطریق محمد بن علی بن شافع، بحوالہ نافع بن عجیر بن عبد یزید نقل کیا ہے کہ انہوں نے اپنی زوجہ ہشیمہ کو طلاق بائنہ دی پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اللہ کی قسم! میں نے اس سے ایک طلاق کا ارادہ کیا تھا۔.... (الحدیث)(2)\nبغوی کا قول ہے: اس سند سے صرف یہ حدیث ہے۔\nمیں کہتا ہوں: اسے بحوالہ زعفرانی اور بحوالہ شافعی رحمہ اللہ(3) انہوں نے محمد کے حوالے سے نقل کیا ہے، ربیع نے ان کی مخالفت کی ہے، فرماتے ہیں: بحوالہ شافعی رحمہ اللہ اسے اسی طرح بطریق حمیدی، بحوالہ شافعی اس سند سے بحوالہ نافع نقل کیا ہے کہ رکانہ نے اپنی زوجہ ہشیمہ کو طلاق دے دی، زعفرانی نے اس قصے والے شخص اور ان کی زوجہ کے نام میں اختلاف کیا ہے۔ اسی طرح ابو داؤد نے بحوالہ ابو ثور اور ابن سراج آخر میں اور بحوالہ شافعی رحمہ اللہ اس سند سے اختلاف ہے، فرماتے ہیں: بحوالہ نافع بن عجیر بن رکانہ، اسی طرح اسے ابن قانع نے بطریق ابراہیم بن محمد مدنی، بحوالہ عبد اللہ بن علی بن سائب نقل کیا ہے، فرماتے ہیں: عن نافع بن عجیر، عن عمہ اور وہ رکانہ ہیں، بحوالہ نافع بن عجیر ایک اور حدیث مروی ہے، اس کا متن یہ ہے: علی میرا پسندیدہ اور میرا امین ہے۔ ابن حبان نے اسے نقل کیا ہے اور صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۷۹) تجرید (۱۰۲/۲)\n(2) ابوداؤد (۳۲۰۶) ترمذی (۱۱۷۷) حاکم مستدرک (۱۱۹/۲)\n(3) شافعی فی الأم (الحدیث: ۱۱۸/۵)"}],[8639,"§۸۶۶۵ ۔ نافع بن علقمہ(1)\nابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: شام میں فروش ہوئے ان کی کوئی حدیث نقل نہیں کی، ابن ابی حاتم نے ان کا ذکر کیا ہے، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا، فرماتے ہیں: میں نے اپنے والد کو کہتے ہوئے سنا: مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہو، ابو یعلی نے بطریق حسین بن واقد، بحوالہ حبیب بن ابی ثابت نقل کیا ہے کہ عبد الرحمن بن ابی لیلی نے ان سے بیان کیا، فرماتے ہیں کہ میں سیدنا عمر رضی اللہ عنہ کے ساتھ مکہ کی طرف نکلا تو ہمارے سامنے امیر مکہ نافع بن علقمہ آئے، وہ اپنے چچا نافع کے ہم نام تھے، سیدنا عمر رضی اللہ عنہ نے ان سے کہا: تم نے مکہ کا امیر کسے بنایا.... (الحدیث)\nیہ سند قوی ہے لیکن اس میں ان کے والد کے نام میں غلطی ہے، یہ قصہ نافع بن عبد الحارث کے بارے میں مشہور ہے، جیسا کہ ابھی گزر چکا ہے، مکہ کے امراء میں نافع بن علقمہ بھی ہیں جو خزاعی نہیں، نہ ہی انہوں نے سیدنا عمر رضی اللہ عنہ کا زمانہ پایا، چہ جائیکہ انہیں شرف صحابیت حاصل ہو، وہ نافع بن علقمہ بن صفوان بن محرث کنانی ہیں۔ عبد الملک بن مروان نے انہیں مکہ کا امیر بنایا تھا، ان کا ابان بن عثمان کے ساتھ قصہ ہے، زبیر بن بکار نے موفقات میں ان کا ذکر کیا ہے، وہ مروان کے ماموں ہیں جو عبد الملک کے والد ہیں کیونکہ ام مروان، وہ سیدنا عثمان کی والدہ آمنہ بنت علقمہ بن صفوان ہیں جن کا تذکرہ ہے، میں نے علقمہ کا صحابہ میں ذکر نہیں دیکھا گویا وہ اسلام لانے سے پہلے وفات پاگئے تو ان کے بیٹے نافع کو شرف صحابیت حاصل ہوگا، ہو سکتا نہ مکہ کے قریب تھے، حجاز میں کوئی ایسا باقی نہ رہا تھا جو اسلام نہ لایا ہو اور حجۃ الوداع میں شریک نہ ہوا ہو۔","",{"fn":"(1) اسد الغابہ (۵۸۰) استیعاب (۲۶۲۲) تجرید (۱۰۲/۲)"}],[8640,"§۸۶۶۶ ۔ نافع بن غیلان(1)\nبن سلمہ ثقفی، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر(2) نے صحابہ میں ان کا ذکر کیا ہے۔ ابن عساکر کا قول ہے، مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہے یا نہیں؟ انہوں نے ذکر کیا کہ وہ دومۃ الجندل میں شہید ہوئے۔\nمیں کہتا ہوں: یہ واقعہ ۱۳ھ کا ہے۔ اس کا تقاضا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں بالغ ہوں، پہلے گزر چکا ہے کہ حجۃ الوداع کے موقع پر قریش اور ثقیف سب اسلام لے آئے تھے اور حج میں شریک تھے، وہ صحابی ہیں، ان کے والد صحابہ میں مشہور ہیں۔\nابن ابی دنیا نے بطریق یعقوب بن داؤد ثقفی نقل کیا ہے، فرماتے ہیں: نافع بن غیلان بن سلمہ ثقفی سیدنا خالد بن ولید رضی اللہ عنہ کے ساتھ شہید ہوئے، ان کے والد نے ان پر انتہائی غم کا اظہار کیا اور یہ اشعار کہے:\n”میری آنکھ کو کیا ہوا، ایک گھڑی کے لیے بند نہیں ہوتی جوں ہی بند ہوتی ہے، اس میں ایک آنسو پھوٹ آتا ہے، اے نافع! اب ان گھڑ سواروں کا مقابلہ کون کرے گا جو پوری قوت اور نیزہ بازی سے حملہ آور ہوں گے، مجھ سے اگر ہو سکتا تو میں نافع کو جڑوں اور زبان کے درمیان رکھ لیتا۔“\nکہتے ہیں: ان کے بہت زیادہ رونے پر عتاب کیا گیا، انہوں نے کہا: مجھے رونے دو میرے آنسو ختم ہو جائیں، بعد میں ان سے کسی نے کہا: غیلان! تمہارے آنسو کہاں ہیں؟ وہ کہنے لگے: ہر چیز پرانی ہو جاتی ہے۔ اسی طرح یہ روایت زبیر نے بطریق عبد اللہ بن مصعب زبیری، انہوں نے اپنے والد سے باضافہ ان الفاظ کے نقل کی ہے: نافع بھی پرانا ہو گیا اور آنسو بھی پرانے ہو گئے اب قریب اس سے ملاقات ہوگی۔","",{"fn":"(1) اسد الغابہ (۵۱۸۳) استیعاب (۲۶۲۳) تجرید (۱۰۳/۲)\n(2) استیعاب (۵۵/۴)"}],[8641,"§۸۶۶۷ ۔ نافع بن کیسان ثقفی(1)\nابن سعد کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، دمشق میں فروش ہوئے، ابو نعیم نے صحابہ رضی اللہ عنہم میں بطریق صدقہ، بحوالہ نافع بن کیسان، انہوں نے اپنے والد سے نقل کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”عنقریب میری امت میرے بعد شراب پیئے گی، وہ اس کا دوسرا نام رکھ کر پیئیں گے، ان کے امراء، شراب نوشی میں ان کے مددگار ہوں گے۔“(2)\nابن عائذ نے بحوالہ ولید بن مسلم، انہوں نے اس شخص سے روایت کیا ہے، جس نے عبد الرحمن بن ربیعہ سے سنا، انہوں نے عبد الرحمن بن ایوب بن نافع سے، انہوں نے نافع سے، انہوں نے اپنے والد سے، انہوں نے اپنے دادا نافع بن کیسان سے، جو نبی کریم صلی اللہ علیہ وسلم کے ساتھی ہیں، مرفوع نقل کیا ہے: ”حضرت عیسیٰ ابن مریم دمشق کے مشرقی دروازے کے پاس اتریں گے۔“(3)\nاسے تمام نے اپنے فوائد میں بطریق ابن عائذ نقل کیا ہے، اور محمد بن وہب بن عطیہ نے بحوالہ عبد الرحمن بن زمعد انھی الفاظ میں ان کی پیروی کی ہے۔\nابن شاہین نے اپنے طریق سے اسے نقل کیا ہے، اسی طرح اسے موسیٰ بن عامر کے طریق سے بحوالہ ولید نقل کیا ہے۔ میں نے دمشق کے ایک شیخ سے مذاکرہ کیا، فرماتے ہیں: میں نے عبد الرحمن بن ربیعہ سے بحوالہ عبد الرحمن بن ایوب انھی الفاظ میں فرماتے ہوئے سنا، اسے ابن قانع نے دوسرے طریق سے بحوالہ ولید نقل کیا ہے کہ مجھے قریش کے ایک شیخ نے بتایا: میں نے اسے عبد الرحمن سے سنا، اسی طرح اسے صفوان بن صالح نے بحوالہ ولید نقل کیا ہے، اور ولید سے آگے اختلاف ہے، ہشام بن عمار، ان کے حوالے سے فرماتے ہیں کہ انہوں نے ابو ربیعہ سے بحوالہ نافع بن کیسان، انہوں نے اپنے والد سے سنا، اسی طرح ہشام بن خالد کا قول ہے جیسا کہ کیسان کے سوانح میں گزر چکا ہے، صفوان کا قول ہے.... موسیٰ بن عامر نے اسی طرح فرمایا۔","",{"fn":"(1) اسد الغابہ (۵۱۸۴) (۵۱۰/۴) استیعاب (۲۶۲۴) (۵۵/۴) تجرید (۱۰۳/۲)\n(2) کنز العمال (۱۳۱۷۵) مختصر تاریخ دمشق (۱۰۸/۲۶) جامع المسانید والسنن (۱۰۶/۱۲)\n(3) المعجم الکبیر (۴۴۰/۱۹) تاریخ کبیر (۲۳۲/۷) (۲۳۴/۷) جامع المسانید والسنن (۱۰۶/۱۲) اسد الغابہ (۲۱۲/۴) استیعاب (۵۵/۴)"}],[8642,"§۸۶۶۸ ۔ نافع بن مسعود غفاری\nابن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق جریر بن ایوب، بحوالہ شعبی، انہوں نے نافع بن مسعود غفاری سے نقل کیا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا.... پھر رمضان کی فضیلت کے بارے میں حدیث نقل کی، فرماتے ہیں: ان میں سے بعض نے فرمایا: بحوالہ جریر بن ایوب، عن شعبی، عن ابی مسعود غفاری۔"],[8643,"§۸۶۶۹ ۔ نافع جرشی(1)\nجعفر مستغفری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور بطریق عبد الرحمن بن بشیر دمشقی، بحوالہ نافع جرشی نقل کیا ہے کہ انہوں نے ان سے بیان کیا کہ جب نبی کریم صلی اللہ علیہ وسلم کو مبعوث کیا گیا، تو پہاڑ کی چوٹی پر کاہن رہتا تھا، لوگوں نے اسے بلایا، اور اس سے کہا: ہمیں اس شخص کا حال بتاؤ، تو وہ ان کی طرف اترا، اپنی کمان پر تکی لگائی، اپنی نگاہ کو آسمان کی طرف بلند کیا، پھر کودنے لگا اور کہنے لگا: اللہ تعالیٰ نے محمد (صلی اللہ علیہ وسلم) کو عزت بخشی ہے اور انہیں برگزیدہ کیا ہے، اور اے لوگو! تمہاری طرف مبعوث کیا ہے....(2) اور قصہ ذکر کیا۔\nیہ عبد الرحمن، ابو حاتم نے ذکر کیا ہے کہ انہوں نے بحوالہ ابن اسحاق منکر روایات نقل کی ہیں، بخاری رحمہ اللہ نے تاریخ نافع جرشی میں فرمایا: زہری رحمہ اللہ فرماتے ہیں: بحوالہ ابن کعب مولیٰ عثمان، ان کے حوالے سے نقل کیا ہے اور ان کا صحابی وغیرہ ہونا بیان نہیں کیا، اس کے سیاق سے ظاہر ہوتا ہے کہ ابن کعب وہ عبد اللہ بن کعب بن مالک انصاری نہیں بلکہ وہ دوسرے ہیں، مولیٰ عثمان، اسی طرح خطیب نے مشتبہ میں بطریق عبد الرحمن نقل کیا ہے سیاق میں فرمایا: عن عبد اللہ بن کعب مولیٰ عثمان، مجھ سے نافع جرشی نے روایت کیا۔","",{"fn":"(1) اسد الغابہ (۵۱۶۸) تجرید (۱۰۱/۲)\n(2) تاریخ کبیر (۸۴/۴) جامع المسانید والسنن (۱۱۳/۱۲) اسد الغابہ (۲۱۵/۴)"}],[8644,"§۸۶۷۰ ۔ نافع حبشی\nابرہہ کے سوانح میں ان کا ذکر گزر چکا ہے، وہ ان آٹھ آدمیوں میں سے ایک تھے جو حبشہ سے آئے اور اسلام لائے۔"],[8645,"§۸۶۷۱ ۔ نافع(1)\nمولی رسول اللہ صلی اللہ علیہ وسلم۔ ابن ابی حاتم نے بحوالہ اپنے والد فرمایا: انہیں شرف صحابیت حاصل ہے، اسلم بن سہل نے تاریخ واسط میں بطریق یزید بن ہارون، بحوالہ نافع مولی رسول اللہ صلی اللہ علیہ وسلم نقل کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جنت میں کوئی بوڑھا، بدکار، تکبر کرنے والا، اور اپنے اعمال کا اللہ پر احسان جتانے والا شخص داخل نہ ہوگا۔“(2)\nاسے بخاری رحمہ اللہ، مطین، حسن بن سفیان، بغوی، ابن ابی داؤد، ابن سکن، ابن شاہین، طبرانی، ابن مندہ نے بطریق ابو سعید اصبح، بحوالہ خالد بن امیہ نقل کیا ہے.... پھر انہی الفاظ میں حدیث ذکر کی لیکن اس میں تقدیم و تاخیر ہے۔ بغوی رحمہ اللہ کا قول ہے، مجھے معلوم نہیں کہ اس اسناد سے، اس حدیث کے علاوہ کوئی روایت مروی ہے۔\nاسے ابن قانع نے دوسرے طریق سے بحوالہ خالد بن امیہ نقل کیا ہے، فرماتے ہیں: میں نے نافع مولی رسول اللہ صلی اللہ علیہ وسلم کو دیکھا اور انہیں یہ کہتے ہوئے سنا کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے نافع! تمہیں میرے بعد فقر و فاقہ پہنچے گا تو لوگوں سے اپنا حال بیان کر دینا، وہ تم پر رحم کریں گے۔ فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”جنت میں بوڑھا زانی داخل نہیں ہوگا....“۔ (الحدیث) اس میں یہ اضافہ کیا ہے: ”نہ کثرت سے شراب پینے والا، نہ ہی اپنے والدین کی نافرمانی کرنے والا۔“ اس میں یہ قول ذکر نہیں کیا: ”نہ اپنے اعمال سے اللہ تعالیٰ پر احسان جتانے والا۔“","",{"fn":"(1) اسد الغابہ (۵۱۷۱) استیعاب (۲۶۱۶) تجرید (۱۰۲/۲)\n(2) مجمع الزوائد (۲۵۵/۶) تاریخ کبیر (۸۲/۴) جامع المسانید والسنن (۱۱۲/۱۲) استیعاب (۵۲/۴) اسد الغابہ (۲۱۷/۴)"}],[8646,"§۸۶۷۲ ۔ نافع رؤاسی(1)\nعلقمہ کے دادا ہیں، عمرو بن مالک رواسی کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) استیعاب (۲۶۲۵)"}],[8647,"§۸۶۷۳ ۔ نافع(1)\nابو طیبہ حجام، کنیتوں میں ان کا ذکر آئے گا، حدیث میں ان کا نام محمد بن سہل بن ابی خیثمہ ہے، بحوالہ محیصہ بن مسعود کہ ان کا ایک غلام پچھنے لگاتا تھا اسے نافع ابو طیبہ کہا جاتا تھا، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنی کمائی کے بارے میں سوال کرنے گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کے قریب نہ جاؤ“۔ اس نے دوبارہ پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس سے پانی پلانے والے اونٹوں کو چارا کھلاؤ تو اس کی اوجھ تک پہنچ جائے۔ اسے ابن سکن، ابن قانع نے بروایت لیث، بحوالہ یزید بن ابی حبیب، انہوں نے بحوالہ ابی صغیر انصاری، انہوں نے محمد بن سہل سے نقل کیا ہے۔ کنیتوں میں اس کا مزید ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۱۷۶) تجرید (۱۰۲/۲)"}],[8648,"§۸۶۷۴ ۔ نافع\nمولیٰ غیلان بن سلمی ثقفی، بزار، بغوی نے بطریق لہیعہ، بحوالہ غیلان بن سلمہ نقل کیا ہے کہ نافع، غیلان بن سلمہ کے غلام تھے۔ بھاگ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس چلے گئے اور غیلان مشرک تھا، پھر غیلان اسلام لائے، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی ولاء کو غیلان کے سپرد کر دیا، ابن سعد نے روایت کیا ہے۔"],[8649,"§۸۶۷۵ ۔ نافع(1)\nبے نسبت۔ بغوی رحمہ اللہ نے نافع بن حارث بن کلدہ کے سوانح میں ان کا ذکر کیا ہے۔ بظاہر یہ معلوم ہوتا ہے کہ وہ کوئی اور ہیں، ابن سعد کا قول ہے کہ ہم سے خلف بن خلیفہ نے بحوالہ ابان بن بشیر، انہوں نے اہل بصرہ کے شیخ سے نقل کیا ہے، فرماتے ہیں: ہم سے نافع نے نقل کیا کہ نبی کریم صلی اللہ علیہ وسلم چار سو سے زیادہ افراد کے ساتھ روانہ ہوئے یہاں تک کہ ہم لوگ ایک ایسی جگہ پر اترے جہاں پانی کا نام و نشان نہیں تھا، گلتا تھا لوگوں کو اس سے بڑی گرانی ہوئی، اتنے میں آپ صلی اللہ علیہ وسلم کی طرف ایک بکری چلتی ہوئی آئی، نافع فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے اس کا دودھ دوہا اور سارے لشکر کو سیراب کیا اور خود بھی پیا، پھر فرمانے لگے: نافع! تم اس بکری کے مالک ہو، مجھے نہیں لگتا تم اس کے مالک بنو، فرماتے ہیں: میں نے ایک لکڑی لے کر زمین میں گاڑی اور بکری مضبوطی سے باندھ دی، میں بھی سو گیا اور لوگ بھی سو گئے۔ جب میں بیدار ہوا تو کیا دیکھتا ہوں، رسی کھل پڑی ہے اور بکری ندارد، جس پر نبی صلی اللہ علیہ وسلم نے فرمایا: جو اسے لایا تھا وہی اسے لے گیا۔(2)\nاسے حاکم ابو احمد نے کنیتوں میں ابو الفضل میں سوانح میں جن کا نام مروی نہیں، نقل کیا ہے، پھر بطریق خلف بن خلیفہ بحوالہ ابو الفضل، انہوں نے نافع نامی شخص سے روایت کیا ہے۔ واسط آتے تھے، ان کی طویل عمر ہوئی یہاں تک کہ حجاج کے زمانے میں بھی تھے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے حوالے سے ایک حدیث ذکر کی.... پھر حدیث نقل کی۔\nاسے طبرانی نے نافع بے نسبت کے سوانح میں نقل کیا ہے، فرماتے ہیں ہم سے اسلم بن سہل نے بحوالہ خلف انہی الفاظ میں نقل کیا ہے، اسلم نے تاریخ واسط میں کہا: ابو الفضل کا نام شیخ ابان یوسف بن میمون ہے، اس میں انہوں نے درست نہیں کہا، کیونکہ انہوں نے گمان کیا ہے کہ وہ نافع مولی رسول اللہ صلی اللہ علیہ وسلم ہیں، جن کا ذکر گزر چکا ہے، وہ اس کے علاوہ ہیں، بہت سے راویوں نے ان میں فرق کیا ہے۔ ان میں حاکم ابو احمد بھی ہیں جیسا کہ میں نے ذکر کیا ہے، خلف بن خلیفہ سے آگے مذکورہ حدیث میں اختلاف ہے، اسے ابو کریب نے ان کے حوالے سے نقل کیا ہے اور سند میں ابان کا ذکر نہیں کیا، اسے عصمہ بن سلیمان نے بحوالہ خلف نقل کیا ہے، فرماتے ہیں: عن ابی ہاشم رمانی، عن نافع، انہیں شرف صحابیت حاصل ہے۔ اسے ابن سکن اور ابن قانع نے اپنے طریق سے نقل کیا ہے، اسی طرح ابن شاہین کا قول ہے، فرماتے ہیں: انہیں شرف صحابیت حاصل ہے۔","",{"fn":"(1) تجرید (۱۰۳/۲)\n(2) دلائل النبوۃ (۱۳۷/۶) البدایہ والنہایہ (۱۹/۶) طبقات کبریٰ (۱۹/۱) (۴۹/۷)"}],[8650,"§۸۶۷۶ ۔ نامیہ بن صفارہ ضبعی\nرفاعہ بن زید کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، زید بن حارثہ نے جذامیوں نے ساتھ ان کے اسلام لانے کے بعد جو کچھ کیا، اس وجہ سے وہ آئے، اموی نے اپنی روایت میں، بحوالہ ابن اسحاق ان کا نام لیا ہے، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8651,"§۸۶۷۷ ۔ نباش بن زرارہ(1)\nابن مندہ کا قول ہے: مغازی میں ان کا ذکر ہے، وہ نبی کریم صلی اللہ علیہ وسلم کے صحابی تھے، اسی طرح ان کا مختصر ذکر کیا ہے، ابو موسیٰ کا قول ہے: نباش بن زرارہ تمیمی، ابو ہالہ، مستغفری نے صحابہ رضی اللہ عنہم کے باب نون میں ان کا ذکر کیا ہے۔ ابن اثیر(2) نے ان کا تعاقب کیا ہے، اور ان کا نسب بیان کیا ہے۔ فرماتے ہیں: ابن زرارہ بن وقدان بن حبیب بن سلامہ بن عدی بن جروہ بن اسید بن عمرو بن تمیم، ابو ہالہ تمیمی، پھر فرمایا: مصعب زبیری کا قول ہے: وہ بنو عبد الدار کے حلیف ہیں، ابن اثیر کا قول ہے: ابو موسیٰ نے ابن مندہ پر اپنے استدراک میں ان کا ذکر کیا ہے، ابن مندہ نے ان کا ذکر کیا ہے، ان کے استدراک کی کوئی وجہ نہیں پھر یہ کہ انہیں شرف صحابیت حاصل نہیں، کیونکہ وہ نبوت سے پہلے تھے اور نبی کریم صلی اللہ علیہ وسلم سے پہلے خدیجہ رضی اللہ عنہا کے شوہر تھے، ان سے ان کے بیٹے ابو ہالہ ہوئے، زرارہ اور اس کے بیٹے کو شرف صحابیت حاصل نہیں۔\nرہا ان کا ابو موسیٰ کے قول کا تعاقب کرنا تو وہ قابل توجہ ہے کیونکہ ان کی کنیت نباش ہے، فرماتے ہیں: وہ تمیم ہیں، اور ان کا ابن مندہ کے قول کا تعاقب کرنے میں تردد ہے۔ کیونکہ انہوں نے ان کا نسب بیان نہیں کیا، احتمال ہے کہ یہ دوسرے ہیں، پھر ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے، جو کچھ مستغفری نے ذکر کیا ہے، انہوں نے اسے دلیل بنایا ہے، اور مستغفری کا حوالہ مصعب زبیری کی روایت ہے۔ کیونکہ وہ فرماتے ہیں: نباش بن زرارہ تمیمی ابو ہالہ، بنو عبد الدار کے حلیف ہیں، اور ہند بنت خدیجہ کے والد ہیں۔\nاس میں ایسی کوئی بات نہیں جو اس کے صحابی ہونے کی دلیل ہو کیونکہ انہوں نے نسب کی حیثیت سے بحث کی ہے، صحابی ہونے کی حیثیت سے بحث نہیں کی۔","",{"fn":"(1) تجرید (۱۰۳/۲)\n(2) اسد الغابہ (۲۲۲/۴)"}],[8652,"§۸۶۷۸ ۔ نبتل بن حارث\nبن قیس بن زید بن ضبیعہ بن زید بن مالک بن عوف بن عمرو بن عوف انصاری اوسی، ابو عبید قاسم بن سلام نے کتاب النسب میں ان کے بھائی ابو سفیان کے ساتھ ان کا ذکر کیا ہے، ابن کلبی نے، پھر بلاذری نے منافقین میں ان کا ذکر کیا ہے، احتمال ہے کہ ابو عبید کو معلوم ہوا ہو کہ انہوں نے توبہ کر لی ہے، محمد بن اسحاق نے سیرۃ النبوۃ میں ان کا ذکر کیا ہے کہ یہ آیت ﴿وَمِنْهُمُ الَّذِينَ يُؤْذُونَ النَّبِيَّ وَيَقُولُونَ هُوَ أُذُنٌ﴾(1) ان کے بارے میں نازل ہوئی، اس میں قصہ ہے.... سدی نے ان کا ذکر کیا ہے لیکن ان لوگوں نے ان میں ان کا نام نہیں لیا۔(2)","",{"fn":"(1) سورۃ التوبۃ الآیۃ (۶۱)\n(2) السیرۃ النبویۃ (۱۲۵/۲)"}],[8653,"§۸۶۷۹ ۔ نبہان انصاری(1)\nاسعد کے والد ہیں، ابن سکن نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی حدیث کا مخرج کوفیوں کے حوالے سے ہے۔ ہمیں اس طریق کے علاوہ معلوم نہیں پھر بطریق عمرو بن شمر، بحوالہ محمد بن سوقہ نقل کیا ہے کہ انہوں نے انصار کے ایک شخص سے سنا جنہیں اسعد بن نبہان کہا جاتا ہے، وہ فرماتے ہیں کہ مجھ سے میرے والد نے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو عشاء کی نماز کے لیے اذان دیتے ہوئے سنا تو جو کچھ اس نے کہا، آپ صلی اللہ علیہ وسلم نے اس کے جواب میں وہی الفاظ کہے۔ اسی طرح دارقطنی نے مؤتلف میں نقل کیا ہے۔\nاسے ابن قانع، ابن مندہ نے دوسرے طریق سے بحوالہ عمرو بن شمر نقل کیا ہے۔ عمرو بن شمر متروک راوی ہیں۔","",{"fn":"(1) تجرید (۱۰۳/۲)"}],[8654,"§۸۶۸۰ ۔ نبہان تمار\nمقاتل بن سلیمان نے اپنی تفسیر میں، بحوالہ ضحاک، انہوں نے سیدنا ابن عباس رضی اللہ عنہما سے اس آیت مبارکہ کی تفسیر میں فرمایا: ﴿وہ لوگ جو کوئی گناہ یا اپنی جانوں پر ظلم کر بیٹھتے ہیں (تو پھر متنبہ ہو کر) اللہ کا ذکر کرتے ہیں اور اپنے گناہوں کی بخشش مانگ لیتے ہیں....﴾(1) الآیۃ۔ فرماتے ہیں: وہ نبہان تمار ہیں، ان کے پاس حسین و جمیل عورت کھجور خریدنے آئی، انہوں نے اس کے سرینوں پر ہاتھ مارا، اس نے کہا: اللہ کی قسم! تم نے اپنے بھائی کی غیر موجودگی میں اس کی عزت کی حفاظت نہیں کی، نہ اپنی حاجت کو پہنچ سکے، وہ شرمندہ ہو گئے۔ پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے اور انہیں بتایا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”دیکھنا، کہیں وہ کسی غازی کی عورت نہ ہو“۔(2) وہ چلے گئے، اور تین دن روتے رہے، دن کو روزہ رکھتے اور رات کو قیام کرتے، تو اللہ تعالیٰ نے چوتھے دن یہ آیت نازل فرمائی۔ آپ صلی اللہ علیہ وسلم نے ان کی طرف پیغام بھیجا اور اس کی خبر دی۔ انہوں نے اللہ کی حمد و ثنا کی اور اللہ کا شکر ادا کیا، فرماتے ہیں: یا رسول اللہ! یہ میری توبہ ہے، میرا شکر کیسے قبول ہوگا؟ تو اللہ تعالیٰ نے یہ آیت نازل فرمائی ﴿دن کے دونوں اطراف میں نماز ادا کرو اور رات کے قریب، نیکیاں، برائیوں کو دور کر دیتی ہیں﴾(3)۔\nاسی طرح عبد الغنی بن سعید ثقفی نے اپنی تفسیر میں، بحوالہ ابن عباس رضی اللہ عنہما طویل حدیث نقل کی ہے۔\nمقاتل متروک راوی ہے، اور ضحاک نے سیدنا ابن عباس رضی اللہ عنہما سے نہیں سنا عبد الغنی اور موسیٰ دونوں فوت ہو گئے۔\nاس قصے کو ثعلبی، مہدوی، مکی، ماوردی نے اپنی تفسیر میں بغیر سند کے روایت کیا ہے۔ لیکن قتادہ نے اس کے بعض حصے کو مختصرا بیان کیا ہے۔\nاس قصے والے صحابی کا نام دوسری آیت کے شان نزول میں ابو زرعہ وغیرہ کی کتاب میں آیا ہے۔","",{"fn":"(1) سورۃ آل عمران الآیۃ (۱۳۵)\n(2) اسد الغابہ (۲۲۲/۴)\n(3) سورہ ہود الآیۃ (۱۱۴)"}],[8655,"§۸۶۸۱ ۔ نبہان (غیر منسوب)(1)\nوثیمہ نے کتاب الردۃ کے آخر میں فرمایا کہ ہم سے اسماعیل بن علبہ نے، بحوالہ ابراہیم نخعی نقل کیا ہے کہ نبہان اسلام سے مرتد ہو گئے۔ انہیں نبی کریم صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ صلی اللہ علیہ وسلم نے انہیں توبہ کی تلقین کی، وہ تائب ہو گئے تو آپ صلی اللہ علیہ وسلم نے انہیں چھوڑ دیا۔ پھر وہ اسلام سے مرتد ہو گئے، انہیں نبی کریم صلی اللہ علیہ وسلم کے پاس لایا گیا، آپ صلی اللہ علیہ وسلم نے انہیں توبہ کی تلقین کی، انہوں نے توبہ کر لی، تو آپ صلی اللہ علیہ وسلم نے انہیں چھوڑ دیا۔ آپ صلی اللہ علیہ وسلم نے انہیں تیسری یا چوتھی مرتبہ فرمایا: ”اے اللہ! مجھے نبہان پر قدرت دے کہ اس کی گردن میں کالی رسی ہو“۔ چنانچہ انہیں نبی کریم صلی اللہ علیہ وسلم کے پاس لایا گیا، ان کی گردن میں کالی رسی تھی، آپ صلی اللہ علیہ وسلم نے اسے قتل کرنے کا حکم دیا، جب وہ اسے لے کر چلے تو اس نے اپنے سر سے اس شخص کو اشارہ کیا جو اسے لے جا رہا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا: ”اس نے تمہیں کیا کہا؟“ اس نے کہا: کہ یہ مجھے کہتا ہے کہ میں مسلمان ہوں میں اَشْهَدُ اَنْ لَّا اِلٰهَ اِلَّا اللّٰهُ وَ اَشْهَدُ اَنَّ مُحَمَّدًا رَّسُوْلُ اللّٰهِ کہتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اسے چھوڑ دو“۔\nاس کا ایک اور موصول طریق ہے لیکن اس کی سند بہت ضعیف ہے، طبرانی نے اوسط میں محمد بن مرز بانی کے سوانح میں، بحوالہ انس فرمایا: نبہان تین مرتبہ مرتد ہو گئے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! مجھے نبہان پر قدرت دے کہ اس کی گردن میں سیاہ رسی ہو“۔(2) آپ صلی اللہ علیہ وسلم کی دعا اتنی جلدی قبول ہوئی اور اس کا اثر یوں ظاہر ہوا کہ نبہان گرفتار ہو گئے ان کی گردن میں سیاہ رسی تھی، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس لائے گئے، آپ صلی اللہ علیہ وسلم نے تلوار اپنے دائیں ہاتھ میں لی اور رسی اپنے بائیں ہاتھ میں تاکہ اسے قتل کریں تو انصار کے ایک شخص نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! اگر آپ اسے اپنے آپ سے دور کر دیں؟ تو آپ صلی اللہ علیہ وسلم نے تلوار ایک شخص کے سپرد کی اور فرمایا: ”جاؤ! اسے قتل کر دو“۔ فرماتے ہیں: وہ اسے لے کر چلے تو نبہان نے اور کہا: کیا تم ایسے شخص کو قتل کرتے ہو جو گواہی دیتا ہے کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ محمد اللہ کے رسول ہیں؟ تو انہوں نے چھوڑ دیا گیا۔ فرماتے ہیں: اس حدیث کو، بحوالہ طحمہ سوائے حکام بن سلم کے کسی نے روایت نہیں کیا۔","",{"fn":"(1) تجرید (۱۰۳/۲)\n(2) مجمع الزوائد (۲۶۲/۶) معجم الاوسط (۷۶۲۹)"}],[8656,"§۸۶۸۲ ۔ نبہان\nدوسرے ہیں، بے نسبت۔ حمص میں فروش ہوئے، ابن شاہین نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور، بحوالہ ابراہیم بن عبد اللہ زبیعی نقل کیا ہے کہ ہم سے محمد بن عبد الاعلیٰ نے، بحوالہ عمر بن نبہان، انہوں نے اپنے والد سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جس کے تین بچے حالت اسلام میں فوت ہو گئے ہوں، اللہ تعالیٰ اسے اپنی رحمت کے فضل سے جنت میں داخل کرے گا“۔(1) فرماتے ہیں: مجھ سے سیدنا ابو ہریرہ رضی اللہ عنہ ملے اور فرمایا: کیا تم وہی شخص ہو جس سے نبی کریم صلی اللہ علیہ وسلم نے بچوں کے بارے میں فرمایا؟ میں نے کہا: جی ہاں! مجھ سے فرمایا، جو کچھ مجھ سے فرمایا مجھے وہ حمص کے خزانوں سے زیادہ پسند ہے۔\nدوسرے راویوں نے، بحوالہ ابن جریج ان کی مخالفت کی ہے، فرماتے ہیں: عمر بن نبہان، بحوالہ ابو ثعلبہ اشجعی ان کے سوانح میں ان کا ذکر آئے گا۔","",{"fn":"(1) مسند احمد (۳۹۶/۶) معجم الکبیر (۲۲/۶۰۱) (۲۲/۹۵۷) مجمع الزوائد (۸/۳) جامع المسانید والسنن (۱۴/۱۲)"}],[8657,"§۸۶۸۳ ۔ نبیشہ الخیر الہذلی(1)\nابن عمرو بن عوف، بعض کا قول ہے: ابن عبد اللہ بن عمرو بن عوف بن حارث بن نضر بن محق بن ہذلی کے چچا زاد ہیں۔ ان کی کنیت ابو طریف ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی: ”ایام تشریق، کھانے اور پینے کے دن ہیں، یہ روایت صحیح مسلم(2) میں ہے۔ پیالے کا اپنے چاٹنے والے کے لیے استغفار کے بارے میں ان کی حدیث ہے، اسے ترمذی(3) نے نقل کیا ہے۔ دوسری حدیث عتیرہ کے بارے میں ہے۔ ایک اور حدیث قربانی کا گوشت تین دن کے بعد ذخیرہ کرنے کے بارے میں ہے، دونوں حدیثیں اصحاب سنن کے ہاں ہیں سوائے ترمذی کے، ان سے ابو ملیح ہذلی نے اور امام عاصم جدہ معلی بن اسد روایت کیا ہے، ابو عمر(4) کا قول ہے: بصرہ میں فروش ہوئے، بعض کا قول ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم کے پاس قیدی تھے، انہوں نے کہا: یا رسول اللہ! انہیں فدیہ لے کر آزاد کر دیں یا ان پر احسان کریں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے بہتر فیصلہ کیا تم نبیشہ الخیر ہو۔","",{"fn":"(1) استیعاب (۲۶۸۱)\n(2) مسلم (۲۶۷۲)\n(3) ترمذی (۱۸۰۴)\n(4) استیعاب (۸۵/۴)"}],[8658,"§۸۶۸۴ ۔ نبیشہ(1)\nدوسرے ہیں۔ یہ وہی ہیں جن کے بھائی نے ان کی طرف سے جواب دیا تھا، انہیں کہا گیا: پہلے اپنی طرف سے جواب دو پھر نبیشہ کی طرف سے جواب دینا۔ مشہور یہ ہے کہ ان کا نام بشر مرہ ہے، دارقطنی وغیرہ نے نبیشہ کے لفظ کے ساتھ حدیث نقل کی ہے، اس کی سند ضعیف ہے۔","",{"fn":"(1) اسد الغابہ (۵۱۹۲) تجرید (۱۰۴/۲)"}],[8659,"§۸۶۸۵ ۔ نبیط بن جابر(1)\nبن مالک بن عدی بن زید بن عدی بن عمرو بن مالک، ابن نجار انصاری۔ بغوی رحمہ اللہ نے ان کا ذکر کیا ہے اور فرمایا: ان سے مروی کوئی حدیث نہیں پھر ابن سعد نے کہا: اُحد میں شریک تھے، نبی کریم صلی اللہ علیہ وسلم نے فریدہ بنت اسعد بن زرارہ سے نکاح کر دیا۔ بیعت کرنے والی خواتین میں سے ہیں، ان کے ہاں عبد الملک، عبد اللہ، محمد، ابراہیم، زینب کی ولادت ہوئی۔ سیدہ زینب، انس بن مالک کی زوجہ ہیں، ابن ابی حاتم(2) کو اس میں خط ہوتا ہے، نبیط بن شریط کے سوانح میں فرماتے ہیں: وہ نبیط بن جابر، بنو مالک بن نجار سے ہیں، نبی کریم صلی اللہ علیہ وسلم نے فریدہ سے ان کا نکاح کر دیا، یہ عجیب بات ہے، ابن عبیط اشجعی کا نسب معروف ہے، ان کا نسب، مالک بن نجار کے نسب سے بالکل جمع نہیں ہوتا۔","",{"fn":"(1) اسد الغابہ (۵۱۹۳) استیعاب (۲۶۲۶) تجرید (۱۰۴/۲)\n(2) الجرح والتعدیل (۱۰۴/۲) (۵۰۵/۸)"}],[8660,"§۸۶۸۶ ۔ نبیط بن شریط(1)\nبن انس بن مالک بن بلال اشجعی، کوفہ میں فروش ہوئے، ان کے والد شریط کی حدیث میں ان کا ذکر ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اور سالم بن عبید سے روایت کی، ان سے ان کے بیٹے سلمہ، نعیم بن ابی ہند، اور ابو مالک اشجعی نے روایت کی۔\nابن ابی حاتم(2) کا قول ہے: انہیں شرف صحابیت حاصل ہے، نبی کریم صلی اللہ علیہ وسلم کے بعد ایک مدت تک زندہ رہے۔","",{"fn":"(1) استیعاب (۲۶۲۷)\n(2) الجرح والتعدیل (۵۰۶/۲)"}],[8661,"§۸۶۸۷ ۔ نبیہ بن حذیفہ(1)\nبن غانم بن عامر بن عبد اللہ بن عبید بن عویج بن عدی بن کعب بن لوی قرشی عدوی، ابو جہم بن حذیفہ کے بھائی ہیں، ابو عمر(2) نے ان کے بھائی کے سوانح میں ان کا ذکر کیا ہے، فرماتے ہیں: مجھے معلوم نہیں کہ انہیں دیدار حاصل ہے (یا نہیں)۔","",{"fn":"(1) اسد الغابہ (۵/۹۶)، استیعاب (۲۶۲۸) تجرید (۱۰۴/۲)\n(2) استیعاب (۵۶/۴)"}],[8662,"§۸۶۸۸ ۔ نبیہ بن صؤاب جہنی(1)\nان کے والد کا نام صؤاب، ان کی کنیت ابو عبد الرحمن ہے، نبی کریم صلی اللہ علیہ وسلم کے پاس وفد کے ساتھ آئے، فتح مصر میں شریک تھے، ان چار لوگوں میں سے ہیں جو مصر میں قبلہ کی طرف فروش ہوئے، ابن یونس نے ان کا ذکر کیا ہے اور بطریق یثیم بن عدی، بحوالہ نبیہ بن صؤاب نقل کیا ہے، انہیں شرف صحابیت حاصل ہے، فرماتے ہیں: حمیر سے ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ کے پاس ٹھہرا پھر فوت ہو گیا آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کا کوئی مسلمان وارث تلاش کرو“، وہ نہیں ملا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کی میراث قضاعہ کے کسی آدمی کے سپرد کر دو، تو وہ عبد اللہ بن انیس کے سپرد کی گئی، اس وقت وہ نسب میں ان کے قریب تھے۔\nابن یونس کا قول ہے: یہ حدیث منکر ہے، یثیم اس کے روایت کرنے میں متفرد ہے، وہ قابل اعتبار نہیں، عبد الرحمن نے بحوالہ یزید اس حدیث کے علاوہ بھی روایت کیا ہے۔\nاسے ابن مندہ نے بحوالہ ابن یونس تبصرہ کیے بغیر ذکر کیا ہے، اور ابن سعد نے، بحوالہ عبد الرحمن بن زیاد نقل کیا ہے، اور اس کے نسب میں اضافہ کیا ہے۔ اس ابو یثیم نے، بحوالہ یزید فرمایا: مجھ سے اس شخص نے بیان کیا جس نے نبیہ بن صؤاب سے سنا، وہ نبی کریم صلی اللہ علیہ وسلم کے صحابی ہیں.... پھر ان کا ذکر کیا(2) حربی نے بطریق یسار بن عبد الرحمن صدفی، بحوالہ عمر نقل کیا ہے کہ انہوں نے سورہ حج میں دو سجدے کیے۔\nابن یونس نے بطریق شجرہ بن عبد اللہ نقل کیا ہے کہ انہوں نے ابو عبد الرحمن نہدی کو فرماتے ہوئے سنا، انہوں نے سیدنا عمر رضی اللہ عنہ کے ساتھ سورہ حج میں دو سجدے کیے، خطیب نے موضح میں فرمایا: ابو عبد الرحمن(3) وہ نبیہ بن صؤاب ہیں، ان کے دوسرے شیخ ہیں انہیں نبیہ بن صؤاب کہا جاتا تھا، قسم ثالث میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۵۱۹۸) استیعاب (۲۶۲۹)، تجرید (۱۰۴/۲)\n(2) جامع المسانید والسنن (۱۲۲/۱۲)\n(3) الموضح (۴۲۹/۲)"}],[8663,"§۸۶۸۹ ۔ نبیہ بن عثمان(1)\nبن ربیعہ بن وہب بن حذیفہ بن جمح، قریشی جمحی۔ واقدی رحمہ اللہ نے حبشہ کی طرف دوسری مرتبہ ہجرت کرنے والوں میں ان کا ذکر کیا ہے، فرماتے ہیں: اسلام کے ابتدائی دور میں اسلام لائے۔(2)\nابن اسحاق رحمہ اللہ نے ان کا ذکر نہیں کیا، نہ ہی موسیٰ بن عقبہ، اور ابو معشر نے ان کا ذکر کیا ہے۔ بلاذری رحمہ اللہ نے ذکر کیا ہے کہ وہ سیدنا جعفر بن ابی طالب کے ساتھ کشتی میں سوار تھے۔","",{"fn":"(1) اسد الغابہ (۵۱۹۹) استیعاب (۲۶۳۰) تجرید (۱۰۴/۲)\n(2) السیرۃ النبویۃ (۴/۴)"}],[8664,"§۸۶۹۰ ۔ نبیہ بن وہب(1)\nبن عثمان بن ابی طلحہ عبدری، ان کے والد کے سوانح میں دیکھ لیا جائے۔","",{"fn":"(1) تجرید (۱۰۴/۲)"}],[8665,"§۸۶۹۱ ۔ نبیہ(1)\nبے نسبت۔ ابو عمر(2) کا قول ہے: مجھے ان کا اس سے زیادہ معلوم نہیں کہ نبی علیہ السلام کے موالی میں ان کا ذکر ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں خریدا اور انہیں آزاد کر دیا۔\nصاحب الجمہرہ نے ان کا ذکر کیا ہے۔ فرماتے ہیں: وہ سرداروں کی اولاد میں سے ہیں، ان کے لکھنے میں اختلاف ہے، بعض کا قول ہے: بقیر کے ساتھ ہے۔ بعض نے کہا: عظیم کے وزن پر ہے۔","",{"fn":"(1) استیعاب (۲۶۳۱)\n(2) استیعاب (۵۶/۴)"}],[8666,"§۸۶۹۲ ۔ نجف بن ابی صفرہ ازدی\nابو عبید القاسم بن سلام نے ذکر کیا ہے کہ وہ اپنے والد کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے ساتھ وفد میں آئے، وہ مشہور امیر مہلب کے بھائی ہیں، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[8667,"§۸۶۹۳ ۔ نجیح\nکلثوم بن ہدم کے غلام ہیں، عمرو بن شعبہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، اور بطریق عبد العزیز بن عمران، بحوالہ عبد الرحمن بن یزید بن جاریہ نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم جب کلثوم بن ہدم کے ہاں فروش ہوئے تو کلثوم نے اپنے غلام نجیح کو بلایا، نبی کریم صلی اللہ علیہ وسلم نے اس کے نام سے اچھا فال لے کر فرمایا: اے ابو بکر! تو نے نجات پائی۔\nاسی طرح اس قصے کو ابو سعید نیشا پوری نے شرف المصطفیٰ میں نقل کیا ہے۔ اسے محمد بن حسن مخزومی نے اخبار مدینہ میں، بحوالہ اسحاق بن ابراہیم بن حارث عن ابیہ نقل کیا ہے۔"],[8668,"§۸۶۹۴ ۔ نجام عدوی\nوہ نعیم بن عبد اللہ ہیں، نعیم میں ان کا ذکر آئے گا۔"],[8669,"§۸۶۹۵ ۔ نذیر غسانی(1)\nابو مریم، اپنی کنیت سے مشہور ہیں۔ طبرانی(2) نے بطریق بقیہ نقل کیا ہے کہ ہم سے ابو بکر بن عبد اللہ بن ابی مریم غسانی نے بحوالہ اپنے والد، انہوں نے اپنے دادا سے نقل کیا ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جہاد کیا۔ آپ صلی اللہ علیہ وسلم نے مجھے جھنڈا عطا فرمایا۔ میں نے آپ صلی اللہ علیہ وسلم کے سامنے چٹان پر کھڑے ہو کر تیر اندازی کی، آپ صلی اللہ علیہ وسلم اس سے بہت خوش ہوئے اور میرے لیے دعا کی۔\nابو حاتم رازی(3) کا قول ہے: بعض شامیوں نے ابو مریم کے نام کے بارے میں پوچھا، انہوں نے کہا: نذیر، بعض کا قول ہے: ان کا نام بکیر ہے، جیسا کہ گزر چکا ہے۔ کنیتوں میں ان کا ذکر آئے گا۔","",{"fn":"(1) تجرید (۱۰۵/۲)\n(2) المعجم الکبیر (۲۲/۸۳۳)\n(3) الجرح والتعدیل (۴۳۶/۹)"}],[8670,"§۸۶۹۶ ۔ نذیر سدوسى\nوہ ابن خصاصیہ ہیں، پہلے ان کا نام نذیر تھا، آپ صلی اللہ علیہ وسلم نے ان کا نام بشیر رکھا۔"],[8671,"§۸۶۹۷ ۔ نزال بن سبرہ(1)\nبذلی کوفی، ابو مسعود مشقی نے اطراف میں فرمایا، اور حمیدی نے ان کی پیروی کی ہے، پھر ابن عساکر اور مزى نے فرمایا: انہیں شرف صحابیت حاصل ہے، مزى کا قول ہے: ان کے صحابی ہونے میں اختلاف ہے، مشہور ہے کہ وہ مخضرمی ہیں جیسا کہ قسم ثالث میں آ رہا ہے، مسلم، ابن سعد، دارقطنی اور حاکم نے یقین کیا ہے کہ وہ تابعی ہیں جیسا کہ مبسوط میں آئے گا۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۵۲۰۲)، تجرید (۱۰۵/۲)"}],[8672,"§۸۶۹۸ ۔ نزیل\nمنحالی، بزیل میں ان کا ذکر گزر چکا ہے، امیر ابن ماکولا(1) نے نون اور زاء کے ساتھ قلمبند کیا ہے۔","",{"fn":"(1) الاکمال (۵۶/۱)"}],[8673,"§۸۶۹۹ ۔ نسطاس\nمولی سعد بن عبادہ خزرجی، دارقطنی رحمہ اللہ کی کتاب الاخیاء میں ان کا ذکر ہے، انہوں نے بطریق ابن وہب، بحوالہ یحییٰ بن عبد العزیز نقل کیا ہے۔ فرماتے ہیں: ایک سال سیدنا سعد بن عبادہ جہاد کرتے تھے اور ایک سال ان کے بیٹے قیس بن سعد جہاد کرتے تھے، سیدنا سعد نے لوگوں کے ساتھ جہاد کیا، رسول اللہ صلی اللہ علیہ وسلم کے پاس بہت سے مسلمان بطور مہمان آئے، سیدنا سعد رضی اللہ عنہ کو یہ بات معلوم ہوئی تو وہ اس لشکر میں تھے، انہوں نے کہا: اگر میرا بیٹا قیس ہوتا تو کہتا: اے نسطاس! چا پیاں لاؤ۔ اور رسول اللہ صلی اللہ علیہ وسلم کی ضرورت کی چیزیں نکالو، تو نسطاس کہتا: اپنے والد سے تحریر لاؤ، تو وہ اس کی ناک توڑ کر چا پیاں لے لیتا اور رسول اللہ صلی اللہ علیہ وسلم کی ضرورت کی اشیاء نکال لیتا، اسی طرح ہی ہوا، سیدنا قیس نے رسول اللہ صلی اللہ علیہ وسلم کے لیے سونے کے لیے۔"],[8674,"§۸۷۰۰ ۔ نسطاس، مولی صفوان بن امیہ\nحجمی، مشرکین کے ساتھ اُحد میں شریک تھے پھر اسلام لائے اور ان کا اسلام سنور گیا، وہ احد کے دن کے بارے میں بیان کرتے ہیں، فرماتے ہیں: میں ان لوگوں میں سے تھا جو لشکر سے پیچھے تھے، اس دن غلاموں میں سے وحشی اور صواب جو بنو عبد الدار کا غلام تھا، اس کے علاوہ کسی نے جنگ میں حصہ نہیں لیا، فرماتے ہیں: کچھ دیر لڑائی جاری رہی پھر ہمارے ساتھی شکست کھا کر واپس آ گئے اور نبی کریم صلی اللہ علیہ وسلم کے ساتھی ہمارے لشکر میں داخل ہو گئے، ہم اس وقت خیموں میں تھے۔ مجھے بھی قیدی بنا لیا گیا، لشکر میں بڑی لوٹ مار ہوئی، ہم اسی حال میں تھے کہ میں نے گھوڑوں کو آتے دیکھا.... پھر ایک قصہ ذکر کیا، یہ واقدی(1) نے ذکر کیا ہے، اس میں ہے: میں نے مسلمانوں میں سے ایک شخص کو دیکھا کہ اس نے صفوان بن امیہ کو پکڑے ہوا تھا، یہاں تک کہ میں نے گمان کیا کہ وہ مر جائے گا، جب میں اس تک پہنچا تو اس میں تھوڑی سی رمق باقی تھی، میں اس کے پاس آیا اور اپنے خنجر سے اس پر وار کیا، اس کے بعد میں نے اس کے بارے میں لوگوں سے پوچھا، انہوں نے کہا: بنو ساعدہ کا ایک شخص ہے، پھر اللہ تعالیٰ نے مجھے اسلام کی ہدایت دی، ابن اسحاق(2) نے ذکر کیا ہے کہ نسطاس مذکورہ شخص ہے جو خبیب بن عدی کے ساتھی زید بن دثنہ کے قتل پر مامور ہوا تھا۔","",{"fn":"(1) مغازی (۲۲۰)\n(2) السیرۃ النبویۃ (۱۳۶/۳)"}],[8675,"§۸۷۰۱ ۔ نسیر(1)\nتفخیر کے ساتھ ہے، ابن عنبس بن زید بن عامر انصاری ظفری، ابو سعد نے شرف مصطفیٰ میں ان کا ذکر کیا ہے، موحدہ میں گزر چکا ہے، اس میں اختلاف کا ذکر کیا، اس میں یہ اضافہ ہے کہ خطیب نے مؤتلف میں نون کے ساتھ ان کا ذکر کیا ہے، ابن عمارہ بن قداح کے ہاں ان کا نسب بیان ہوا ہے، فرماتے ہیں: عنبس بن زید بن عامر بن سواد بن کعب ابن خزرج بن عمرو بن مالک بن اوس۔","",{"fn":"(1) اسد الغابہ (۵۲۰۳)، تجرید (۱۰۵/۲)"}],[8676,"§۸۷۰۲ ۔ نسیر بن عنبس\nانہیں شرف صحابیت حاصل ہے، بہت سی جنگوں میں شریک ہوئے، ان کے والد عنبس کو فارس الجواء کہا جاتا تھا۔ نسیر بن جرابی عبید کے دن شہید ہوئے، ان کے پوتے عبد اللہ بن سہل بن نسیر قادسیہ میں شہید ہوئے۔\nمیں کہتا ہوں: میں نے ان کے پوتے عبد اللہ کا ذکر پہلے کر دیا ہے۔"],[8677,"§۸۷۰۳ ۔ نسیر بن یحیی انصاری\nمولی عثمان بن حنیف، تیسری قسم میں ان کا ذکر آئے گا۔"],[8678,"§۸۷۰۴ ۔ نشیط بن مسعود\nبن امیہ بن خلف تجی، ابو غلیط، اپنی کنیت سے مشہور ہیں، ان کے نام میں اختلاف ہے، کنیتوں میں ان کا ذکر آئے گا۔"],[8679,"§۸۷۰۵ ۔ نصر بن حارث(1)\nبن عبد یزاح بن کعب انصاری ظفری، تمام اقوال کے مطابق بدر میں شریک ہوئے، ہشام بن کلبی نے ان کا ذکر کیا ہے، ابو معشر، ابن عمارہ، اور واقدی نے صاد کے ساتھ ان کا ذکر کیا ہے، ابن قداح نے ضاد کے ساتھ اس کا ذکر کیا ہے، ابن ماکولا(2) نے خطیب کی پیروی میں اسے درست قرار دیا ہے، ابن اسحاق(3) نے نون مضمومہ، اس کے بعد میم کے ساتھ اس کا ذکر کیا ہے، ابن سعد(4) نے ذکر کیا ہے: ان سے روایت کرنے والوں کی غلطی ہے، ان کے بیٹے حارث بن نضر کا ذکر حرف حاء میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۰۴)، استیعاب (۲۶۳۳)، تجرید (۱۰۵/۲)\n(2) اکمال (۲۹۴/۲)\n(3) السیرۃ النبویۃ (۲۴۹/۲)\n(4) طبقات الکبریٰ (۴۵۴/۳)"}],[8680,"§۸۷۰۶ ۔ نصر بن حزن\nعبدہ بن حزن میں ان کا ذکر گزر چکا ہے۔"],[8681,"§۸۷۰۷ ۔ نصر بن دہر(1)\nبن اخرم بن مالک اسلمی، ان کے والد کا پہلی قسم میں ذکر گزر چکا ہے۔ بخاری رحمہ اللہ کا قول ہے: انہیں شرف صحابیت حاصل ہے، بغوی کا قول ہے: مدینہ میں فروش ہوئے، ان سے دو حدیثیں مروی ہیں، نسائی(2) نے ان کے بیٹے ابو ہشیم کی ماعز کے قصے میں ایک حدیث نقل کی ہے، جو ان سے مروی ہے، اور اس کی سند جید ہے، ان کی ایک حدیث خیبر کے دن سیدنا عامر بن اکوع کے قصے کے بارے میں ہے، اسے ابن ابی عاصم(3) نے نقل کیا ہے۔\nابن عبد البر کا قول ہے: عبد اللہ بن ہشیم بن نصر نے احادیث روایت کیں وہ ان کے حوالے سے انہیں نقل کرنے میں متفرد ہیں۔","",{"fn":"(1) اسد الغابہ (۵۲۰۶)، استیعاب (۲۶۳۴)\n(2) نسائی (۸/۹)\n(3) الآحاد والمثانی (۳۴۶/۴)"}],[8682,"§۸۷۰۸ ۔ نصر بن غانم(1)\nبن عامر بن عبد اللہ بن عبید بن عویج بن عدی بن کعب عدوی، زبیر بن بکار نے نسب میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ اور ان کا بیٹا طاعون عمواس ۱۸ھ میں وفات پا گئے۔","",{"fn":"(1) استیعاب (۲۶۳)، تجرید (۱۰۵/۲)"}],[8683,"§۸۷۰۹ ۔ نصر بن وہب خزاعی\nابن سکن اور ابن قانع نے صحابہ میں ان کا ذکر کیا ہے، دونوں نے بطریق عبد اللہ بن ابی حمید، بحوالہ ابی ملیح ہذلی نقل کیا ہے کہ مجھ سے نصر بن وہب خزاعی نے حدیث بیان کی کہ نبی کریم صلی اللہ علیہ وسلم گدھے پر بغیر زین سوار ہوئے، اس پر چادر پڑی ہوئی تھی، سیدنا معاذ بن جبل رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے پیچھے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم جانتے ہو اللہ کا بندوں پر کیا حق ہے؟ الحدیث(1)۔\nاسے ابن مندہ اور ابو نعیم نے اس طریق سے نقل کیا ہے۔","",{"fn":"(1) بخاری (۵۹۶۷)، مسلم (۱۴۳)، مسند احمد (۲۶۰/۳)"}],[8684,"§۸۷۱۰ ۔ نصر سلمی\nابن حزم نے وحدان میں مندبقی بن محمد سے ان کی ایک حدیث نقل کی ہے، احتمال ہے کہ وہ نصر بن دہر ہوں جن کا ذکر گزر چکا ہے۔"],[8685,"§۸۷۱۱ ۔ نصرہ بن اکثم\nان کا ذکر گزر چکا ہے، ان کے نام کے پہلے حرف میں اختلاف ہے۔"],[8686,"§۸۷۱۲ ۔ نصیب غنوی\nان کے مولیٰ، ابو نعیم نے ایک حدیث میں ان کا ذکر کیا ہے جو بطریق ابو سفیان غنوی، بحوالہ سراء بنت نبہان مروی ہے، وہ جاہلیت میں گھر کی مالکن تھیں، فرماتی ہیں: ہمارے مولا نصیب نے رسول اللہ صلی اللہ علیہ وسلم سے سانپوں کے بارے میں سوال کیا کہ ہم ان میں سے کن کو ماریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو تمہارے سامنے ظاہر ہوں انہیں قتل کرو، جس نے انہیں مارا گویا اس نے کافر کو قتل کیا ہے، اور ان میں سے جس نے تم میں سے کسی کو مارا تو وہ شہید ہوگا“۔(1)","",{"fn":"(1) المعجم الکبیر (۲۴/۷۷۹)، مجمع الزوائد (۴۵/۴)"}],[8687,"§۸۷۱۳ ۔ نصیر(1)\nتصغیر کے ساتھ ہے، مطین نے ان کا ذکر کیا ہے اور بطریق ثور بن زید، بحوالہ نصیر نقل کیا ہے: رسول اللہ صلی اللہ علیہ وسلم نے ضرار کی تقسیم سے منع فرمایا ہے۔ بغوی(2) کا قول ہے: مجھے معلوم نہیں کہ انہیں شرف صحابیت حاصل ہے یا نہیں۔","",{"fn":"(1) تجرید (۱۰۶/۲)\n(2) جامع المسانید والسنن (۱۳۱/۱۲)، اسد الغابہ (۲۲۸/۴)"}],[8688,"§۸۷۱۴ ۔ النضر بن حارث(1)\nبن علقمہ بن کلدہ بن عبد الدار قرشی عبدری: ابن ابی حاتم کا قول ہے: نضر بن حارث، بعض کا قول ہے: نضیر، مسلمان فتح مکہ میں سے ہیں۔ ان سے کوئی روایت مروی نہیں، اسی طرح ابن مندہ نے بطریق شیث بن حارث بن ابی زائدہ، بحوالہ ابن اسحاق،(2) انہوں نے عاصم بن عمر بن قتادہ سے، انہوں نے محمود بن لبید سے، انہوں نے ابو سعید سے نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم جب طائف سے آئے تو ھم انڈ اترے اور نضر بن حارث کو سواونٹ دیے۔\nابن اثیر(3) نے اس شخص پر تنکیر کی ہے، جس نے نضیر بن حارث کا عنوان قائم کیا ہے، فرماتے ہیں: نضر حالت کفر میں قتل ہوا، اس پر اہل سیر کا اجماع ہے اور اس احتمال کی وجہ سے تعاقب کیا ہے کہ اس کا کوئی اور بھائی ہو جو اس کا ہم نام ہو یا ان دونوں میں سے ایک کے نام میں یا کا اضافہ ہے، ان کا ایک اور بھائی ہے۔ جس کا نام ان کے والد کے نام پر حارث رکھا گیا، زیاد بکائی نے، بحوالہ ابن اسحاق ان کا ذکر کیا ہے، ان کا ذکر گزر چکا ہے۔\nجس نے یہ دلیل بنائی ہے کہ موسیٰ بن عقبہ نے ذکر کیا ہے کہ نضیر بن حارث نے حبشہ کی طرف ہجرت کی، صاحب عنوان کے بارے میں تحدثین کا یہ بیان ہے کہ یہ فتح مکہ کے مسلمانوں میں سے ہیں۔\nاس کا مزید ذکر نضیر کے سوانح میں آئے گا ان شاء اللہ تعالیٰ۔\nبلاذری نے، بحوالہ ہشیم بن عدی ان کا ذکر کیا ہے، فرماتے ہیں: نضیر بن حارث نے حبشہ کی طرف ہجرت کی پھر مکہ آئے اور مرتد ہو گئے پھر فتح مکہ کے دن یا اس کے بعد اسلام لائے اور یرموک میں شہید ہو گئے اس سے دونوں اقوال کو جمع کیا جا سکتا ہے کہ وہ ایک ہیں۔ واللہ اعلم۔","",{"fn":"(1) اسد الغابہ (۵۲۱۲) تجرید (۱۰۶/۲)\n(2) السیرۃ النبویۃ (۱۰۷/۴)\n(3) اسد الغابہ (۳۳۶/۴)"}],[8689,"§۸۷۱۵ ۔ نضر بن سلمہ ہذلی(1)\nابن مندہ نے ان کا ذکر کیا ہے اور بطریق سلمہ بن سلمہ بن نجیب، بحوالہ ان کے والد نقل کیا ہے کہ انہوں نے ابو عبد اللہ قراط سے سنا کہ وہ بحوالہ نضیر بن سلمہ ہذلی بیان کر رہے تھے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے فرماتے ہوئے سنا: ”اگر لوگ عشاء اور صبح کی نماز باجماعت کی فضیلت جان لیں تو ضرور آئیں اگرچہ گھٹنوں کے بل آنا پڑے“۔(2)","",{"fn":"(1) اسد الغابہ (۵۲۱۱)\n(2) ابن ماجہ (۷۹۶)، مسند احمد (۵۷۵۲)، اسد الغابہ (۲۲۹/۴)"}],[8690,"§۸۷۱۶ ۔ نضرہ بن اکثم(1)\nبن ابی جون خزاعی، ابن کلبی نے ان کا ذکر کیا ہے، فرماتے ہیں: وہ معبد کے بھائی ہیں، ان دونوں کی والدہ ام معبد بنت خالد ہیں، جن کے ہاں رسول اللہ صلی اللہ علیہ وسلم ہجرت کے وقت ٹھہرے تھے، وہ نضرہ بن اکثم کے علاوہ ہیں حرف باء میں جن کا ذکر گزر چکا ہے، اگرچہ ابو عمر نے ان دونوں کو ملا دیا ہے، اور وہ جو حرف باء میں جن کا ذکر ہے، میرے خیال میں وہ انصاری ہیں۔","",{"fn":"(1) اسد الغابہ (۵۲/۵)، تجرید (۱۰۶/۲)"}],[8691,"§۸۷۱۷ ۔ نضرہ بن خدیج جشمی\nسعید بن عبد الرحمن کی روایت میں، بحوالہ سفیان بن عیینہ ان کے جامع میں ان کا ذکر ہے، انہوں نے ابی زعراء سے، انہوں نے ابو احوص سے ذکر کیا ہے، ان کا نام عوف بن مالک بن نضلہ ہے: کہ ان کے والد نبی کریم صلی اللہ علیہ وسلم کے پاس آئے مرہ۔ بحوالہ ابو احوص وہ اپنے دادا سے نقل کرتے ہیں، فرماتے ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے پاس آیا، آپ صلی اللہ علیہ وسلم نے مجھے اوپر سے نیچے تک دیکھا پھر سر جھکا لیا اور فرمایا: ”کیا تم اونٹوں کے مالک ہو یا بکریوں کے؟“۔(1) الحدیث\nیہ حدیث ابو احوص کے والد کے لیے معروف ہے وہ مالک بن نضلہ ہیں، ان کی حدیث بخاری کے ہاں کتاب الادب میں بطریق ابو احوص ہے، اسی طرح وہ اصحاب السنن الاربعہ کے ہاں ہیں، اسے امام احمد نے بھی، بحوالہ سفیان نقل کیا ہے۔","",{"fn":"(1) مسند احمد (۱۳۶/۴)، المعجم الکبیر (۱۹/۶۲۲)، جامع المسانید والسنن (۱۳۴/۱۲)"}],[8692,"§۸۷۱۸ ۔ نضلہ بن طریف(1)\nبن نہصل حر مازی، ابن ابی عاصم نے ان کا ذکر کیا ہے، بغوی، ابن سکن نے بھی بطریق جنید بن امین بن ذرہ بن نضلہ بن طریف بن نہصل حر مازی عن ابیہ، عن جدہ نضلہ ان کا ذکر کیا ہے، بغوی کی روایت میں ہے: مجھ سے میرے والد امین نے بیان کیا کہ مجھ سے ابو ذرہ نے، بحوالہ ابی نضلہ، انہوں نے ان میں سے ایک شخص سے نقل کیا ہے، جنہیں اعشیٰ کہا جاتا تھا، ان کا نام عبد اللہ بن اعور تھا، ان کے پاس انہی میں سے ایک عورت تھی، اس کا نام معاذہ تھا، ایک دن وہ حجر سے اپنے گھر والوں کے لیے غلہ لینے گئے، تو ان کی بیوی بھاگ گئی اور ان کی نافرمان ہو گئی، اس نے مطرف بن نہصل نامی ایک شخص سے پناہ مانگی وہ ان کے پاس گئے اور کہا: اے چچا زاد! تمہارے پاس میری بیوی ہے۔ اسے مجھے واپس لوٹا دو، اس نے کہا: میرے پاس نہیں ہے، اگر میرے پاس ہوتی تو میں تمہیں واپس نہ لوٹاتا، مطرف ان سے زیادہ غالب تھے، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے پناہ لی اور یہ اشعار کہے:\n”اے لوگوں کے بادشاہ اور عرب کے دیانت دار، میں آپ سے اپنی مصیبت کی شکایت کرتا ہوں، جسے بھوکی بھیڑیں بھٹ کے سائے میں ہو، میں رجب میں اس کے لیے غلہ لینے نکلا، تو وہ مجھ سے جنگ و جدل کرنے لگی، اس نے عہد توڑ دیا اور دم دبا لی، اور مجھے نسب والے پیچھے میں اتار دیا، وہ بری غالب آنے والی ہیں جس پر غالب آ جائیں۔\nتو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”وہ بری غالب آنے والی ہیں جس پر غالب آ جائیں“۔ پھر نبی کریم صلی اللہ علیہ وسلم نے مطرف بن نہصل کو خط لکھا: ”اس عورت معاذہ کو تلاش کرو اور ان کے سپرد کر دو“۔ جب انہیں خط پڑھ کر سنایا گیا تو انہوں نے کہا: اے معاذہ! یہ رسول اللہ صلی اللہ علیہ وسلم کا تیرے بارے میں خط ہے، میں تمہیں ان کے سپرد کر دوں گا، اس نے کہا: میرے لیے عہد و میثاق اور نبی کریم صلی اللہ علیہ وسلم کا ذمہ لیں کہ وہ میرے فعل کی مجھے سزا نہیں دیں گے، انہوں نے ان کے لیے عہد و ذمہ لے لیا۔ اور انہیں ان کے سپرد کر دیا، انہوں نے اس کے بارے میں یہ شعر کہا:\n”تیری عمر کی قسم! معاذہ سے میری محبت ایسی نہیں کہ کسی چغل خور یا زمانے کی دوری تبدیل کر دے“۔(2)","",{"fn":"(1) اسد الغابہ (۵۲۱۸)، استیعاب (۲۶۳۷)، تجرید (۱۰۶/۲)\n(2) مسند احمد (۲۰۲/۲)، الآحاد والمثانی (۲/۴۲۲)، استیعاب (۵۸/۳)، اسد الغابہ (۲۳۱/۴)"}],[8693,"§۸۷۱۹ ۔ نضلہ بن عبید اسلمی(1)\nابو برزہ، اپنی کنیت سے مشہور ہیں، کنیتوں میں ان کا ذکر آئے گا، ابن درید کا قول ہے: نضلہ بن عبد اللہ، یہ وہی شخص ہیں جس نے بلال بن حظل کو قتل کر دیا، شاید ان کا نام عبد اللہ تھا اور انہیں عبید کہا جاتا تھا، ابن شاہین کا قول ہے: ابو برزہ نضلہ بن عبید، پھر بطریق احمد بن سیار مروزی نقل کیا: ابو برزہ اسلمی ان کا نام عبد اللہ بن نضلہ بن عبید بن حارث بن حبال بن ربیعہ بن دعبل بن انس بن جذیمہ بن مالک بن سلامان بن اسلم بن افصی ہے۔ مرو میں فروش ہوئے اور وہیں وفات پا گئے، مقبرہ کلا باز میں دفن ہوئے، مرو میں ان کی اولاد ہے، بعض کا قول ہے: بصرہ میں وفات پائی، بعض کا قول ہے: بستان اور دھرات کے صحرا میں وفات پائی۔\nحاکم کی تاریخ نیشا پور میں ہے: بعض کا قول ہے: ان کا نام نضلہ بن عبید ہے، پھر عباس بن مصعب تک اپنی سند سے بیان کیا ہے، فرماتے ہیں: مجھ سے محمد بن مالک بن یزید بن ابی برزہ اسلمی نے نقل کیا ہے، فرماتے ہیں: ابی برزہ اسلمی کا نام نضلہ بن نیار تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام عبد اللہ رکھا اور فرمایا: ”نیار شیطان ہے“۔ وہ نیار بن حبال بن ربیعہ ہیں، پھر ان کا نسب بیان کیا، جیسا کہ گزر چکا ہے، لیکن دعبل اور انس کے درمیان عبدان کا اضافہ کیا۔\nپھر ابن شاہین نے، بحوالہ ابی نعیم نقل کیا ہے کہ وہ نضلہ بن عبد اللہ ہیں۔ احمد اور ابن معین: نضلہ بن عبید، وہ اکثر کا قول ہے، ابن سعد نے، بحوالہ یثیم بن عدی نقل کیا ہے کہ وہ خالد بن نضلہ ہیں اور، بحوالہ واقدی منقول ہے: راوی کہتے ہیں کہ ان کے بیٹے کا نام عبد اللہ بن نضلہ ہے، وہ اپنی کنیت سے مشہور ہیں۔\nابو عمر(2) کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائے، فتح خیبر و فتح مکہ اور حنین میں شریک ہوئے، ان سے مروی ہے: میں نے ابن حظل کو قتل کیا۔\nانہوں نے نبی کریم صلی اللہ علیہ وسلم، ابو بکر رضی اللہ عنہ سے روایت کی، ان سے ان کے بیٹے مغیرہ، ان کی پوتی منیہ بنت عبید بن ابی برزہ، ابو عثمان نہدی، ابو عالیہ، ابو وازع، ابو وضی، ابو منہال سیار بن سلامہ، ازرق بن قیس، ابو طالوت بن عبد السلام بن ابی حازم، ان کے والد اور دوسرے لوگوں نے روایت کی، ابن سعد کا قول ہے: مدینہ کے رہائشی تھے، پھر بصرہ فروش ہوئے اور خراسان میں جہاد کیا، دوسرے راویوں کا قول ہے: نہروان میں خوارج کے ساتھ قتال میں شریک تھے۔(3)\nانہوں نے خراسان میں اس کے بعد جہاد کیا، بعض کا قول ہے: وہ صفین اور نہروان میں سیدنا علی رضی اللہ عنہ کے ساتھ شریک ہوئے، یہ بطریق ثعلبہ بن ابی برزہ، بحوالہ ان کے والد نقل کیا ہے۔\nابن کلبی کا قول ہے: بصرہ میں فروش ہوئے، ان کا وہاں گھر تھا، پھر خراسان چلے گئے اور مرو فروش ہوئے پھر بصرہ لوٹ آئے، خلیفہ کا قول ہے: خراسان میں ۶۴ھ میں ابن زیاد کے بصرہ سے نکال دینے کے بعد وفات پائی۔ دوسرے راویوں کا قول ہے: سیدنا معاویہ رضی اللہ عنہ کی خلافت میں وفات پائی۔\nمیں کہتا ہوں: ابو احمد نے پہلے قول پر اعتماد کیا ہے، ابن حبان کا قول ہے: بعض نے کہا: وہ خلافت عبد الملک تک باقی رہے، اس پر بخاری(4) نے تاریخ اوسط میں، ان لوگوں کی فضیلت میں جنہوں نے ساٹھ(۶۰) سے ستر(۷۰) سال کی عمر کے درمیان وفات پائی، اس کا اعتماد کیا ہے۔\nمیں کہتا ہوں: اس کی تائید اس سے ہوتی ہے، جس پر محمد بن قدامہ وغیرہ نے اعتماد کیا ہے کہ وہ ۷۵ھ میں وفات پا گئے، اس وقت عبد الملک کی حکومت تھی، یزید ۶۴ھ کے شروع میں فوت ہو گیا۔ پھر اس کا بیٹا معاویہ کچھ دن والی بنا، پھر فتنہ کھڑا ہوا یہاں تک کہ سیدنا ابن زبیر حجاز، عراق، خراسان کے امیر بن گئے اور مروان شام کے امیر بنے، پھر وہ مصر کی طرف متوجہ ہوئے اور اس پر غلبہ پا لیا، پھر تھوڑا عرصہ زندہ رہے، اور رمضان میں اسی سال فوت ہو گئے۔ بخاری نے اپنی صحیح میں نقل کیا ہے کہ انہوں نے مروان، ابن زبیر اور بصرہ کے قراء کی برائی بیان کی جب یزید بن معاویہ کی موت کے بعد اختلاف پیدا ہوا، پھر قصہ ذکر کیا، جس کا حاصل یہ ہے کہ سب دنیا کے لیے لڑ رہے ہیں۔\nصحیح بخاری میں ہے کہ وہ اہواز میں خوارج کے قتال میں شریک ہوئے، اسماعیلی نے اپنے مستخرج میں اضافہ کیا ہے: مہلب بن ابی صفرہ کے ساتھ یہ ان کے بھائی عبد الملک سے پہلے بشر بن مروان کی بصرہ پر دور حکومت کا واقعہ ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۱۹)، استیعاب (۲۶۳۸)\n(2) استیعاب (۵۸/۳)\n(3) مختصر تاریخ دمشق (۱۵۱/۲۶)\n(4) تاریخ الکبیر (۱۱۸/۴)"}],[8694,"§۸۷۲۰ ۔ نضلہ بن عمرو(1)\nبن احبان بن حلان بن جحاف بن حبیب بن غفار غفاری، مکرم غفاری کے سوانح میں ان کا ذکر گزر چکا ہے۔\nابن سکن کا قول ہے: انہیں شرف صحابیت حاصل ہے، احمد، بغوی(2) اور ثابت نے دلائل میں اور ابن قانع نے بطریق ابن یونس محمد بن معن بن نضلہ بن عمرو نقل کیا ہے، مجھے میرے دادا نے، بحوالہ اپنے والد نضر بن نضلہ بتایا: نضلہ نبی کریم صلی اللہ علیہ وسلم سے مرس میں ملے تو گاہبن اونٹنی نے ان پر حملہ کر دیا، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے لیے برتن میں دودھ دوہا، آپ صلی اللہ علیہ وسلم نے پیا اور نضلہ نے برتن میں پیا اور کہا: یا رسول اللہ صلی اللہ علیہ وسلم! میں سات برتوں میں دودھ پیتا ہوں لیکن میرا پیٹ نہیں بھرتا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”مومن ایک انتڑی میں پیتا ہے....“(3)\nان کی ایک روایت میں ہے: میں نے اپنے دادا سے سنا، مجھ سے نضلہ بن عمرو نے بیان کیا: فرماتے ہیں: میں اپنی اونٹنی کے ساتھ آیا.... پھر اسی طرح ذکر کیا۔","",{"fn":"(1) استیعاب (۲۶۳۹)، تجرید (۱۰۷/۲)\n(2) مسند احمد (۳۳۶/۴)\n(3) مسلم (۵۳۴۵)، ابن ماجہ (۳۲۵۸)، ابن حبان (۵۲۳۵)، استیعاب (۵۸/۳)"}],[8695,"§۸۷۲۱ ۔ نضلہ انصاری(1)\nانہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے سعید بن مسیب نے روایت کیا، ابو عمر(2) نے مختصر ان کا ذکر کیا ہے، ابن ابی حاتم ان سے سبقت لے گئے ہیں، اس میں یہ اضافہ ہے: ان کی حدیث اس عورت کے بارے میں ہے، جس سے انہوں نے نکاح کیا، ابن قانع کو اس میں تردد ہے، فرماتے ہیں: نضلہ یا نضرہ۔","",{"fn":"(1) استیعاب (۲۶۴۰)\n(2) استیعاب (۵۹/۳)"}],[8696,"§۸۷۲۲ ۔ نضلہ انصاری\nدوسرے ہیں، جعفر بن نضلہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[8697,"§۸۷۲۳ ۔ النضیر بن حارث(1)\nبن علقمہ بن کلدہ عبدری، موسیٰ بن عقبہ نے مہاجرین حبشہ میں ان کا ذکر کیا ہے، اور یہ کہ وہ یرموک میں شہید ہوئے، رہے ابن اسحاق(2) تو انہوں نے مغازی میں فرمایا: مجھ سے عبد اللہ بن ابی بکر بن حزم وغیرہ نے بیان کیا، فرماتے ہیں: نضیر بن حارث ان لوگوں میں سے ہیں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے تالیف قلب کے لیے حنین میں سو اونٹ دیے، اسی طرح ابن سعد اور ابن شاہین کا قول ہے، ابن ماکولا(3) کا قول ہے: ان کی کنیت ابو الحارث ہے، قریش کے حکماء میں سے تھے، انہیں رہین کہا جاتا تھا، نضیر بن حارث کے بھائی ہیں، جسے رسول اللہ صلی اللہ علیہ وسلم نے صفراء مقام میں بدر سے واپسی کے بعد قتل کرنے کا حکم دیا تھا، ابن عبد البر کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے انہیں حنین کے دن سو اونٹ دینے کا حکم دیا، تو ان کے پاس بنو ذکل میں سے ایک شخص اس کی خوشخبری دینے آیا، انہوں نے کہا: اللہ کی قسم! میں نے انہیں مانگا نہیں تھا، انہوں نے یہ لے لیے اور دلی کو اس میں سے دس اونٹ دیے اور انہوں نے کہا: اللہ کی قسم! مجھے اسلام پر رشوت لینا پسند نہیں ہے، پھر مدینہ کی طرف چلے اور وہاں فروش ہوئے، پھر ہجرت کر کے شام چلے گئے، یرموک میں شریک تھے، وہیں قتل ہوئے۔ اسی طرح موسیٰ بن عقبہ، زبیر بن بکار اور ابن کلبی کا قول ہے: وہ یرموک میں شہید ہوئے، جو قصہ ابن عبد البر نے ذکر کیا ہے، اسے واقدی نے مغازی میں طویل نقل کیا ہے، پھر فرماتے ہیں: ہمیں ابراہیم بن محمد بن شرحبیل عبدری نے، بحوالہ اپنے والد بتایا۔ فرماتے ہیں: نضیر بن حارث لوگوں میں سب سے بڑے عالم تھے، وہ فرماتے: تمام تعریفیں اللہ تعالیٰ کے لیے ہیں جس نے ہمیں اسلام کے ساتھ عزت دی، اور ہم پر محمد صلی اللہ علیہ وسلم کے ساتھ احسان کیا، ہم اس پر فخر کریں گے جس پر ہمارے باپ دادا مرے، مجھے قریش کے ہر معاملے میں رائے کے لیے ساتھ رکھا جاتا، یہاں تک کہ فتح مکہ کا سال آیا اور آپ صلی اللہ علیہ وسلم حنین کی طرف نکلے، ہم بھی آپ صلی اللہ علیہ وسلم کے مقابلے میں نکلے، ہم چاہتے تھے کہ اگر محمد (صلی اللہ علیہ وسلم) کو شکست ہو تو ہم آپ کے خلاف مدد کریں، ایسا نہ ہو سکا، جب آپ صلی اللہ علیہ وسلم حنین میں پہنچے تو اللہ کی قسم! میں اسی حال میں تھا، مجھے آپ صلی اللہ علیہ وسلم کے بارے میں معلوم ہوا، آپ صلی اللہ علیہ وسلم مجھ سے خوشی سے ملے، اور فرمایا: ”نضیر“۔ میں نے کہا: میں حاضر ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: یہ بہتر موقع ہے جو تم نے حنین کے دن ارادہ کیا تھا“۔ فرماتے ہیں: میں آپ صلی اللہ علیہ وسلم کے پاس جلدی سے آیا۔” آپ صلی اللہ علیہ وسلم نے فرمایا: ”اب تم جو کچھ غور و فکر کرنا چاہتے ہو کر سکتے ہو“۔ میں نے کہا: میں دیکھ چکا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ! اس کی ثابت قدمی زیادہ کر“۔ فرماتے ہیں: اللہ کی قسم! جس نے آپ کو حق دے کر بھیجا، میرا دل دین کے اثبات اور حق کی نصرت میں گویا ایسا ہو گیا جیسے پتھر ہے۔\nپھر میں اپنے گھر آیا تو بنو ذکل کا ایک شخص آیا اس نے کہا: اے ابو الحارث، رسول اللہ صلی اللہ علیہ وسلم نے تمہیں سو اونٹ دینے کا حکم دیا ہے۔ مجھ اس میں سے دینا کیونکہ مجھ پر قرض ہے۔ فرماتے ہیں میں نے چاہا کہ اسے نہ لوں میں نے کہا، یہ تالیف قلب کے لیے ہے، اور میں نے اسلام پر رشوت نہیں چاہی، پھر میں نے کہا: نہ میں نے اسے طلب کیا ہے نہ اس کا سوال کیا ہے، پھر میں نے انہیں لے لیا اور دلی کو اس میں سے دس اونٹ دیے۔ ان نضیر کا مرتفع نامی بیٹا ہے، مرتفع ان کا لقب ہے اور محمد نام ہے، انہی کی طرف وہ کنوال منسوب ہے جسے بحر مرتفع کہا جاتا ہے یہ مکہ میں ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۲۳)، تجرید (۱۰۷/۲)\n(2) السیرۃ النبویۃ (۱۰۷/۴)\n(3) الاکمال (۲۸۶/۱)"}],[8698,"§۸۷۲۴ ۔ نظیر مزنی(1)\nابو موسیٰ نے ذیل میں بطریق ابو اسحاق مستملی ذکر کیا ہے، پھر بطریق محمد بن اسماعیل بن جعفر، بحوالہ عبد اللہ بن سلمہ، انہوں نے ابن شہاب سے، انہوں نے اسماعیل بن ابی حکیم، انہوں نے نظیر مزنی یا مدنی سے روایت کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ”بے شک اللہ تعالیٰ جب یہ آیت سنتے ہیں ﴿وَلَمْ يَكُنِ الَّذِينَ كَفَرُوا﴾ تو فرماتے ہیں: ”میرے بندے کو خوشخبری دے دو، میری عزت کی قسم! میں تمہیں دنیا اور آخرت کے کسی حال میں نہ بھولوں گا“۔(2)\nمستملی کا قول ہے: ابن ترخان سے ان کا ذکر کیا گیا تو وہ انہیں نہ پہچان سکے اور فرمایا کہ یہ حدیث لا تعداد سندوں سے مروی ہے۔ عبد اللہ بن سلمہ بے حد متروک راوی ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۲۴)، تجرید (۱۰۷/۲)\n(2) اسد الغابہ (۵۲۲۶)، تجرید (۱۰۷/۲)"}],[8699,"§۸۷۲۵ ۔ نعامۃ الضبی(1)\nیزید کے والد ہیں، دارقطنی رحمہ اللہ کا قول ہے: ابو بشیر مروزی نے بطریق حبان عبدری، بحوالہ یزید بن نعامۃ الضبی، عن ابیہ ان کا ذکر کیا ہے، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم کے سامنے کھانا رکھا جاتا تو فرماتے: ”اے اللہ! تو پاک ہے، کیسا اچھا ہے جو تو نے ہمیں آزمایا، تو پاک ہے، تو نے ہمیں بہت زیادہ عطا فرمایا، تو پاک ہے، تو نے ہمیں بڑی عافیت دی“۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) جامع المسانید والسنن (۱۴۱/۱۲)"}],[8700,"§۸۷۲۶ ۔ نعم\nنبی کریم صلی اللہ علیہ وسلم نے ان کا نام بدل کر عبد اللہ رکھا، ان کا ذکر گزر چکا ہے۔"],[8701,"§۸۷۲۷ ۔ نعمان بن اسود کندی\nابن ابی الجون ہیں، ان کا ذکر آئے گا۔"],[8702,"§۸۷۲۸ ۔ نعمان بن اشیم اشجعی(1)\nابو ہند، نعیم بن ابی ہند کے والد ہیں، اپنی کنیت سے مشہور ہیں، خلیفہ بن خیاط کا قول ہے: ان کا نام رافع بن اشیم ہے، کونیوں میں ان کا شمار ہے۔ انہیں نعمان، مولیٰ اشجح کہا جاتا تھا۔\nبخاری رحمہ اللہ، ابو حاتم،(2) ابن سکن، ابو عمر(3) کا قول ہے، انہیں شرف صحابیت حاصل ہے، کوفہ میں فروش ہوئے، بخاری(4) اور ابن مندہ نے بطریق رافع بن نعمان، مولیٰ بنو نضر نقل کیا ہے کہ مجھے نعیم بن ابی ہند نے بتایا، فرماتے ہیں: میرے والد موت کے وقت بے چین ہوئے، ان پر نزع طاری ہو گیا تو فرمایا: اے بیٹے! مجھے خوف ہے کہ میرا کوئی شان باقی نہ رہے، میرے بستر کو گھر کے کونے میں لے جاؤ، لہذا ہم نے ایسا ہی کیا، وہ فوت ہو گئے، فرماتے ہیں: میرے والد نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ابن سکن نے بطریق سلمہ بن نہیط حدیث نقل کی ہے کہ مجھ سے ابو نعیم بن ابی ہند نے بیان کیا، فرماتے ہیں میں نے اپنے والد اور چچا کے ساتھ حج کیا، یا انہوں نے مجھ سے کہا: تم سرخ اونٹ والے صاحب کو خطبہ دیتے ہوئے دیکھ رہے ہو؟ وہ رسول اللہ صلی اللہ علیہ وسلم ہیں، اسی طرح ابو ہند کے سوانح میں ان کا ذکر کیا ہے۔ اس بنا پر کہ ابو نعیم سے مراد ابو ہند ہیں، وہ غلطی ہے جو لفظی غلطی اور تبدیلی سے پیدا ہوئی، صحیح یہ ہے: بحوالہ سلمہ، کہ مجھ سے میرے والد یا نعیم بن ابی ہند نے ان کے حوالے سے بیان کیا ہے، فرماتے ہیں: میں نے حج کیا.... پھر حدیث ذکر کی، ان کے قول میں عنہ کی ضمیر سلمہ کے والد کے لیے ہے، حدیث کو روایت کرنے والے نبیط بن شریط ہیں، ابو نعیم کے والد نہیں، ابن مندہ نے حدیث کو بطریق سلمہ نقل کیا ہے، فرماتے ہیں: مجھ سے میرے والد ابو نعیم بن ابی ہند نے اپنے والد کے حوالے سے نقل کیا.... پھر اسے ذکر کیا، ان کے قول عن ابیہ سے مراد سلمہ کے والد ہیں، نعیم کے والد نہیں، ابو نعیم نے اس پر تنبیہ کی ہے۔ اور بطریق سلمہ نقل کیا ہے کہ مجھ سے میرے والد یا نعیم نے، بحوالہ میرے والد نقل کیا ہے، فرماتے ہیں: میں نے حج کیا، یہی صحیح ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۲۴)، استیعاب (۲۶۴۴)، تجرید (۱۰۷/۲)\n(2) جامع المسانید والسنن (۱۴۲/۱۲)\n(3) استیعاب (۵۹/۳)\n(4) تاریخ الکبیر (۷۶/۸)"}],[8703,"§۸۷۲۹ ۔ نعمان بن اوس معافری\nنبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، سید ابو علی ہجری کا قول ہے، میں نے مغلطائی کی تحریر سے اسے نقل کیا ہے۔"],[8704,"§۸۷۳۰ ۔ نعمان بن بزرج یمانی(1)\nابن حبان کا قول ہے: بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے۔\nمیں کہتا ہوں: مخضرمیوں میں مشہور ہیں، قسم ثالث میں ان کا ذکر آئے گا۔","",{"fn":"(1) تجرید (۱۰۷/۲)"}],[8705,"§۸۷۳۱ ۔ نعمان بن بشیر(1)\nبن سعد بن ثعلبہ بن جلاس بن زید انصاری خزرجی، ان کا تمام نسب حرف باء میں ان کے والد کے سوانح میں گزر چکا ہے، ان کی کنیت ابو عبد اللہ ہے، وہ مشہور ہیں، انہیں اور ان کے والد کو شرف صحابیت حاصل ہے، واقدی رحمہ اللہ کا قول ہے: ہجرت کے چودہ ماہ بعد انصار کے گھرانوں میں سے پیدا ہونے والے پہلے بچے ہیں۔(2)\nابن زبیر کے حوالے سے مروی ہے: نعمان بن بشیر مجھ سے چھ ماہ بڑے ہیں انہوں نے نبی کریم صلی اللہ علیہ وسلم، حضرت خالد بن عبد اللہ بن رواحہ، سیدنا عمر، سیدہ عائشہ رضی اللہ عنہا سے روایت کیا، ان سے ان کے بیٹے محمد، ان کے مولا سالم، عروہ، شعبی، سعیدی، ابو قلابہ، خثیمہ بن عبد الرحمن، سماک بن حرب اور دوسرے لوگوں نے روایت کی۔\nابو سحر نے، بحوالہ شعبہ بن عبد العزیز نقل کیا ہے، وہ سیدنا فضالہ بن عبید کے بعد دمشق کے قاضی تھے، سماک بن حرب کا قول ہے: سیدنا معاویہ رضی اللہ عنہ نے انہیں کوفہ کا والی مقرر کیا، جن لوگوں کو میں نے سنا وہ ان میں سب سے بڑے خطیب تھے، ہشام کا قول ہے: سیدنا معاویہ رضی اللہ عنہ نے انہیں کوفہ کے بجائے حمص کا والی بنا دیا، اور کوفہ کو حضرت عبید اللہ بن زیاد کی نگرانی میں دے دیا، وہ اس وقت شام میں تھے جب یزید بن معاویہ کا انتقال ہو گیا اور معاویہ بن یزید خلیفہ بنے، ان کا جلد ہی انتقال ہو گیا تو سیدنا نعمان نے سیدنا ابن زبیر کی بیعت کی دعوت دی پھر اپنی بیعت کی طرف بلایا، مروان بن حکم نے ضحاک بن قیس کے بعد ان پر حملہ کیا اور نعمان بن بشیر کو قتل کر دیا، یہ ۶۵ھ کا واقعہ ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۳۰)، استیعاب (۲۶۴۳)، تجرید (۱۰۷/۲)\n(2) جامع المسانید والسنن (۱۴۵/۱۲)"}],[8706,"§۸۷۳۲ ۔ نعمان بن بیبا\nضبی، مستغفری نے ان کا ذکر کیا ہے، اور بطریق سعد بن عبد اللہ بن حارث بن خلیفہ، عن ابیہ، عن جدہ، نعمان بن بیبا نقل کیا ہے، فرماتے ہیں: ہم نبی کریم صلی اللہ علیہ وسلم کے پاس بنو ضبیب کی ایک جماعت کے ساتھ آئے اور آپ سے سوال کیا، آپ صلی اللہ علیہ وسلم نے ہماری حاجت کو پورا فرمایا.... پھر حدیث کا ذکر کیا(1) اس کی اسناد مجہول ہیں۔","",{"fn":"(1) اسد الغابہ (۲۳۶/۴)"}],[8707,"§۸۷۳۳ ۔ نعمان بن ثابت\nبن نعمان، ابو الضیاح، اپنی کنیت سے مشہور ہیں، عنقریب ان کا ذکر آئے گا، بعض کا قول ہے: ان کا نام عمیر ہے۔"],[8708,"§۸۷۳۴ ۔ نعمان بن جبلہ\nبن وائل بن قیس بن بکر بن عامر بن جلاج بن عوف بن بکر بن عقدہ عذری، طبری نے ان کا ذکر کیا ہے، فرماتے ہیں: وہ اور ان کے بھائی عبد عمرو، نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، عبد عمرو کا نام بکر تھا، نعمان جاہلیت میں رئیس تھے، یہ وہی ہیں، جنہوں نے بشیر بن ابو حازم کو قید کر لیا اور انہیں اوس بن حارثہ طائی کو دے دیا، کیونکہ انہوں نے اوس اور اس کی ماں کی ہجو کی تھی، قصہ مشہور ہے، نابغہ ذبیانی نے نعمان مذکور کی مدح کی ہے۔"],[8709,"§۸۷۳۵ ۔ نعمان بن جزء\nبن نعمان بن قیس بن مالک بن سعد بن ذھل بن نطیف بن عبد اللہ بن ناجیہ بن مراد مرادی، پھر غطیفی، ابن یونس(1) نے ان کا ذکر کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے، فتح مصر میں شریک تھے، ان کی کوئی روایت معلوم نہیں، ان کے ایک بھائی ہیں جنہیں ہانی کہا جاتا ہے، فتح مصر میں شریک تھے، ان دونوں کو شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابہ (۲۳۶/۴)"}],[8710,"§۸۷۳۶ ۔ نعمان بن ابی جعال ضبیبی\nرفاعہ بن زید کے قبیلے سے ہیں۔ ابن اسحاق(1) نے اسلام لانے والوں میں ان کا ذکر کیا ہے، سیدنا زید بن حارثہ رضی اللہ عنہ کے ارض حمی میں بنو جذام سے جہاد کرنے کے بعد وہ نبی کریم صلی اللہ علیہ وسلم کے پاس وفد میں آئے۔","",{"fn":"(1) السیرۃ النبویۃ (۱۹۷/۴)"}],[8711,"§۸۷۳۷ ۔ نعمان بن ابی الجون\nاسود بن شراحیل بن حجر بن معاویہ کندی ہیں، طبری نے، بحوالہ واقدی ان کا ذکر کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم کے پاس مسلمان ہو کر آئے اور کہا: میں آپ کا عرب کی سب سے خوبصورت لڑکی سے نکاح کروں گا، وہ اپنی بہن اسماء کا ارادہ رکھتے تھے، پھر ان کے نکاح اور جدائی کی حدیث نقل کی، حاکم نے بطریق واقدی، بحوالہ عبد الواحد بن ابی عوف نقل کیا ہے وہ فرماتے ہیں: نعمان بن ابی جون آئے پھر ان کا ذکر کیا اور یہ اضافہ کیا: وہ اور ان کے والد شریہ کے قریب فروش ہوئے تھے، فرماتے ہیں: اسماء کی شادی اپنے چچا زاد سے ہوئی تھی، وہ وفات پا گئے، وہ آپ سے نکاح کرنے کی رغبت رکھتی ہیں اور آپ کی طرف نکاح کا پیغام بھیجا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: بارہ اوقیہ اور نصف پر ان کا مجھ سے نکاح کر دو، انہوں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! ان کے لیے مہر میں کمی نہ کیجئے: آپ صلی اللہ علیہ وسلم نے فرمایا: ”میری ازواج میں سے کسی کا مہر اس سے زیادہ نہ تھا، اور نہ میری بیٹیوں میں سے کسی کا مہر اس سے زیادہ ہے“۔ نعمان نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ کے فضل میں نمونہ ہے۔ اپنے گھر والوں کی طرف کسی کو بھیج دیجئے، آپ صلی اللہ علیہ وسلم نے ابو اسید ساعدی کو ان کے ساتھ بھیج دیا، جب انہیں معلوم ہوا تو اپنے کمرے میں چلی گئیں اور انہیں اندر آنے کی اجازت دی، سیدنا ابو اسید نے فرمایا: نبی کریم صلی اللہ علیہ وسلم کی ازواج کو مردوں میں سے کسی نے نہیں دیکھا، انہوں نے کہا: پھر مجھے بتا دیجئے، انہوں نے کہا: اپنے محرم مردوں کے سوا دوسرے کسی مرد سے بات نہ کریں، سیدنا ابو اسید فرماتے ہیں: میں نے انہیں ایک پالکی میں سوار کرایا اور انہیں لے کر مدینہ آیا اور بنو ساعدہ کے ہاں اتارا، ان کے پاس قبیلہ کی عورتیں خوشی سے آئیں، وہ نہایت خوبصورت تھیں، پھر ان کے پاس ایک عورت آئی اور ان سے کہا: تم بادشاہوں میں سے ہو، اگر تم چاہتی ہو کہ رسول اللہ صلی اللہ علیہ وسلم کے ہاں مرتبہ حاصل کرو تو آپ صلی اللہ علیہ وسلم سے پناہ مانگ لینا.... (الحدیث)"],[8712,"§۸۷۳۸ ۔ نعمان بن حارثہ انصاری(1)\nبعض کا قول ہے: پہلی بیعت عقبہ میں شریک ہوئے، ابن مندہ(2) نے، اور ابو نعیم نے بطریق محمد بن ابراہیم بن یسار بحوالہ زہری نقل کیا ہے، فرماتے ہیں: جب مشرکین کی رسول اللہ صلی اللہ علیہ وسلم پر تکالیف بڑھ گئیں تو منیٰ میں جمرہ عقبہ کے پاس انصار کے چھ افراد ملے، سیدنا نعمان بن حارثہ نے کہا: اللہ تعالیٰ کے حکم کو پورا کرنے میں، میں آپ سے بیعت کرتا ہوں یا رسول اللہ صلی اللہ علیہ وسلم! اگر آپ چاہیں تو ہم اہل منیٰ پر اپنی تلواروں سے ٹوٹ پڑیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے اس کا حکم نہیں دیا گیا“۔\nسند میں غیر معروف راوی ہیں، ابن اسحاق اور موسیٰ بن عقبہ نے ان نعمان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابہ (۵۲۳۶)، تجرید (۱۰۸/۲)\n(2) اسد الغابہ (۴۴۲/۶)"}],[8713,"§۸۷۳۹ ۔ نعمان بن ابی خذمہ(1)\nبن نعمان بن امیہ بن برک بن ثعلبہ بن عمرو بن عوف انصاری اوسی، موسیٰ بن عقبہ اور ابن اسحاق(2) وغیرہ نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔ ابن سعد(3) نے، بحوالہ واقدی اور ابو معشر نقل کیا ہے فرماتے ہیں: نعمان بن خذمہ، ابو خذمہ خاء کے ساتھ ہے۔ اور، بحوالہ ابو عمارہ حاء کے ساتھ ہے، فرماتے ہیں: ہم نے انصار کے نسب میں دیکھا تو ہمیں کوئی ایسا شخص نہیں ملا، جس کی یہ کنیت ہو۔\nمیں کہتا ہوں: ابن کلبی نے ان کا ذکر کیا ہے، جیسا کہ ابن عمارہ کا قول ہے، اور ان کی کنیت ذکر نہیں کی، فرماتے ہیں: بدر میں شریک ہوئے۔","",{"fn":"(1) اسد الغابہ (۵۲۳۸)، استیعاب (۲۶۴۴)، تجرید (۱۰۸/۲)\n(2) السیرۃ النبویۃ (۲۶۰/۲)، استیعاب (۶۸/۳)\n(3) طبقات الکبریٰ (۴۵/۳)"}],[8714,"§۸۷۴۰ ۔ نعمان و مالک\nیہ دونوں خلف بن دارم بن اسلم بن افصی خزاعی کے بیٹے ہیں، ابن سعد(1) اور بغوی نے ان کے حوالے سے نقل کیا ہے، فرماتے ہیں: وہ دونوں اُحد کے دن رسول اللہ صلی اللہ علیہ وسلم کے جاسوس تھے، وہ دونوں شہید ہو گئے ہم نے انہیں ایک قبر میں دفن کیا۔","",{"fn":"(1) طبقات الکبریٰ (۱۷۶/۴)"}],[8715,"§۸۷۴۱ ۔ نعمان بن رازیہ\nازدی پھر لہبی، ازد کے ناظم اور ان کے علمبردار ہیں، بخاری(1) کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سنا، ابن مندہ کا قول ہے: بخاری نے وحدان میں صحابہ میں ان کا ذکر کیا ہے، ابن ابی حاتم(2) اور ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، احمد بن محمد بن عیسیٰ نے حمص میں آنے والے صحابہ میں ان کا ذکر کیا ہے۔\nابن قانع، ابن سکن نے بطریق محمد بن ولید زبیدی، بحوالہ محمد بن صالح بن شرح، انہوں نے اپنے والد سے نقل کیا ہے کہ انہوں نے ازد کے ناظم کو دیکھا، انہیں نعمان بن رازیہ کہا جاتا تھا، فرماتے ہیں: میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! ہم جاہلیت میں شگون لیتے تھے یہاں تک کہ اللہ تعالیٰ نے اسلام کو ظاہر فرمایا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اسلام نے اس کی سچائی کی نفی کی ہے، تم میں سے کسی کو سفر سے نہ روکیں“۔\nیہ ابن سکن کے الفاظ ہیں، جبکہ ابن قانع کے الفاظ یہ ہیں: یہ اسلام میں سب سے زیادہ اچھی بات ہے.... آخر تک، پہلا قول زیادہ صحیح ہے۔ ابن سکن کا قول ہے: مجھے نبی کریم صلی اللہ علیہ وسلم سے ان کی کوئی اور حدیث نہیں ملی۔\nمیں کہتا ہوں: یہ ابن ابی حاتم رازی کے قول پر رد ہے، ان سے علم مروی نہیں، واقدی نے مغازی میں، بحوالہ ابو معشر وغیرہ ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے جب حنین کے بعد طائف جانے کا ارادہ کیا تو طفیل بن عمرو دوسی کو پیغام بھیجا اور انہیں حکم دیا کہ وہ عمرو بن حممہ کے بت کو گرا دیں اور اپنی قوم سے مدد طلب کریں۔ وہ طائف گئے، ان کے ساتھ چار سو افراد تھے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اے ازد کی جماعت! تمہارا جھنڈا کون لے گا“، طفیل نے کہا: جو جاہلیت میں علمبردار تھا یعنی نعمان بن رازیہ یہی۔","",{"fn":"(1) تاریخ الکبیر (۷۵/۴)\n(2) جامع المسانید والسنن (۱۴۳/۱۲)"}],[8716,"§۸۷۴۲ ۔ نعمان بن ریعی\nبعض کا قول ہے: وہ ابو قتادہ بن ربعی انصاری کا قول ہے: مشہور یہ ہے کہ ان کا نام حارث ہے، کنیتوں میں ان کا ذکر آئے گا۔"],[8717,"§۸۷۴۳ ۔ نعمان بن زید\nبن اکال، ان کے بیٹے سعد کے سوانح میں ان کا ذکر گزر چکا ہے، ابن کلبی نے ذکر کیا ہے کہ مذکورہ قصہ سعد کا ہے، جبکہ یہ نعمان کا ہے۔"],[8718,"§۸۷۴۴ ۔ نعمان بن سنان انصاری(1)\nمولی بنو عبید بن عدی بن غنم بن کعب بن سلمہ، موسیٰ بن عقبہ ابن اسحاق(2) وغیرہ نے بدری صحابہ میں ان کا ذکر کیا ہے، ان سے مروی کوئی روایت نہیں۔","",{"fn":"(1) اسد الغابہ (۵۲۴۴)\n(2) السیرۃ النبویۃ (۲۵۸/۲)"}],[8719,"§۸۷۴۵ ۔ نعمان بن سفیان\nبن خالد بن عوف، بنو سہم سے ہیں، ابن سعد نے، بحوالہ واقدی ذکر کیا ہے کہ وہ ان تین افراد میں سے تھے جنہیں رسول اللہ صلی اللہ علیہ وسلم نے غزوہ حمراء الاسد میں مشرکین کے پیچھے روانہ کیا تھا، سلیط بن سفیان کا ذکر پہلے گزر چکا ہے، لگتا ہے یہ ان کے بھائی ہیں، سیدنا نعمان بن خلف بن عون کا ابھی ذکر گزر چکا ہے۔"],[8720,"§۸۷۴۶ ۔ نعمان بن شریک شیبانی(1)\nمفروق بن عمرو کے سوانح میں ان کا ذکر گزر چکا ہے، ذہبی نے تجرید(2) میں یہ یقین سے لکھا ہے کہ انہیں وفد کے ساتھ آنے کی سعادت حاصل ہے، رہے ابو نعیم، تو انہوں نے نعمان کے لیے صحابی ہونا ثابت کیا ہے اور، بحوالہ مفروق اس کی نفی کی ہے۔","",{"fn":"(1) تجرید (۱۰۸/۲)\n(2) تجرید (۱۴۶)"}],[8721,"§۸۷۴۷ ۔ نعمان بن عبد عمرو(1)\nبن مسعود بن کعب بن عبد اشہل بن حارث بن دینار بن نجار انصاری خزرجی، ابن حبان کا قول ہے: انہیں شرف صحابیت حاصل ہے، ابن اسحاق(2) نے بدر میں شریک ہونے والوں اور اُحد میں شہید ہونے والوں میں ان کا ذکر کیا ہے، اسی طرح ابن کلبی کا قول ہے، ان کے بھائی ضحاک کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۱۶)، استیعاب (۲۶۴۷)\n(2) السیرۃ النبویۃ (۲۶۲/۲)"}],[8722,"§۸۷۴۸ ۔ نعمان بن عبید\nعبید کو مقرن بن اوس بن مالک انصاری کہا جاتا تھا، ابن قداح نے انصار کے نسب میں ان کا ذکر کیا ہے، فرماتے ہیں: وہ یمامہ میں شہید ہوئے۔"],[8723,"§۸۷۴۹ ۔ نعمان بن عجلان(1)\nبن نعمان بن عامر بن زرلیق انصاری زرقی، ابو عمر(2) کا قول ہے: انصار کے خطیب اور شاعر تھے، یہ وہی ہیں جنہوں نے سیدنا حمزہ بن عبد المطلب کے شہید ہونے کے بعد ان کی زوجہ خولہ بنت قیس سے نکاح کیا، وہ فخر سے اپنی قوم کے بارے میں یہ اشعار کہتے ہیں:\n”قریش سے کہہ دو، ہم مکہ اور حنین کے دن والے ہیں، بدر کے شہسوار ہیں، ہم نے نبی کریم صلی اللہ علیہ وسلم کی مدد کی اور پناہ دی، ہم راتوں کے پھیر اور بڑے کاموں سے ڈرے نہیں، ہم نے ہجرت کرنے والوں کو خوش آمدید کہا اور انہیں کہا کہ تم فقر سے مامون ہو گئے ہو، تمہارے لئے ہم اپنے ماموں اور گھروں کو تقسیم کرتے ہیں جیسا اونٹوں کا گوشت نصف نصف تقسیم ہوتا ہے“۔\nابن سکن اور ابن مندہ نے بطریق یزید بن ہارون، بحوالہ نعمان بن عجلان نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور مجھے بخار تھا، آپ صلی اللہ علیہ وسلم نے پوچھا: ”اے نعمان! تمہارا کیا حال ہے؟“ میں نے کہا: مجھے بخار ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: ”اے اللہ جلد شفا دے....“ الحدیث\nابن سکن کا قول ہے: مجھے ان کی اس کے علاوہ کوئی اور حدیث نہیں ملی، میرے خیال میں وہ مرسل ہے۔\nمیں کہتا ہوں: عیسیٰ بہت ضعیف راوی ہے، مبرد(3) نے ذکر کیا ہے کہ سیدنا علی رضی اللہ عنہ بن ابو طالب نے ان نعمان کو بحرین کا والی بنایا تو بنو زریق میں سے جو بھی ان کے پاس جاتا، اسے دیتے جاتے، ان کے بارے میں ابو اسود دؤلی نے کہا:\n”میں دیکھتا ہوں کہ فتنے نے لوگوں کو تم سے غافل کر دیا ہے، اے بنو زریق لوٹری کی طرح مال لوٹو، ابن عجلان وہ شخص ہے ہم جانتے ہو، اللہ کے مال کو ایسے خرچ کر رہا ہے، جیسے لوٹ مار اچھی ہو“۔","",{"fn":"(1) استیعاب (۲۶۴۷)، تجرید (۱۰۸/۲)\n(2) استیعاب (۶۴/۳)\n(3) الکامل (۱۸۴/۱)"}],[8724,"§۸۷۵۰ ۔ نعمان بن عدی(1)\nبن نضلہ عدوی، ان کے والد عدی کے سوانح میں ان کا ذکر گزر چکا ہے۔ وہ مہاجرین حبشہ میں سے ہیں، ان نعمان کو سیدنا عمر رضی اللہ عنہ نے میسان کا والی بنایا، انہوں نے یہ مشہور اشعار کہے:\n”مجھ کو یہ بات کون سنائے گا کہ اس کا شوہر میسان میں شیشوں کے پیالوں اور حتم کے برتنوں میں شراب پیتا ہے، جب چاہتا ہے، بستی کے کسان اسے گانا سناتے ہیں، جھانج والی ہر اونچی جگہ پر بلند آواز سے گاتی ہیں، اگر تم دونوں میرے شراب کے ساتھی ہو تو بڑے جام سے مجھے پلاؤ چھوٹے ٹوٹے ہوئے جام سے مجھے نہ پلانا، شاید امیر المومنین کو ہمارا ٹوٹے ہوئے محل میں مل بیٹھ کر شراب پینا برا لگے“\nسیدنا عمر رضی اللہ عنہ کو یہ بات معلوم ہوئی تو ان کی طرف لکھا: مجھے تمہارے شعر پہنچے ہیں، اللہ کی قسم! تم نے میرے ساتھ برا کیا ہے، پھر انہیں معزول کر دیا۔ جب آئے اور کہنے لگے: اللہ کی قسم! ایسا کچھ بھی نہیں، یہ صرف شعر کی لفاظی ہے، سیدنا عمر رضی اللہ عنہ نے فرمایا: میں تمہیں سچا سمجھتا ہوں۔ لیکن اللہ کی قسم! میں تمہیں اپنی طرف سے والی نہیں بناؤں گا۔\nحضرت زبیر بن بکار نے، بحوالہ اپنے چچا مصعب فرمایا: ابن عمر رضی اللہ عنہ نے نعیم بن نحام کو اس کی بیٹی کے لیے نکاح کا پیغام دیا، انہوں نے کہا: میں اپنے گوشت کو ایسی حالت میں نہیں چھوڑوں گا، جس کو پھینک دیا جائے۔ میرا ایک ناتواں بھتیجا ہے، اسے کوئی بھی نکاح کے لیے اپنی بیٹی نہیں دیتا۔ اس کی والدہ عاتکہ بنت حذیفہ بن غانم کی خواہش سیدنا ابن عمر رضی اللہ عنہ کے ساتھ اپنی بیٹی کا نکاح کرنے کی تھی، نعیم نے نعمان بن عدی سے اس کا نکاح کر دیا، وہ یتیم اور اس کی پرورش میں تھا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”عورتوں سے ان کی اولاد کے بارے میں مشورہ لو“۔ نعیم(2) نے کہا: وہ اس وجہ سے چاہتی تھی کہ ابن عمر رضی اللہ عنہ نے اسے مال دیا تھا، وہ اسے میرے مال میں سے مل جائے گا۔","",{"fn":"(1) اسد الغابہ (۵۲۴۸)، استیعاب (۲۶۴۹)، تجرید (۱۰۸/۲)\n(2) السیرۃ النبویۃ (۲۶۰/۱) اسد الغابہ (۲۳۹/۴)"}],[8725,"§۸۷۵۱ ۔ نعمان بن عصر(1)\nبن ربیخ بن حارث بن آدیم بن امیہ بلوی، بنو معاویہ بن مالک بن عمرو بن عوف کے حلیف ہیں، انصاری ہیں، ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے، فرماتے ہیں: بنو معاویہ میں سے نعمان بلوی ان کے حلیف ہیں، ابن عقبہ، ابو معشر وغیرہ نے ان کے والد کا نام لیا ہے۔\nاس کے لکھنے میں اختلاف ہے، اکثر کا قول ہے: دو زبر کے ساتھ ہے۔ واقدی کا قول ہے: زبر اور سکون کے ساتھ، ابن ماکولا(3) کا قول ہے: مرتدین سے جہاد کرتے ہوئے شہید ہوئے، انہیں طلیحہ بن خویلد اسدی نے شہید کیا۔","",{"fn":"(1) السیرۃ النبویۃ (۲۶۱/۲)\n(2) السیرۃ النبویۃ (۲۵۲/۲) (۲۶۵/۲)\n(3) الاکمال (۱۷۲/۲)"}],[8726,"§۸۷۵۲ ۔ نعمان بن عمرو بن انسان(1)\nابن خذہ بن عمرو بن آمیہ بن عامر بن بیاضہ انصاری، اُحد میں شریک ہوئے، ان کے پاس مسلمانوں کا جھنڈا تھا، یہ ابن کلبی کا قول ہے: اسے رشاطی نے نقل کیا ہے، فرماتے ہیں: ابن عبد البر اور ابن فتحون نے ان کا ذکر نہیں کیا۔","",{"fn":"(1) تجرید (۱۰۸/۲)"}],[8727,"§۸۷۵۳ ۔ نعمان بن عمرو بن رفاعہ(1)\nبن حارث بن سواد بن غنم بن مالک بن نجار انصاری، ابن اسحاق(2) نے بدر میں شریک ہونے والوں میں ان کا ذکر کیا ہے۔ ابن درید کی کتاب اشتقاق میں ہے کہ وہ بدر میں شریک ہوئے اور اُحد میں شہید ہوئے۔ لیکن تصغیر میں ہے کہ وہ بدر میں شریک ہوئے اور اُحد میں شہید ہوئے، لیکن تصغیر کے ساتھ ان کا ذکر کیا ہے، فرماتے ہیں: نعیمان بن عمرو، ان کا نسب بیان نہیں کیا، تو بعض کو گمان ہوا کہ وہ نعیمان مزاح کرنے والے ہیں، ایسا نہیں جیسا کہ ان کے سوانح میں آئے گا۔","",{"fn":"(1) استیعاب (۲۶۵۱)\n(2) السیرۃ النبویۃ (۲۶۱/۲)"}],[8728,"§۸۷۵۴ ۔ نعمان بن عمرو بن عمیر(1)\nیمانی، ابن عساکر نے مبہمات التعریف والا علام کے ذیل میں مسعود، ابن عبد یا لیل، اولاد عمرو بن عمیر بن عوف ثقفی وغیرہ کے ساتھ ان کا ذکر اس آیت مبارکہ کے شان نزول میں کیا ہے: ﴿اے ایمان والو! اللہ سے ڈرو اور سود میں سے جو باقی رہ گیا ہے اسے چھوڑ دو﴾۔ تفسیر سعید کی طرف اس کی نسبت کی ہے، کہ انہوں نے ان کے ساتھ ان کا ذکر کیا ہے۔ بلال نامی شخص کے آخر میں اس کا کچھ قصہ آئے گا، اسی طرح مسعود بن عمرو کے سوانح میں اس میں سے کچھ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۵۲۵۰)"}],[8729,"§۸۷۵۵ ۔ نعمان بن عمرو بن مقرن\nبغوی نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور بطریق جریر، بحوالہ نعمان بن عمرو بن مقرن، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان کو گالی دینا گناہ ہے اور اس کو قتل کرنا کفر ہے“۔(1) اسے ابن شاہین نے بطریق زیاد بکائی، بحوالہ نعمان بن مقرن نقل کیا ہے، پہلا قول زیادہ صحیح ہے۔\nابن شاہین نے بطریق یحییٰ بن عطیہ، بحوالہ عمرو بن نعمان بن مقرن نقل کیا ہے، فرماتے ہیں: مزینہ سے کچھ لوگ آئے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے فقر کا اظہار کیا کہ ان کے پاس اموال نہیں، جس کی زکوٰۃ ادا کریں۔ سیدنا نعمان بن مقرن اپنی بکریوں کو ہانکتے ہوئے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، ان کے بارے میں یہ آیت نازل ہوئی ﴿دیہاتیوں میں سے بعض ایسے ہیں جو اللہ اور آخرت کے دن پر ایمان لاتے ہیں...﴾ (الآیۃ)(2) عمرو بن نعمان ان کے چچا زاد ہیں جن کے حالات ذکر کے جارہے ہیں، بعض کا قول ہے: یہ نام غلطی سے راوی سے بدل گیا، بعض کا قول ہے: نعمان کی یہ حدیث نبی کریم صلی اللہ علیہ وسلم سے مرسل ہے۔","",{"fn":"(1) بخاری (۴۸) ترمذی (۵۲) (۱۹۸۳)\n(2) سورۃ التوبۃ الآیۃ (۹۹)"}],[8730,"§۸۷۵۶ ۔ النعمان بن عوف\nبن نعمان شیبانی، سیف نے فتوح میں ان کا ذکر کیا ہے کہ سیدنا خالد بن ولید رضی اللہ عنہ سیدنا ابو بکر صدیق رضی اللہ عنہ کے پاس قیدیوں کا خمس لائے، مثنیٰ ابن حارثہ نے انہیں فتح عراق میں لشکر کے ایک حصے کا امیر بنایا۔ طبری(1) نے اپنی تاریخ میں ان کا ذکر کیا ہے۔ پہلے گزر چکا ہے کہ فتوح کے زمانے میں وہ صرف صحابہ رضی اللہ عنہم کو امیر بناتے تھے۔","",{"fn":"(1) طبری فی تاریخہ (۳۸۲/۳)"}]])